insert into public.site_content (id, data)
values (1, '{"BANK": [{"src": "October US 2024", "type": "mc", "stem": "In the figure, line \\(q\\) is parallel to line \\(r\\), and both lines are intersected by line \\(s\\). If \\(y=2x+9\\), what is the value of \\(x\\)?", "fig": {"lines": [[30, 70, 330, 70, "q", 338, 75], [30, 160, 330, 160, "r", 338, 165], [130, 200, 226, 34, "s", 231, 28]], "arcs": [[205, 70, 0.5, -0.866, -1, 0, "61&deg;"], [153, 160, 0.5, -0.866, -1, 0, "y"]]}, "figNote": true, "opts": ["26", "35", "55", "65"], "ans": "A", "rat": "The 61&deg; angle (upper-left at line \\(q\\)) and \\(y\\) (upper-left at line \\(r\\)) are <b>corresponding angles</b>, so \\(y=61\\). Then \\(2x+9=61\\), so \\(2x=52\\) and \\(x=26\\).", "skill": "Lines, angles, and triangles"}, {"src": "May 2024", "type": "spr", "stem": "In the figure shown, line \\(r\\) is parallel to line \\(s\\), and both lines are intersected by line \\(t\\). If \\(x=2w+24\\), \\(y=5w+29\\), and \\(7w=a\\), where \\(a\\) is a constant, what is the value of \\(a\\)?", "fig": {"lines": [[120, 30, 120, 205, "r", 126, 24], [220, 30, 220, 205, "s", 226, 24], [75, 176, 259, 70, "t", 266, 63]], "arcs": [[120, 150, -0.866, 0.5, 0, 1, "x&deg;", 33], [220, 92, 0, -1, -0.866, 0.5, "y&deg;", 33]]}, "figNote": true, "accepted": [127], "rat": "\\(x\\) (below \\(t\\), left of \\(r\\)) and \\(y\\) (above \\(t\\), left of \\(s\\)) are <b>same-side angles</b> that together make a straight-line pair across the parallel lines, so \\(x+y=180\\). Then \\((2w+24)+(5w+29)=180\\), so \\(7w+53=180\\) and \\(7w=127\\). Since \\(a=7w\\), \\(a=127\\).", "skill": "Lines, angles, and triangles"}, {"src": "June 2024", "type": "spr", "stem": "In the figure, line \\(n\\) intersects lines \\(r\\) and \\(s\\). Line \\(r\\) is parallel to line \\(s\\). What is the value of \\(x\\)?", "fig": {"lines": [[30, 70, 330, 70, "r", 338, 75], [30, 160, 330, 160, "s", 338, 165], [124, 33, 239, 198, "n", 246, 206]], "arcs": [[150, 70, -0.574, -0.819, 1, 0, "164&deg;", 40], [213, 160, -0.574, -0.819, -1, 0, "x&deg;", 30]]}, "accepted": [16], "rat": "The 164&deg; angle at line \\(r\\) is the obtuse angle on the upper-right. Its corresponding angle at line \\(s\\) is also 164&deg;, so the acute angle \\(x\\) next to it on the upper-left is its supplement: \\(x=180-164=16\\).", "skill": "Lines, angles, and triangles"}, {"src": "October US 2024", "type": "mc", "stem": "In the figure shown, line \\(l\\) intersects lines \\(j\\) and \\(k\\). Which additional piece of information is sufficient to prove that lines \\(j\\) and \\(k\\) are parallel?", "fig": {"lines": [[30, 70, 330, 70, "k", 338, 75], [30, 160, 330, 160, "j", 338, 165], [130, 200, 226, 34, "l", 231, 28]], "arcs": [[205, 70, 0.5, -0.866, 1, 0, "w&deg;", 40], [205, 70, -0.5, 0.866, -1, 0, "x&deg;", 40], [153, 160, 0.5, -0.866, -1, 0, "35&deg;", 42], [153, 160, -0.5, 0.866, -1, 0, "y&deg;", 40], [153, 160, -0.5, 0.866, 1, 0, "z&deg;", 40]]}, "figNote": true, "opts": ["\\(w=35^\\circ\\)", "\\(x=145^\\circ\\)", "\\(y=35^\\circ\\)", "\\(z=145^\\circ\\)"], "ans": "B", "rat": "Lines \\(j\\) and \\(k\\) are parallel exactly when the upper-left angle at \\(k\\) equals the upper-left 35&deg; at \\(j\\). That angle is the supplement of \\(w\\), so we need \\(w=145\\) &mdash; and since \\(x\\) is <b>vertical</b> to \\(w\\), that is the same as \\(x=145\\) (choice B). Choice A would make the corresponding angle 145&deg;, not 35&deg;. Choices C and D are about angles at the <i>same</i> intersection as the 35&deg;: \\(y=145\\) and \\(z=35\\) are already forced by the figure, so they can never prove anything about line \\(k\\).", "skill": "Lines, angles, and triangles"}, {"src": "November 2024", "type": "mc", "stem": "In the figure shown, the lines \\(l\\) and \\(k\\) are parallel and line \\(t\\) intersects both lines. If \\(x>154\\), which of the following must be true?", "fig": {"lines": [[30, 70, 330, 70, "l", 338, 75], [30, 160, 330, 160, "k", 338, 165], [124, 33, 239, 198, "t", 112, 28]], "arcs": [[150, 70, -0.574, -0.819, 1, 0, "x&deg;", 40], [213, 160, -0.574, -0.819, -1, 0, "y&deg;", 30]]}, "opts": ["\\(y<26\\)", "\\(y>26\\)", "\\(x+y<180\\)", "\\(x+y>180\\)"], "ans": "A", "rat": "\\(y\\) equals the corresponding angle of the supplement of \\(x\\): the upper-left angle at \\(l\\) is \\(180-x\\), and it corresponds to \\(y\\). So \\(y=180-x\\). If \\(x>154\\), then \\(y<180-154=26\\). (Note \\(x+y=180\\) exactly, so C and D are both false.)", "skill": "Lines, angles, and triangles"}, {"src": "December 2024", "type": "mc", "stem": "In the figure, line \\(q\\) is parallel to line \\(r\\), and both lines are intersected by line \\(s\\). If \\(y=2x+8\\), what is the value of \\(x\\)?", "fig": {"lines": [[30, 70, 330, 70, "q", 338, 75], [30, 160, 330, 160, "r", 338, 165], [130, 200, 226, 34, "s", 231, 28]], "arcs": [[205, 70, 0.5, -0.866, -1, 0, "74&deg;"], [153, 160, 0.5, -0.866, -1, 0, "y"]]}, "figNote": true, "opts": ["33", "41", "49", "59"], "ans": "A", "rat": "The 74&deg; angle and \\(y\\) sit in the same upper-left position at each parallel line, so they are <b>corresponding angles</b>: \\(y=74\\). Then \\(2x+8=74\\), so \\(x=33\\).", "skill": "Lines, angles, and triangles"}, {"src": "March 2025", "type": "txt", "stem": "In the figure shown, line \\(k\\) intersects lines \\(r\\) and \\(s\\). If \\(w=146^\\circ\\), which additional piece of information is sufficient to prove that lines \\(r\\) and \\(s\\) are parallel? <span style=\"color:var(--muted);font-size:14px\">(Enter your answer as an equation, e.g. <i>y = 20</i>.)</span>", "fig": {"h": 235, "lines": [[130, 25, 130, 210, "r", 136, 20], [240, 25, 240, 210, "s", 246, 20], [89, 51, 277, 183, "k", 80, 44]], "arcs": [[130, 80, 0, -1, 0.819, 0.574, "w&deg;", 34], [130, 80, 0.819, 0.574, 0, 1, "x&deg;", 34], [240, 157, 0, -1, -0.819, -0.574, "y&deg;", 33], [240, 157, -0.819, -0.574, 0, 1, "z&deg;", 34]]}, "accepted": ["z=146", "y=34", "146", "34"], "rat": "\\(w\\) and \\(z\\) are <b>alternate interior angles</b> for transversal \\(k\\), so \\(r\\parallel s\\) exactly when \\(z=146\\). Equivalently, \\(w\\) and \\(y\\) are same-side interior angles, so \\(y=180-146=34\\) also proves it. (Either <b>z = 146</b> or <b>y = 34</b> is accepted.) Note that \\(x=34\\) is <i>automatically</i> true &mdash; \\(x\\) is the linear pair of \\(w\\) at the same intersection &mdash; so it proves nothing.", "skill": "Lines, angles, and triangles"}, {"src": "May 2025", "type": "mc", "stem": "In the figure, line \\(l\\) is parallel to line \\(m\\). What is the value of \\(x\\)?", "fig": {"lines": [[30, 70, 330, 70, "l", 338, 75], [30, 160, 330, 160, "m", 338, 165], [134, 33, 249, 198, "k", 256, 206]], "arcs": [[160, 70, -0.574, -0.819, -1, 0, "x&deg;", 30], [223, 160, 0.574, 0.819, -1, 0, "111&deg;", 42]]}, "figNote": true, "opts": ["31", "69", "111", "131"], "ans": "B", "rat": "The 111&deg; angle is below line \\(m\\); its supplement above \\(m\\) on the same side is \\(180-111=69\\), and that angle <b>corresponds</b> to \\(x\\) at line \\(l\\). So \\(x=69\\).", "skill": "Lines, angles, and triangles"}, {"src": "May 2025", "type": "mc", "stem": "In the figure shown, line \\(t\\) intersects lines \\(j\\) and \\(k\\). Which additional piece of information is sufficient to prove that lines \\(j\\) and \\(k\\) are parallel?", "fig": {"lines": [[30, 70, 330, 70, "j", 338, 75], [30, 160, 330, 160, "k", 338, 165], [130, 200, 226, 34, "t", 231, 28]], "arcs": [[205, 70, 0.5, -0.866, 1, 0, "w", 38], [205, 70, -0.5, 0.866, -1, 0, "x", 38], [153, 160, 0.5, -0.866, 1, 0, "54&deg;", 42], [153, 160, -0.5, 0.866, -1, 0, "y", 38], [153, 160, -0.5, 0.866, 1, 0, "z", 38]]}, "opts": ["\\(w=54\\)", "\\(x=126\\)", "\\(y=54\\)", "\\(z=126\\)"], "ans": "A", "rat": "\\(w\\) and the 54&deg; angle occupy the same upper-right position at their lines, so they are <b>corresponding angles</b>: \\(w=54\\) proves \\(j\\parallel k\\). \\(y=54\\) (vertical to 54&deg;) and \\(z=126\\) (linear pair with 54&deg;) are true in <i>any</i> figure, so they prove nothing; \\(x=126\\) would actually contradict parallelism since \\(x\\) is vertical to \\(w\\).", "skill": "Lines, angles, and triangles"}, {"src": "March 2024", "type": "mc", "stem": "Two lines intersect at exactly one point, forming two acute angles and two obtuse angles. The measure of one of these angles is \\((9x-190)^\\circ\\). Which of the following could NOT be the sum of the measures of any two of these angles?", "fig": null, "opts": ["\\((-18x+380)^\\circ\\)", "\\((-18x+740)^\\circ\\)", "\\((18x-380)^\\circ\\)", "\\(180^\\circ\\)"], "ans": "A", "rat": "The four angles are \\(\\theta,\\;180-\\theta,\\;\\theta,\\;180-\\theta\\) with \\(\\theta=(9x-190)^\\circ\\). Possible sums of two of them: \\(2\\theta=(18x-380)^\\circ\\) (choice C), \\((180-\\theta)+(180-\\theta)=(-18x+740)^\\circ\\) (choice B), and \\(\\theta+(180-\\theta)=180^\\circ\\) (choice D). Choice A, \\((-18x+380)^\\circ\\), is the <i>negative</i> of \\(2\\theta\\) &mdash; it cannot equal a sum of two positive angle measures.", "skill": "Lines, angles, and triangles"}, {"src": "ID 954943a4", "type": "mc", "stem": "Jennifer bought a box of Crunchy Grain cereal. The nutrition facts on the box state that a serving size of the cereal is \\(\\tfrac{3}{4}\\) cup and provides 210 calories, 50 of which are calories from fat. In addition, each serving of the cereal provides 180 milligrams of potassium, which is 5% of the daily allowance for adults. If \\(p\\) percent of an adult’s daily allowance of potassium is provided by \\(x\\) servings of Crunchy Grain cereal per day, which of the following expresses \\(p\\) in terms of \\(x\\)?", "fig": null, "opts": ["\\(p=0.5x\\)", "\\(p=5x\\)", "\\(p=(0.05)^x\\)", "\\(p=(1.05)^x\\)"], "ans": "B", "rat": "Each serving provides 5% of the daily allowance, so \\(x\\) servings provide \\(5x\\) percent: \\(p=5x\\). No decimal conversion is needed because \\(p\\) is already a percentage, and the relationship is linear, not exponential.", "skill": "Percentages"}, {"src": "Official-style &middot; ID 65c49824", "type": "spr", "stem": "A school district is forming a committee to discuss plans for the construction of a new high school. Of those invited to join the committee, 15% are parents of students, 45% are teachers from the current high school, 25% are school and district administrators, and the remaining 6 individuals are students. How many more teachers were invited to join the committee than school and district administrators?", "fig": null, "accepted": [8], "rat": "Students make up \\(100-15-45-25=15\\%\\) of those invited, and that equals 6 people, so \\(0.15x=6\\) gives \\(x=40\\) invitees. Teachers: \\(0.45(40)=18\\). Administrators: \\(0.25(40)=10\\). Difference: \\(18-10=8\\).", "skill": "Percentages"}, {"src": "ID 0ea56bb2", "type": "mc", "stem": "The manager of an online news service received the report above on the number of subscriptions sold by the service. The manager estimated that the percent increase from 2012 to 2013 would be double the percent increase from 2013 to 2014. How many subscriptions did the manager expect would be sold in 2014?", "figHTML": "<table class=\"data-table\"><tr><th>Year</th><th>Subscriptions sold</th></tr><tr><td>2012</td><td>5,600</td></tr><tr><td>2013</td><td>5,880</td></tr></table>", "opts": ["6,020", "6,027", "6,440", "6,468"], "ans": "B", "rat": "From 2012 to 2013 the increase was \\(\\frac{5880-5600}{5600}=0.05\\), or 5%. The 2013&ndash;2014 increase is expected to be half of that, 2.5%, so the 2014 expectation is \\(5880(1.025)=6027\\).", "skill": "Percentages"}, {"src": "Official-style &middot; ID 0231050d", "type": "spr", "stem": "The line graph shows the total amount of snow, in inches, recorded each year in Washington, DC, from 2003 to 2015. If \\(p\\%\\) is the percent decrease in the annual snowfall from 2003 to 2007, what is the value of \\(p\\)?", "fig": {"h": 210, "extra": "<line x1=\"60\" y1=\"30\" x2=\"60\" y2=\"170\" stroke=\"#1e1e1e\" stroke-width=\"1.5\"/><line x1=\"60\" y1=\"170\" x2=\"330\" y2=\"170\" stroke=\"#1e1e1e\" stroke-width=\"1.5\"/><text x=\"52\" y=\"174\" font-size=\"10\" text-anchor=\"end\">0</text><line x1=\"57\" y1=\"170\" x2=\"60\" y2=\"170\" stroke=\"#1e1e1e\" stroke-width=\"1\"/><text x=\"52\" y=\"150.66666666666666\" font-size=\"10\" text-anchor=\"end\">10</text><line x1=\"57\" y1=\"146.66666666666666\" x2=\"60\" y2=\"146.66666666666666\" stroke=\"#1e1e1e\" stroke-width=\"1\"/><text x=\"52\" y=\"127.33333333333334\" font-size=\"10\" text-anchor=\"end\">20</text><line x1=\"57\" y1=\"123.33333333333334\" x2=\"60\" y2=\"123.33333333333334\" stroke=\"#1e1e1e\" stroke-width=\"1\"/><text x=\"52\" y=\"104\" font-size=\"10\" text-anchor=\"end\">30</text><line x1=\"57\" y1=\"100\" x2=\"60\" y2=\"100\" stroke=\"#1e1e1e\" stroke-width=\"1\"/><text x=\"52\" y=\"80.66666666666667\" font-size=\"10\" text-anchor=\"end\">40</text><line x1=\"57\" y1=\"76.66666666666667\" x2=\"60\" y2=\"76.66666666666667\" stroke=\"#1e1e1e\" stroke-width=\"1\"/><text x=\"52\" y=\"57.33333333333333\" font-size=\"10\" text-anchor=\"end\">50</text><line x1=\"57\" y1=\"53.33333333333333\" x2=\"60\" y2=\"53.33333333333333\" stroke=\"#1e1e1e\" stroke-width=\"1\"/><text x=\"52\" y=\"34\" font-size=\"10\" text-anchor=\"end\">60</text><line x1=\"57\" y1=\"30\" x2=\"60\" y2=\"30\" stroke=\"#1e1e1e\" stroke-width=\"1\"/><polyline points=\"72.0,76.7 92.5,142.0 113.0,139.7 133.5,139.7 154.0,146.7 174.5,158.3 195.0,153.7 215.5,39.3 236.0,142.0 256.5,165.3 277.0,163.0 297.5,95.3 318.0,128.0\" fill=\"none\" stroke=\"#1e1e1e\" stroke-width=\"1.6\"/><circle cx=\"72.0\" cy=\"76.7\" r=\"2.4\" fill=\"#1e1e1e\"/><text x=\"72.0\" y=\"183\" font-size=\"8.5\" text-anchor=\"end\" transform=\"rotate(-45 72.0 183)\">2003</text><circle cx=\"92.5\" cy=\"142.0\" r=\"2.4\" fill=\"#1e1e1e\"/><text x=\"92.5\" y=\"183\" font-size=\"8.5\" text-anchor=\"end\" transform=\"rotate(-45 92.5 183)\">2004</text><circle cx=\"113.0\" cy=\"139.7\" r=\"2.4\" fill=\"#1e1e1e\"/><text x=\"113.0\" y=\"183\" font-size=\"8.5\" text-anchor=\"end\" transform=\"rotate(-45 113.0 183)\">2005</text><circle cx=\"133.5\" cy=\"139.7\" r=\"2.4\" fill=\"#1e1e1e\"/><text x=\"133.5\" y=\"183\" font-size=\"8.5\" text-anchor=\"end\" transform=\"rotate(-45 133.5 183)\">2006</text><circle cx=\"154.0\" cy=\"146.7\" r=\"2.4\" fill=\"#1e1e1e\"/><text x=\"154.0\" y=\"183\" font-size=\"8.5\" text-anchor=\"end\" transform=\"rotate(-45 154.0 183)\">2007</text><circle cx=\"174.5\" cy=\"158.3\" r=\"2.4\" fill=\"#1e1e1e\"/><text x=\"174.5\" y=\"183\" font-size=\"8.5\" text-anchor=\"end\" transform=\"rotate(-45 174.5 183)\">2008</text><circle cx=\"195.0\" cy=\"153.7\" r=\"2.4\" fill=\"#1e1e1e\"/><text x=\"195.0\" y=\"183\" font-size=\"8.5\" text-anchor=\"end\" transform=\"rotate(-45 195.0 183)\">2009</text><circle cx=\"215.5\" cy=\"39.3\" r=\"2.4\" fill=\"#1e1e1e\"/><text x=\"215.5\" y=\"183\" font-size=\"8.5\" text-anchor=\"end\" transform=\"rotate(-45 215.5 183)\">2010</text><circle cx=\"236.0\" cy=\"142.0\" r=\"2.4\" fill=\"#1e1e1e\"/><text x=\"236.0\" y=\"183\" font-size=\"8.5\" text-anchor=\"end\" transform=\"rotate(-45 236.0 183)\">2011</text><circle cx=\"256.5\" cy=\"165.3\" r=\"2.4\" fill=\"#1e1e1e\"/><text x=\"256.5\" y=\"183\" font-size=\"8.5\" text-anchor=\"end\" transform=\"rotate(-45 256.5 183)\">2012</text><circle cx=\"277.0\" cy=\"163.0\" r=\"2.4\" fill=\"#1e1e1e\"/><text x=\"277.0\" y=\"183\" font-size=\"8.5\" text-anchor=\"end\" transform=\"rotate(-45 277.0 183)\">2013</text><circle cx=\"297.5\" cy=\"95.3\" r=\"2.4\" fill=\"#1e1e1e\"/><text x=\"297.5\" y=\"183\" font-size=\"8.5\" text-anchor=\"end\" transform=\"rotate(-45 297.5 183)\">2014</text><circle cx=\"318.0\" cy=\"128.0\" r=\"2.4\" fill=\"#1e1e1e\"/><text x=\"318.0\" y=\"183\" font-size=\"8.5\" text-anchor=\"end\" transform=\"rotate(-45 318.0 183)\">2015</text><text x=\"78\" y=\"68.66666666666667\" font-size=\"10.5\">(2003, 40)</text><text x=\"160\" y=\"140.66666666666666\" font-size=\"10.5\">(2007, 10)</text><text x=\"16\" y=\"105\" font-size=\"10\" transform=\"rotate(-90 16 105)\" text-anchor=\"middle\">Annual snowfall (inches)</text><text x=\"195\" y=\"205\" font-size=\"10.5\" text-anchor=\"middle\">Year</text>"}, "accepted": [75], "rat": "Snowfall fell from 40 inches in 2003 to 10 inches in 2007. Percent decrease: \\(\\frac{40-10}{40}\\times100=75\\). So \\(p=75\\).", "skill": "Percentages"}, {"src": "ID 67c0200a", "type": "spr", "stem": "The number \\(a\\) is 70% less than the positive number \\(b\\). The number \\(c\\) is 80% greater than \\(a\\). The number \\(c\\) is how many times \\(b\\)?", "fig": null, "accepted": [0.54], "rat": "\\(a=(1-0.70)b=0.30b\\) and \\(c=(1+0.80)a=1.80a\\). Substituting, \\(c=1.80(0.30b)=0.54b\\), so \\(c\\) is \\(.54\\) times \\(b\\). (.54 and 27/50 are both accepted.)", "skill": "Percentages"}, {"src": "Official-style &middot; ID 40e7a1a9", "type": "spr", "stem": "210 is \\(p\\%\\) greater than 30. What is the value of \\(p\\)?", "fig": null, "accepted": [600], "rat": "\\(210=\\left(1+\\tfrac{p}{100}\\right)(30)\\). Dividing by 30: \\(7=1+\\tfrac{p}{100}\\), so \\(\\tfrac{p}{100}=6\\) and \\(p=600\\).", "skill": "Percentages"}, {"src": "ID 55818046", "type": "mc", "stem": "According to the 2010 Census, the adult population aged 18 years or greater of the United States in 2010 was 234,564,071. In 2010, a survey was conducted among a randomly chosen sample of adults aged 18 years or greater in the United States about their preference to live in a warm climate or a cool climate. The table displays a summary of the survey results. Which of the following is closest to the difference between the percentage of adults aged 18&ndash;50 years who responded &ldquo;warm&rdquo; and the percentage of adults aged 51 years or greater who responded &ldquo;warm&rdquo;?", "figHTML": "<table class=\"data-table\"><caption>Climate Preferences</caption><tr><th></th><th>Warm</th><th>Cool</th><th>No preference</th><th>Total</th></tr><tr><th>18&ndash;35 years old</th><td>295</td><td>168</td><td>45</td><td>508</td></tr><tr><th>36&ndash;50 years old</th><td>246</td><td>123</td><td>41</td><td>410</td></tr><tr><th>51&ndash;65 years old</th><td>238</td><td>117</td><td>48</td><td>403</td></tr><tr><th>Greater than 65 years old</th><td>137</td><td>78</td><td>64</td><td>279</td></tr><tr><th>Total</th><td>916</td><td>486</td><td>198</td><td>1,600</td></tr></table>", "opts": ["4%", "5%", "10%", "18%"], "ans": "A", "rat": "Ages 18&ndash;50 who said warm: \\(\\frac{295+246}{508+410}=\\frac{541}{918}\\approx58.9\\%\\). Ages 51+: \\(\\frac{238+137}{403+279}=\\frac{375}{682}\\approx55.0\\%\\). The difference is about 3.9%, closest to 4%.", "skill": "Percentages"}, {"src": "ID 20845d36", "type": "spr", "stem": "The number \\(a\\) is 70% less than the positive number \\(b\\). The number \\(c\\) is 60% greater than \\(a\\). The number \\(c\\) is how many times \\(b\\)?", "fig": null, "accepted": [0.48], "rat": "\\(a=0.30b\\) and \\(c=1.60a=1.60(0.30b)=0.48b\\). So \\(c\\) is \\(.48\\) times \\(b\\). (.48 and 12/25 are both accepted.)", "skill": "Percentages"}, {"src": "Official-style &middot; ID 2e92cc21", "type": "spr", "stem": "The number \\(a\\) is 110% greater than the number \\(b\\). The number \\(b\\) is 90% less than 47. What is the value of \\(a\\)?", "fig": null, "accepted": [9.87], "rat": "\\(b=(1-0.90)(47)=0.1(47)=4.7\\), and \\(a=(1+1.10)b=2.1b=2.1(4.7)=9.87\\).", "skill": "Percentages"}, {"src": "Official-style &middot; ID 8c5dbd3e", "type": "spr", "stem": "The number \\(w\\) is 110% greater than the number \\(z\\). The number \\(z\\) is 55% less than 50. What is the value of \\(w\\)?", "fig": null, "accepted": [47.25], "rat": "\\(z=(1-0.55)(50)=0.45(50)=22.5\\), and \\(w=2.1z=2.1(22.5)=47.25\\). (47.25 and 189/4 are both accepted.)", "skill": "Percentages"}, {"src": "ID 3d73a58b", "type": "spr", "stem": "A gift shop buys souvenirs at a wholesale price of 7.00 dollars each and resells them each at a retail price that is 290% of the wholesale price. At the end of the season, any remaining souvenirs are marked at a discounted price that is 80% off the retail price. What is the discounted price of each remaining souvenir, in dollars?", "fig": null, "accepted": [4.06], "rat": "Retail price: \\(\\$7.00(2.9)=\\$20.30\\). The discount is 80% off, so the discounted price is 20% of retail: \\(\\$20.30(0.20)=\\$4.06\\).", "skill": "Percentages"}, {"src": "ID 040f2a84", "type": "spr", "stem": "The regular price of a shirt at a store is $11.70. The sale price of the shirt is 80% less than the regular price, and the sale price is 30% greater than the store’s cost for the shirt. What was the store’s cost, in dollars, for the shirt? (Disregard the $ sign when entering your answer.)", "fig": null, "accepted": [1.8], "rat": "Sale price: \\(11.70(1-0.8)=\\$2.34\\). Since the sale price is 30% above cost, \\(2.34=1.3x\\), so \\(x=1.80\\).", "skill": "Percentages"}, {"src": "ID 8213b1b3", "type": "spr", "stem": "According to a set of standards, a certain type of substance can contain a maximum of 0.001% phosphorus by mass. If a sample of this substance has a mass of 140 grams, what is the maximum mass, in grams, of phosphorus the sample can contain to meet these standards?", "fig": null, "accepted": [0.0014], "rat": "0.001% as a decimal is \\(\\tfrac{0.001}{100}=0.00001\\). Then \\(0.00001\\times140=0.0014\\) grams.", "skill": "Percentages"}, {"src": "ID 34f8cd89", "type": "mc", "stem": "37% of the items in a box are green. Of those, 37% are also rectangular. Of the green rectangular items, 42% are also metal. Which of the following is closest to the percentage of the items in the box that are <u>not</u> rectangular green metal items?", "fig": null, "opts": ["1.16%", "57.50%", "94.25%", "98.84%"], "ans": "C", "rat": "Rectangular green metal items make up \\(0.37\\times0.37\\times0.42=0.057498\\), about 5.75% of the box. Everything else is \\(1-0.057498=0.942502\\), so about \\(94.25\\%\\) of the items are <i>not</i> rectangular green metal items.", "skill": "Percentages"}, {"src": "ID 25faa756", "type": "spr", "stem": "The number \\(a\\) is 60% greater than the positive number \\(b\\). The number \\(c\\) is 45% less than \\(a\\). The number \\(c\\) is how many times \\(b\\)?", "fig": null, "accepted": [0.88], "rat": "\\(a=1.60b\\) and \\(c=0.55a=0.55(1.60b)=0.88b\\). So \\(c\\) is \\(.88\\) times \\(b\\). (.88 and 22/25 are both accepted.)", "skill": "Percentages"}, {"src": "ID ad911622", "type": "mc", "stem": "The value of a collectible comic book increased by 167% from the end of 2011 to the end of 2012 and then decreased by 16% from the end of 2012 to the end of 2013. What was the net percentage increase in the value of the collectible comic book from the end of 2011 to the end of 2013?", "fig": null, "opts": ["124.28%", "140.28%", "151.00%", "209.72%"], "ans": "A", "rat": "Start with value \\(x\\). After +167%: \\(2.67x\\). After &minus;16%: \\(2.67x(0.84)=2.2428x\\). The net gain is \\(2.2428x-x=1.2428x\\), a net increase of \\(124.28\\%\\). (Choice C is the difference \\(167-16\\), a classic trap: percents of different bases never subtract directly.)", "skill": "Percentages"}, {"src": "ID 310c87fe &middot; Geometry &amp; Trigonometry", "type": "mc", "stem": "A cube has a surface area of 54 square meters. What is the volume, in cubic meters, of the cube?", "fig": null, "rat": "Each face: 54/6 = 9 m&sup2;, so the edge is 3 m and the volume is 3&sup3; = 27 m&sup3;.", "opts": ["18", "27", "36", "81"], "ans": "B", "skill": "Area and volume"}, {"src": "Official-style &middot; Problem-Solving &amp; Data Analysis", "type": "spr", "stem": "Pure beeswax has a density of 0.555 ounce per cubic inch. An online company sells pure beeswax at a price of $8.00 per ounce. What is the selling price, in dollars per cubic inch, for pure beeswax purchased from this company?", "fig": null, "rat": "$8.00 per ounce &times; 0.555 ounce per cubic inch = $4.44 per cubic inch.", "accepted": [4.44], "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "ID 90eed2e5 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A city has 50 city council members. A reporter polled a random sample of 20 city council members and found that 6 of those polled supported a specific bill. Based on the sample, which of the following is the best estimate of the number of city council members in the city who support the bill?", "fig": null, "rat": "Sample proportion 6/20 applied to all 50 members: (6/20)(50) = 15.", "opts": ["6", "9", "15", "30"], "ans": "C", "skill": "Inference from sample statistics and margin of error"}, {"src": "ID b4912cc5 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "The population density of Iceland, in people per square kilometer of land area, increased from 2.5 in 1990 to 3.3 in 2014. During this time period, the land area of Iceland was 100,250 square kilometers. By how many people did Iceland’s population increase from 1990 to 2014?", "fig": null, "rat": "Density rose by 3.3&minus;2.5 = 0.8 people per km&sup2; over 100,250 km&sup2;: 0.8(100,250) = 80,200 people.", "opts": ["330,825", "132,330", "125,312", "80,200"], "ans": "D", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "The score on a trivia game is obtained by subtracting the number of incorrect answers from twice the number of correct answers. If a player answered 40 questions and obtained a score of 50, how many questions did the player answer correctly?", "fig": null, "rat": "With c correct out of 40: 2c &minus; (40&minus;c) = 50, so 3c = 90 and c = 30.", "accepted": [30], "skill": "Systems of two linear equations in two variables"}, {"src": "ID f44a29a8 &middot; Advanced Math", "type": "mc", "stem": "An object’s kinetic energy, in joules, is equal to the product of one-half the object’s mass, in kilograms, and the square of the object’s speed, in meters per second. What is the speed, in meters per second, of an object with a mass of 4 kilograms and kinetic energy of 18 joules?", "fig": null, "rat": "KE = &frac12;mv&sup2;: 18 = &frac12;(4)v&sup2; = 2v&sup2;, so v&sup2; = 9 and v = 3 m/s.", "opts": ["3", "6", "9", "36"], "ans": "A", "skill": "Nonlinear functions"}, {"src": "ID 20b69297 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "Anita created a batch of green paint by mixing 2 ounces of blue paint with 3 ounces of yellow paint. She must mix a second batch using the same ratio of blue and yellow paint as the first batch. If she uses 5 ounces of blue paint for the second batch, how much yellow paint should Anita use?", "fig": null, "rat": "Ratio blue:yellow = 2:3, so yellow = (3/2)(blue). With 5 ounces of blue: yellow = 7.5 = 1.5 times the blue in the second batch.", "opts": ["Exactly 5 ounces", "3 ounces more than the amount of yellow paint used in the first batch", "1.5 times the amount of yellow paint used in the first batch", "1.5 times the amount of blue paint used in the second batch"], "ans": "D", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "A local transit company sells a monthly pass for $95 that allows an unlimited number of trips of any length. Tickets for individual trips cost $1.50, $2.50, or $3.50, depending on the length of the trip. What is the minimum number of trips per month for which a monthly pass could cost less than purchasing individual tickets for trips?", "fig": null, "rat": "The pass can beat individual tickets only if the trips would cost more than $95. In the best case for the pass, every trip costs $3.50: need 3.50n &gt; 95, so n &gt; 27.1. The minimum whole number is 28.", "accepted": [28], "skill": "Linear inequalities in one or two variables"}, {"src": "ID b4f5a7ca &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A survey was conducted using a sample of history professors selected at random from the California State Universities. The professors surveyed were asked to name the publishers of their current texts. What is the largest population to which the results of the survey can be generalized?", "fig": null, "rat": "The sample was random among history professors of the California State Universities, so that is the largest population the results generalize to.", "opts": ["All professors in the United States", "All history professors in the United States", "All history professors at all California State Universities", "All professors at all California State Universities"], "ans": "C", "skill": "Evaluating statistical claims: observational studies and experiments"}, {"src": "ID 4a422e3e &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "To determine the mean number of children per household in a community, Tabitha surveyed 20 families at a playground. For the 20 families surveyed, the mean number of children per household was 2.4. Which of the following statements must be true?", "fig": null, "rat": "Sampling families at a playground over-represents households with children, so the estimate may be biased.", "opts": ["The mean number of children per household in the community is 2.4.", "A determination about the mean number of children per household in the community should not be made because the sample size is too small.", "The sampling method is flawed and may produce a biased estimate of the mean number of children per household in the community.", "The sampling method is not flawed and is likely to produce an unbiased estimate of the mean number of children per household in the community."], "ans": "C", "skill": "Evaluating statistical claims: observational studies and experiments"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "A movie theater sells two types of tickets, adult tickets for $12 and child tickets for $8. If the theater sold 30 tickets for a total of $300, how much, in dollars, was spent on adult tickets? (Disregard the $ sign when gridding your answer.)", "fig": null, "rat": "With a adult and c child tickets: a+c=30 and 12a+8c=300. Then 4a=60, a=15, and adult ticket revenue is 12(15) = $180.", "accepted": [180], "skill": "Systems of two linear equations in two variables"}, {"src": "ID 71189542 &middot; Algebra", "type": "mc", "stem": "A group of 202 people went on an overnight camping trip, taking 60 tents with them. Some of the tents held 2 people each, and the rest held 4 people each. Assuming all the tents were filled to capacity and every person got to sleep in a tent, exactly how many of the tents were 2-person tents?", "fig": null, "rat": "With s two-person and f four-person tents: s+f=60 and 2s+4f=202. Substituting s=60&minus;f: 120+2f=202, so f=41 and s=19.", "opts": ["30", "20", "19", "18"], "ans": "C", "skill": "Systems of two linear equations in two variables"}, {"src": "ID 46f68129 &middot; Algebra", "type": "mc", "stem": "A librarian has 43 books to distribute to a group of children. If he gives each child 2 books, he will have 7 books left over. How many children are in the group?", "fig": null, "rat": "2n + 7 = 43, so n = 18 children.", "opts": ["15", "18", "25", "29"], "ans": "B", "skill": "Linear equations in one variable"}, {"src": "ID 707db2d3 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "For the finale of a TV show, viewers could use either social media or a text message to vote for their favorite of two contestants. The contestant receiving more than 50% of the vote won. An estimated 10% of the viewers voted, and 30% of the votes were cast on social media. Contestant 2 earned 70% of the votes cast using social media and 40% of the votes cast using a text message. Based on this information, which of the following is an accurate conclusion?", "fig": null, "rat": "Contestant 2 won 70% of social-media votes but only 40% of text votes, so social-media voters were more likely to prefer Contestant 2. The other claims are not supported.", "opts": ["If all viewers had voted, Contestant 2 would have won.", "Viewers voting by social media were likely to be younger than viewers voting by text message.", "If all viewers who voted had voted by social media instead of by text message, Contestant 2 would have won.", "Viewers voting by social media were more likely to prefer Contestant 2 than were viewers voting by text message."], "ans": "D", "skill": "Percentages"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "How many liters of a 25% saline solution must be added to 3 liters of a 10% saline solution to obtain a 15% saline solution?", "fig": null, "rat": "0.25x + 0.10(3) = 0.15(x+3) gives 0.25x+0.3 = 0.15x+0.45, so 0.10x = 0.15 and x = 1.5 liters.", "accepted": [1.5], "skill": "Linear equations in two variables"}, {"src": "ID 8705ecba &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "The cost of a certain shirt is $20 before a 5% sales tax is added. What is the total cost, including sales tax, to purchase the shirt?", "fig": null, "rat": "$20 &times; 1.05 = $21.00.", "opts": ["$20.05", "$20.50", "$21.00", "$25.00"], "ans": "C", "skill": "Percentages"}, {"src": "ID 457d2f2c &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A data set of 27 different numbers has a mean of 33 and a median of 33. A new data set is created by adding 7 to each number in the original data set that is greater than the median and subtracting 7 from each number in the original data set that is less than the median. Which of the following measures does NOT have the same value in both the original and new data sets?", "fig": null, "rat": "Thirteen values gain 7 and thirteen lose 7 (the median value is untouched), so the sum, mean, and median are unchanged &mdash; but values move away from the center, so the standard deviation increases.", "opts": ["Median", "Mean", "Sum of the numbers", "Standard deviation"], "ans": "D", "skill": "One-variable data: distributions and measures of center and spread"}, {"src": "ID 53d97af5 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A study was done on the weights of different types of fish in a pond. A random sample of fish were caught and marked in order to ensure that none were weighed more than once. The sample contained 150 largemouth bass, of which 30% weighed more than 2 pounds. Which of the following conclusions is best supported by the sample data?", "fig": null, "rat": "The sample data describe only the largemouth bass caught, so the supported conclusion is about largemouth bass in the pond: about 30% weigh more than 2 pounds.", "opts": ["The majority of all fish in the pond weigh less than 2 pounds.", "The average weight of all fish in the pond is approximately 2 pounds.", "Approximately 30% of all fish in the pond weigh more than 2 pounds.", "Approximately 30% of all largemouth bass in the pond weigh more than 2 pounds."], "ans": "D", "skill": "Inference from sample statistics and margin of error"}, {"src": "ID d28c29e1 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "The International Space Station orbits Earth at an average speed of 4.76 miles per second. What is the space station’s average speed in miles per hour?", "fig": null, "rat": "4.76 miles/second &times; 3,600 seconds/hour = 17,136 miles per hour.", "opts": ["285.6", "571.2", "856.8", "17,136.0"], "ans": "D", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "ID 9bf4c545 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "The members of a city council wanted to assess the opinions of all city residents about converting an open field into a dog park. The council surveyed a sample of 500 city residents who own dogs. The survey showed that the majority of those sampled were in favor of the dog park. Which of the following is true about the city council’s survey?", "fig": null, "rat": "Sampling only dog owners cannot represent all city residents, so the sample is biased for the question asked.", "opts": ["It shows that the majority of city residents are in favor of the dog park.", "The survey sample should have included more residents who are dog owners.", "The survey sample should have consisted entirely of residents who do not own dogs.", "The survey sample is biased because it is not representative of all city residents."], "ans": "D", "skill": "Evaluating statistical claims: observational studies and experiments"}, {"src": "ID 2b15d65f &middot; Algebra", "type": "mc", "stem": "An economist modeled the demand Q for a certain product as a linear function of the selling price P. The demand was 20,000 units when the selling price was $40 per unit, and the demand was 15,000 units when the selling price was $60 per unit. Based on the model, what is the demand, in units, when the selling price is $55 per unit?", "fig": null, "rat": "Slope: (15,000&minus;20,000)/(60&minus;40) = &minus;250 units per dollar. At $55: 20,000 &minus; 250(15) = 16,250.", "opts": ["16,250", "16,500", "16,750", "17,500"], "ans": "A", "skill": "Linear functions"}, {"src": "ID 6e4a60dd &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "Rita’s total bill at a restaurant was $25.00, including tax. If she left a tip of 20% of the total bill, what was the amount of the tip?", "fig": null, "rat": "0.20(25.00) = $5.00.", "opts": ["$3.50", "$4.00", "$4.50", "$5.00"], "ans": "D", "skill": "Percentages"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "According to a model, the head width, in millimeters, of a worker bumblebee can be estimated by adding 0.6 to four times the body weight of the bee, in grams. According to the model, what would be the head width, in millimeters, of a worker bumblebee that has a body weight of 0.5 grams?", "fig": null, "rat": "Head width = 0.6 + 4(body weight) = 0.6 + 4(0.5) = 2.6 millimeters.", "accepted": [2.6], "skill": "Linear functions"}, {"src": "ID 9ba3e283 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "In State X, Mr. Camp’s eighth-grade class consisting of 26 students was surveyed and 34.6 percent of the students reported that they had at least two siblings. The average eighth‑grade class size in the state is 26. If the students in Mr. Camp’s class are representative of students in the state’s eighth-grade classes and there are 1,800 eighth-grade classes in the state, which of the following best estimates the number of eighth‑grade students in the state who have fewer than two siblings?", "fig": null, "rat": "34.6% of 26 = 9 students have at least two siblings, so 17 have fewer. Statewide: 17(1,800) = 30,600.", "opts": ["16,200", "23,400", "30,600", "46,800"], "ans": "C", "skill": "Inference from sample statistics and margin of error"}, {"src": "ID f224df07 &middot; Algebra", "type": "mc", "stem": "A cargo helicopter delivers only 100-pound packages and 120-pound packages. For each delivery trip, the helicopter must carry at least 10 packages, and the total weight of the packages can be at most 1,100 pounds. What is the maximum number of 120-pound packages that the helicopter can carry per trip?", "fig": null, "rat": "With n 120-lb and m 100-lb packages: n+m&ge;10 and 120n+100m&le;1,100. Testing n=5 with m=5: 600+500=1,100 &#10003;. n=6 would need at least 4 more packages: 720+400=1,120, too heavy. Maximum is 5.", "opts": ["2", "4", "5", "6"], "ans": "C", "skill": "Linear inequalities in one or two variables"}, {"src": "ID 3ac09984 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "Marta has 7,500 pesos she will convert to US dollars using a currency exchange service. At this time, the currency exchange rate is 1 peso = 0.075 US dollars. The exchange service will charge Marta a 2% fee on the converted US dollar amount. How many US dollars will Marta receive from the currency exchange after the 2% fee is applied?", "fig": null, "rat": "7,500(0.075) = $562.50; after the 2% fee: 562.50(0.98) = $551.25.", "opts": ["$551.25", "$562.50", "$5,625.00", "$98,000.00"], "ans": "A", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "Official-style &middot; Problem-Solving &amp; Data Analysis", "type": "spr", "stem": "On April 18, 1775, Paul Revere set off on his midnight ride from Charlestown to Lexington. If he had ridden straight to Lexington without stopping, he would have traveled 11 miles in 26 minutes. In such a ride, what would the average speed of his horse have been, to the nearest tenth of a mile per hour?", "fig": null, "rat": "Speed = 11 miles / 26 minutes = 11(60)/26 &asymp; 25.4 miles per hour.", "accepted": [25.4], "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "ID 99550621 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "Makayla is planning an event in a 5,400-square-foot room. If there should be at least 8 square feet per person, what is the maximum number of people that could attend this event?", "fig": null, "rat": "5,400/8 = 675 people.", "opts": ["588", "675", "15,274", "43,200"], "ans": "B", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "ID be00d896 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "For which of the following data sets is the mean greater than the median?", "fig": null, "rat": "In 2, 4, 8, &hellip;, 512 the large values pull the mean (&asymp;113.6) far above the median (32). A and B are symmetric; D is skewed the other way (mean &asymp;194.8 &lt; median 207).", "opts": ["5, 5, 5, 5, 5, 5, 5, 5, 5", "0, 10, 20, 30, 40, 50, 60, 70, 80", "2, 4, 8, 16, 32, 64, 128, 256, 512", "7, 107, 107, 207, 207, 207, 307, 307, 307"], "ans": "C", "skill": "One-variable data: distributions and measures of center and spread"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "Maria plans to rent a boat. The boat rental costs $60 per hour, and she will also have to pay for a water safety course that costs $10. Maria wants to spend no more than $280 for the rental and the course. If the boat rental is available only for a whole number of hours, what is the maximum number of hours for which Maria can rent the boat?", "fig": null, "rat": "60h + 10 &le; 280 gives h &le; 4.5. Whole hours only, so the maximum is 4.", "accepted": [4], "skill": "Linear inequalities in one or two variables"}, {"src": "ID b2f6f17d &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A customer’s monthly water bill was $75.74. Due to a rate increase, her monthly bill is now $79.86. To the nearest tenth of a percent, by what percent did the amount of the customer’s water bill increase?", "fig": null, "rat": "Increase: (79.86&minus;75.74)/75.74 = 4.12/75.74 &asymp; 5.44%, which rounds to 5.4%.", "opts": ["4.1%", "5.1%", "5.2%", "5.4%"], "ans": "D", "skill": "Percentages"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "spr", "stem": "What is the volume, in cubic centimeters, of a right rectangular prism that has a length of 4 centimeters, a width of 9 centimeters, and a height of 10 centimeters?", "fig": null, "rat": "V = 4(9)(10) = 360 cubic centimeters.", "accepted": [360], "skill": "Area and volume"}, {"src": "ID 4ff597db &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "The mean amount of time that the 20 employees of a construction company have worked for the company is 6.7 years. After one of the employees leaves the company, the mean amount of time that the remaining employees have worked for the company is reduced to 6.25 years. How many years did the employee who left the company work for the company?", "fig": null, "rat": "Total before: 20(6.7) = 134 years. Total after: 19(6.25) = 118.75. The employee who left had worked 134&minus;118.75 = 15.25 years.", "opts": ["0.45", "2.30", "9.00", "15.25"], "ans": "D", "skill": "One-variable data: distributions and measures of center and spread"}, {"src": "ID 000259aa &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A group of monarch butterflies migrated from Chicago, Illinois, to Michoacán, Mexico, flying a total of 2,100 miles. It took a single butterfly in the group 120 days to travel this route one way. On average, how many miles did the butterfly travel per day?", "fig": null, "rat": "2,100 miles / 120 days = 17.5 miles per day.", "opts": ["0.057", "0.729", "17.5", "24"], "ans": "C", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "ID 0df106df &middot; Algebra", "type": "mc", "stem": "An online bookstore sells novels and magazines. Each novel sells for $4, and each magazine sells for $1. If Sadie purchased a total of 11 novels and magazines that have a combined selling price of $20, how many novels did she purchase?", "fig": null, "rat": "With n novels: 4n + (11&minus;n) = 20, so 3n = 9 and n = 3.", "opts": ["2", "3", "4", "5"], "ans": "B", "skill": "Systems of two linear equations in two variables"}, {"src": "ID 1ecaa9c0 &middot; Algebra", "type": "mc", "stem": "Robert rented a truck to transport materials he purchased from a hardware store. He was charged an initial fee of $20.00 plus an additional $0.70 per mile driven. If the truck was driven 38 miles, what was the total amount Robert was charged?", "fig": null, "rat": "20.00 + 0.70(38) = 20.00 + 26.60 = $46.60.", "opts": ["$46.60", "$52.90", "$66.90", "$86.50"], "ans": "A", "skill": "Linear functions"}, {"src": "ID 63573fea &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "During the first month of sales, a company sold 1,300,000 units of a certain type of smartphone. During the same month, 15% of the units sold were returned. If sales and the return rate remain the same for each of the next 5 months, about how many units of this smartphone will be returned to the company during this 6-month period?", "fig": null, "rat": "Returns per month: 0.15(1,300,000) = 195,000. Over 6 months: 6(195,000) = 1,170,000.", "opts": ["195,000", "975,000", "1,170,000", "6,630,000"], "ans": "C", "skill": "Percentages"}, {"src": "ID 70feb725 &middot; Algebra", "type": "mc", "stem": "During a month, Morgan ran r miles at 5 miles per hour and biked b miles at 10 miles per hour. She ran and biked a total of 200 miles that month, and she biked for twice as many hours as she ran. What is the total number of miles that Morgan biked during the month?", "fig": null, "rat": "Hours biked = b/10, hours run = r/5, and b/10 = 2(r/5) gives b = 4r. With r+b=200: 5r=200, r=40, so b=160.", "opts": ["80", "100", "120", "160"], "ans": "D", "skill": "Systems of two linear equations in two variables"}, {"src": "ID 3563d76d &middot; Geometry &amp; Trigonometry", "type": "mc", "stem": "At a certain time and day, the Washington Monument in Washington, DC, casts a shadow that is 300 feet long. At the same time, a nearby cherry tree casts a shadow that is 16 feet long. Given that the Washington Monument is approximately 555 feet tall, which of the following is closest to the height, in feet, of the cherry tree?", "fig": null, "rat": "Similar triangles: height = 555(16/300) = 29.6 &asymp; 30 feet.", "opts": ["10", "20", "30", "35"], "ans": "C", "skill": "Lines, angles, and triangles"}, {"src": "ID e1391dd6 &middot; Advanced Math", "type": "mc", "stem": "According to Moore’s law, the number of transistors included on microprocessors doubles every 2 years. In 1985, a microprocessor was introduced that had 275,000 transistors. Based on this information, in which of the following years does Moore’s law estimate the number of transistors to reach 1.1 million?", "fig": null, "rat": "1.1 million / 275,000 = 4 = two doublings. Two doublings take 2(2) = 4 years: 1985 + 4 = 1989.", "opts": ["1987", "1989", "1991", "1994"], "ans": "B", "skill": "Nonlinear functions"}, {"src": "ID 7ed0d098 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "Lani spent 15% of her 8-hour workday in meetings. How many minutes of her workday did she spend in meetings?", "fig": null, "rat": "15% of 8 hours = 0.15(480 minutes) = 72 minutes.", "opts": ["1.2", "15", "48", "72"], "ans": "D", "skill": "Percentages"}, {"src": "ID f8f79e11 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A park ranger asked a random sample of visitors how far they hiked during their visit. Based on the responses, the estimated mean was found to be 4.5 miles, with an associated margin of error of 0.5 miles. Which of the following is the best conclusion from these data?", "fig": null, "rat": "A margin of error gives a plausible range for the population mean: 4.5 &plusmn; 0.5, i.e., between 4 and 5 miles.", "opts": ["It is likely that all visitors hiked between 4 and 5 miles.", "It is likely that most visitors hiked exactly 4.5 miles.", "It is not possible that any visitor hiked less than 3 miles.", "It is plausible that the mean distance hiked for all visitors is between 4 and 5 miles."], "ans": "D", "skill": "Inference from sample statistics and margin of error"}, {"src": "ID 5c3c2e3c &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "The weights, in pounds, for 15 horses in a stable were reported, and the mean, median, range, and standard deviation for the data were found. The horse with the lowest reported weight was found to actually weigh 10 pounds less than its reported weight. What value remains unchanged if the four values are reported using the corrected weight?", "fig": null, "rat": "Lowering the minimum value changes the mean, the range, and the standard deviation &mdash; but the middle value is untouched, so the median is unchanged.", "opts": ["Mean", "Median", "Range", "Standard deviation"], "ans": "B", "skill": "One-variable data: distributions and measures of center and spread"}, {"src": "ID 1e8ccffd &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "The mean score of 8 players in a basketball game was 14.5 points. If the highest individual score is removed, the mean score of the remaining 7 players becomes 12 points. What was the highest score?", "fig": null, "rat": "Total of 8 scores: 8(14.5)=116. Total of remaining 7: 7(12)=84. Highest score: 116&minus;84 = 32.", "opts": ["20", "24", "32", "36"], "ans": "C", "skill": "One-variable data: distributions and measures of center and spread"}, {"src": "ID 36ab4122 &middot; Algebra", "type": "mc", "stem": "Megan’s regular wage at her job is p dollars per hour for the first 8 hours of work in a day plus 1.5 times her regular hourly wage for work in excess of 8 hours that day. On a given day, Megan worked for 10 hours, and her total earnings for that day were $137.50. What is Megan’s regular hourly wage?", "fig": null, "rat": "Pay: 8p + 2(1.5p) = 11p = 137.50, so p = $12.50.", "opts": ["$11.75", "$12.50", "$13.25", "$13.75"], "ans": "B", "skill": "Linear equations in one variable"}, {"src": "ID 2937ef4f &middot; Algebra", "type": "mc", "stem": "Hector used a tool called an auger to remove corn from a storage bin at a constant rate. The bin contained 24,000 bushels of corn when Hector began to use the auger. After 5 hours of using the auger, 19,350 bushels of corn remained in the bin. If the auger continues to remove corn at this rate, what is the total number of hours Hector will have been using the auger when 12,840 bushels of corn remain in the bin?", "fig": null, "rat": "Removal rate: (24,000&minus;19,350)/5 = 930 bushels per hour. Time for 12,840 to remain: (24,000&minus;12,840)/930 = 11,160/930 = 12 hours.", "opts": ["3", "7", "8", "12"], "ans": "D", "skill": "Linear equations in one variable"}, {"src": "ID 194ae3b1 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "There were approximately 113,000 occupational therapy jobs in the United States in 2012. The Bureau of Labor Statistics has projected that this number will increase by 29% from 2012 to 2022. Of the following, which is closest to the number of occupational therapy jobs the bureau has projected for the United States in 2022?", "fig": null, "rat": "113,000(1.29) = 145,770, closest to 145,800.", "opts": ["115,900", "116,300", "142,000", "145,800"], "ans": "D", "skill": "Percentages"}, {"src": "ID e7d9649f &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A random sample of 50 people from a town with a population of 14,878 were asked to name their favorite flavor of ice cream. If 7 people in the sample named chocolate as their favorite ice‑cream flavor, about how many people in the town would be expected to name chocolate?", "fig": null, "rat": "(7/50)(14,878) &asymp; 2,083, closest to 2,100.", "opts": ["350", "2,100", "7,500", "10,500"], "ans": "B", "skill": "Inference from sample statistics and margin of error"}, {"src": "ID 642519d7 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A polling agency recently surveyed 1,000 adults who were selected at random from a large city and asked each of the adults, “Are you satisfied with the quality of air in the city?” Of those surveyed, 78 percent responded that they were satisfied with the quality of air in the city. Based on the results of the survey, which of the following statements must be true? 1. Of all adults in the city, 78 percent are satisfied with the quality of air in the city. 2. If another 1,000 adults selected at random from the city were surveyed, 78 percent of them would report they are satisfied with the quality of air in the city. 3. If 1,000 adults selected at random from a different city were surveyed, 78 percent of them would report they are satisfied with the quality of air in the city.", "fig": null, "rat": "78% is a sample estimate: none of the three statements about exact population or future-sample percentages must be true.", "opts": ["None", "II only", "I and II only", "I and III only"], "ans": "A", "skill": "Evaluating statistical claims: observational studies and experiments"}, {"src": "ID 7ce2830a &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A psychologist designed and conducted a study to determine whether playing a certain educational game increases middle school students’ accuracy in adding fractions. For the study, the psychologist chose a random sample of 35 students from all of the students at one of the middle schools in a large city. The psychologist found that students who played the game showed significant improvement in accuracy when adding fractions. What is the largest group to which the results of the study can be generalized?", "fig": null, "rat": "The random sample came from students at one school, so results generalize to all students at that school.", "opts": ["The 35 students in the sample", "All students at the school", "All middle school students in the city", "All students in the city"], "ans": "B", "skill": "Evaluating statistical claims: observational studies and experiments"}, {"src": "ID b8e73b5b &middot; Algebra", "type": "mc", "stem": "Ken is working this summer as part of a crew on a farm. He earned $8 per hour for the first 10 hours he worked this week. Because of his performance, his crew leader raised his salary to $10 per hour for the rest of the week. Ken saves 90% of his earnings from each week. What is the least number of hours he must work the rest of the week to save at least $270 for the week?", "fig": null, "rat": "Weekly earnings: 8(10)+10h = 80+10h. Saving 90%: 0.9(80+10h) &ge; 270, so 80+10h &ge; 300 and h &ge; 22.", "opts": ["38", "33", "22", "16"], "ans": "C", "skill": "Linear inequalities in one or two variables"}, {"src": "ID 1ea09200 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A sample of 40 fourth-grade students was selected at random from a certain school. The 40 students completed a survey about the morning announcements, and 32 thought the announcements were helpful. Which of the following is the largest population to which the results of the survey can be applied?", "fig": null, "rat": "The sample was drawn at random from fourth-grade students at this school, so results generalize only to all fourth-graders at the school.", "opts": ["The 40 students who were surveyed", "All fourth-grade students at the school", "All students at the school", "All fourth-grade students in the county in which the school is located"], "ans": "B", "skill": "Evaluating statistical claims: observational studies and experiments"}, {"src": "ID 6a305cd0 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "In a study, the data from a random sample of a population had a mean of 37, with an associated margin of error of 3. Which of the following is the most appropriate conclusion that can be made about the population mean?", "fig": null, "rat": "Mean 37 with margin of error 3: plausible population means run from 34 to 40.", "opts": ["It is less than 37.", "It is greater than 37.", "It is between 34 and 40.", "It is less than 34 or greater than 40."], "ans": "C", "skill": "Inference from sample statistics and margin of error"}, {"src": "ID 566759ef &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "Thomas installed a new stove in his restaurant. At the time of installation, the stove had a value of $800. Thomas estimates that each year the value of the stove will depreciate by 20% of the previous year’s estimated value. What is the estimated value of the stove exactly 2 years after Thomas installed it?", "fig": null, "rat": "800(0.80)&sup2; = 800(0.64) = $512.", "opts": ["$480", "$512", "$556", "$640"], "ans": "B", "skill": "Percentages"}, {"src": "ID f89af023 &middot; Advanced Math", "type": "mc", "stem": "A rectangular volleyball court has an area of 162 square meters. If the length of the court is twice the width, what is the width of the court, in meters?", "fig": null, "rat": "Area = length &times; width = (2w)(w) = 2w&sup2; = 162, so w&sup2; = 81 and w = 9 meters.", "opts": ["9", "18", "27", "54"], "ans": "A", "skill": "Nonlinear functions"}, {"src": "ID a8fabad0 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A waiter receives tips from each customer. On average, the tip is 15% of the customer’s bill. At this rate, which of the following is closest to the tip the waiter can expect when a customer has a bill that is $78.20?", "fig": null, "rat": "0.15(78.20) = 11.73, closest to $12.00.", "opts": ["$8.00", "$10.00", "$12.00", "$14.00"], "ans": "C", "skill": "Percentages"}, {"src": "ID 93de3f84 &middot; Geometry &amp; Trigonometry", "type": "mc", "stem": "The volume of right circular cylinder A is 22 cubic centimeters. What is the volume, in cubic centimeters, of a right circular cylinder with twice the radius and half the height of cylinder A?", "fig": null, "rat": "V = &pi;r&sup2;h. New volume: &pi;(2r)&sup2;(h/2) = 2&pi;r&sup2;h = 2(22) = 44.", "opts": ["11", "22", "44", "66"], "ans": "C", "skill": "Area and volume"}, {"src": "ID 37930b2a &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "Residents of a town were surveyed to determine whether they are satisfied with the concession stand at the local park. A random sample of 200 residents was selected. All 200 responded, and 87% said they are satisfied. Based on this information, which of the following statements must be true? I. Of all the town residents, 87% would say they are satisfied with the concession stand at the local park. II. If another random sample of 200 residents were surveyed, 87% would say they are satisfied.", "fig": null, "rat": "A sample percentage is an estimate: it does not guarantee the population value (I) nor the result of another sample (II). Neither must be true.", "opts": ["Neither", "I only", "II only", "I and II"], "ans": "A", "skill": "Evaluating statistical claims: observational studies and experiments"}, {"src": "ID 0108ac2d &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "At a large high school, 300 students were selected at random and were asked in a survey about a menu change in the school cafeteria. All 300 students completed the survey. It was estimated that 38% of the students were in support of a menu change, with a margin of error of 5.5%. Which of the following is the best interpretation of the survey results?", "fig": null, "rat": "38% &plusmn; 5.5% gives a plausible range of 32.5% to 43.5% for the school-wide percentage.", "opts": ["The percent of the students at the school who support a menu change is 38%.", "The percent of the students at the school who support a menu change is greater than 38%.", "Plausible values of the percent of the students at the school who support a menu change are between 32.5% and 43.5%.", "Plausible values of the number of the students at the school who support a menu change are between 295 and 305."], "ans": "C", "skill": "Inference from sample statistics and margin of error"}, {"src": "ID 563407e5 &middot; Algebra", "type": "mc", "stem": "A bakery sells trays of cookies. Each tray contains at least 50 cookies but no more than 60. Which of the following could be the total number of cookies on 4 trays of cookies?", "fig": null, "rat": "Four trays hold between 4(50)=200 and 4(60)=240 cookies. Only 205 falls in that range.", "opts": ["165", "205", "245", "285"], "ans": "B", "skill": "Linear inequalities in one or two variables"}, {"src": "ID 12dbe3de &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A store received a shipment of 1,000 MP3 players, 4 of which were defective. If an MP3 player is randomly selected from this shipment, what is the probability that it is defective?", "fig": null, "rat": "4/1,000 = 0.004.", "opts": ["0.004", "0.04", "0.4", "4"], "ans": "A", "skill": "Probability and conditional probability"}, {"src": "ID 431c3038 &middot; Algebra", "type": "mc", "stem": "In an article about exercise, it is estimated that a 160-pound adult uses 200 calories for every 30 minutes of hiking and 150 calories for every 30 minutes of bicycling. An adult who weighs 160 pounds has completed 1 hour of bicycling. Based on the article, how many hours should the adult hike to use a total of 1,900 calories from bicycling and hiking?", "fig": null, "rat": "One hour of bicycling uses 2(150)=300 calories. The remaining 1,600 calories at 400 calories per hiking hour require 1,600/400 = 4 hours.", "opts": ["9.5", "8.75", "6", "4"], "ans": "D", "skill": "Linear equations in two variables"}, {"src": "ID f7e626b2 &middot; Geometry &amp; Trigonometry", "type": "mc", "stem": "The dimensions of a right rectangular prism are 4 inches by 5 inches by 6 inches. What is the surface area, in square inches, of the prism?", "fig": null, "rat": "Surface area: 2(4&middot;5 + 4&middot;6 + 5&middot;6) = 2(20+24+30) = 148 square inches.", "opts": ["30", "74", "120", "148"], "ans": "D", "skill": "Area and volume"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "An agricultural scientist studying the growth of corn plants recorded the height of a corn plant at the beginning of a study and the height of the plant each day for the next 12 days. The scientist found that the height of the plant increased by an average of 1.20 centimeters per day for the 12 days. If the height of the plant on the last day of the study was 36.8 centimeters, what was the height, in centimeters, of the corn plant at the beginning of the study?", "fig": null, "rat": "The plant grew 12(1.20)=14.4 cm over the study, so the starting height was 36.8&minus;14.4 = 22.4 cm.", "accepted": [22.4], "skill": "Linear equations in one variable"}, {"src": "ID aa43b41f &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "Near the end of a US cable news show, the host invited viewers to respond to a poll on the show’s website that asked, “Do you support the new federal policy discussed during the show?” At the end of the show, the host reported that 28% responded “Yes,” and 70% responded “No.” Which of the following best explains why the results are unlikely to represent the sentiments of the population of the United States?", "fig": null, "rat": "Respondents chose to vote themselves (viewers of one show), so they are not a random sample of the US population.", "opts": ["The percentages do not add up to 100%, so any possible conclusions from the poll are invalid.", "Those who responded to the poll were not a random sample of the population of the United States.", "There were not 50% “Yes” responses and 50% “No” responses.", "The show did not allow viewers enough time to respond to the poll."], "ans": "B", "skill": "Evaluating statistical claims: observational studies and experiments"}, {"src": "ID 9e2bf782 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A fish hatchery has three tanks for holding fish before they are introduced into the wild. Ten fish weighing less than 5 ounces are placed in tank A. Eleven fish weighing at least 5 ounces but no more than 13 ounces are placed in tank B. Twelve fish weighing more than 13 ounces are placed in tank C. Which of the following could be the median of the weights, in ounces, of these 33 fish?", "fig": null, "rat": "The median of 33 weights is the 17th smallest. Positions 11&ndash;21 are tank B fish (5 to 13 ounces), so the median is between 5 and 13: only 8 works.", "opts": ["4.5", "8", "13.5", "15"], "ans": "B", "skill": "One-variable data: distributions and measures of center and spread"}, {"src": "ID f4b3672a &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A certain forest is 253 acres. To estimate the number of trees in the forest, a ranger randomly selects 5 different 1-acre parcels in the forest and determines the number of trees in each parcel. The numbers of trees in the sample acres are 51, 59, 45, 52, and 73. Based on the mean of the sample, which of the following ranges contains the best estimate for the number of trees in the entire forest?", "fig": null, "rat": "Sample mean: (51+59+45+52+73)/5 = 56 trees per acre. Estimate: 56(253) = 14,168 &mdash; in the 13,500 to 14,500 range.", "opts": ["11,000 to 12,000", "12,500 to 13,500", "13,500 to 14,500", "18,000 to 19,000"], "ans": "C", "skill": "Inference from sample statistics and margin of error"}, {"src": "ID 06a152cd &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "To make a bakery’s signature chocolate muffins, a baker needs 2.5 ounces of chocolate for each muffin. How many pounds of chocolate are needed to make 48 signature chocolate muffins? (1 pound = 16 ounces)", "fig": null, "rat": "2.5(48) = 120 ounces = 120/16 = 7.5 pounds.", "opts": ["7.5", "10", "50.5", "120"], "ans": "A", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "ID c88e0663 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "For a school fund-raiser, 10 students sold a total of 90 boxes of cookies. Which of the following can be calculated from this information?", "fig": null, "rat": "Total and count give the mean: 90/10 = 9 boxes per student. Median and extremes require the full distribution.", "opts": ["The average number of boxes sold per student", "The median number of boxes sold per student", "The greatest number of boxes sold by one student", "The least number of boxes sold by one student"], "ans": "A", "skill": "One-variable data: distributions and measures of center and spread"}, {"src": "ID 3f5398a6 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "For a person m miles from a flash of lightning, the length of the time interval from the moment the person sees the lightning to the moment the person hears the thunder is k seconds. The ratio of m to k can be estimated to be 1 to 5. According to this estimate, the person is how many miles from a flash of lightning if the time interval is 25 seconds?", "fig": null, "rat": "m/k = 1/5 with k = 25: m = 25/5 = 5 miles.", "opts": ["10", "9", "6", "5"], "ans": "D", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "ID 8917ce38 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "Which of the following speeds is equivalent to 90 kilometers per hour? (1 kilometer = 1,000 meters)", "fig": null, "rat": "90 km/h = 90,000 m / 3,600 s = 25 meters per second.", "opts": ["25 meters per second", "32 meters per second", "250 meters per second", "324 meters per second"], "ans": "A", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "ID 89f8d08a &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A store manager reviewed the receipts from 80 customers who were selected at random from all the customers who made purchases last Thursday. Of those selected, 20 receipts showed that the customer had purchased fruit. If 1,500 customers made purchases last Thursday, which of the following is the most appropriate conclusion?", "fig": null, "rat": "Sample proportion 20/80 = 25%; applied to 1,500 customers: 375 &mdash; and it is a best estimate, not a certainty.", "opts": ["Exactly 75 customers must have purchased fruit last Thursday.", "Exactly 375 customers must have purchased fruit last Thursday.", "The best estimate for the number of customers who purchased fruit last Thursday is 75.", "The best estimate for the number of customers who purchased fruit last Thursday is 375."], "ans": "D", "skill": "Inference from sample statistics and margin of error"}, {"src": "ID 1180401d &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "The total area of a coastal city is 92.1 square miles, of which 11.3 square miles is water. If the city had a population of 621,000 people in the year 2010, which of the following is closest to the population density, in people per square mile of land area, of the city at that time?", "fig": null, "rat": "Land area: 92.1&minus;11.3 = 80.8 mi&sup2;. Density: 621,000/80.8 &asymp; 7,690 people per square mile.", "opts": ["6,740", "7,690", "55,000", "76,000"], "ans": "B", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "ID 7ac5d686 &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "An inspector begins a day of work with a large sample of shirts that need to be checked for defects. The inspector works at a constant rate throughout the morning. What type of model is best to model the number of shirts remaining to be checked for defects at any given time throughout the morning?", "fig": null, "rat": "Checked at a constant rate, the number remaining falls by the same amount each hour: a linear model with negative slope.", "opts": ["A linear model with a positive slope", "A linear model with a negative slope", "An exponential growth model", "An exponential decay model"], "ans": "B", "skill": "Two-variable data: models and scatterplots"}, {"src": "Official-style &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "Shaquan has 7 red cards and 28 blue cards. What is the ratio of red cards to blue cards that Shaquan has?", "fig": null, "rat": "7 to 28 simplifies to 1 to 4.", "opts": ["1 to 4", "4 to 1", "1 to 7", "7 to 1"], "ans": "A", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "Official-style &middot; Algebra", "type": "mc", "stem": "The solution to the given system of equations is \\((x,y)\\): \\(x=8\\) and \\(y=x+9\\). What is the value of \\(y\\)?", "fig": null, "rat": "Substitute \\(x=8\\): \\(y=8+9=17\\).", "opts": ["8", "9", "17", "72"], "ans": "C", "skill": "Systems of two linear equations in two variables"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "Which expression is equivalent to \\(\\dfrac{x^8}{x^2}\\), where \\(x\\ne 0\\)?", "fig": null, "rat": "Subtract exponents when dividing like bases: \\(x^{8-2}=x^6\\).", "opts": ["\\(x^4\\)", "\\(x^6\\)", "\\(x^{10}\\)", "\\(x^{16}\\)"], "ans": "B", "skill": "Equivalent expressions"}, {"src": "Official-style &middot; Algebra", "type": "mc", "stem": "The function \\(f\\) is defined by \\(f(x)=3x-4\\). What is the value of \\(f(10)\\)?", "fig": null, "rat": "\\(f(10)=3(10)-4=26\\).", "opts": ["3", "10", "26", "34"], "ans": "C", "skill": "Linear equations in one variable"}, {"src": "Official-style &middot; Advanced Math", "type": "spr", "stem": "If \\(\\sqrt{x}+4=11\\), what is the value of \\(x\\)?", "fig": null, "rat": "\\(\\sqrt{x}=7\\), so \\(x=49\\).", "accepted": [49], "skill": "Systems of two linear equations in two variables"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "What value of \\(p\\) satisfies the equation \\(5p+180=250\\)?", "fig": null, "rat": "Subtract 180 from both sides: \\(5p=70\\), so \\(p=14\\).", "accepted": [14], "skill": "Linear functions"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "Line \\(k\\) is defined by \\(y=3x+15\\). Line \\(j\\) is perpendicular to line \\(k\\) in the xy-plane and passes through the point \\((0,-3)\\). What is the slope of line \\(j\\)? (Enter as a fraction or decimal.)", "fig": null, "rat": "Line \\(k\\) has slope 3, so a perpendicular line has slope \\(-\\tfrac{1}{3}\\).", "accepted": [-0.333333], "skill": "Systems of two linear equations in two variables"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "For the linear function \\(f\\), \\(f(0)=8\\), and the graph of \\(y=f(x)\\) in the xy-plane has a slope of 2. What is the value of \\(f(3)\\)?", "fig": null, "rat": "With slope 2 and \\(f(0)=8\\): \\(f(x)=2x+8\\), so \\(f(3)=14\\).", "accepted": [14], "skill": "Linear equations in two variables"}, {"src": "Official-style &middot; Advanced Math", "type": "spr", "stem": "What is the positive solution to the equation \\(x^2-2x-8=0\\)?", "fig": null, "rat": "Factor: \\((x-4)(x+2)=0\\), so \\(x=4\\) or \\(x=-2\\). The positive solution is 4.", "accepted": [4], "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "The equation \\(y=36+18x\\) models the relationship between the height \\(y\\), in inches, of a typical apple tree and the number of years, \\(x\\), after it was planted. If a typical apple tree is 90 inches tall, how many years after it was planted is it?", "fig": null, "rat": "\\(90=36+18x\\) gives \\(18x=54\\), so \\(x=3\\) years.", "accepted": [3], "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "The function \\(g\\) is defined by \\(g(x)=x^2+16\\). For which value of \\(x\\) is \\(g(x)=25\\)?", "fig": null, "rat": "\\(x^2+16=25\\) gives \\(x^2=9\\), so \\(x=\\pm 3\\); of the choices, 3.", "opts": ["3", "5", "9", "41"], "ans": "A", "skill": "Area and volume"}, {"src": "Official-style &middot; Algebra", "type": "mc", "stem": "The graph of \\(9x-10y=19\\) is translated down 4 units in the xy-plane. What is the x-coordinate of the x-intercept of the resulting graph?", "fig": null, "rat": "The translated line is \\(y=\\tfrac{9}{10}x-\\tfrac{19}{10}-4\\). Setting \\(y=0\\): \\(\\tfrac{9}{10}x=\\tfrac{59}{10}\\), so \\(x=\\tfrac{59}{9}\\).", "opts": ["\\(\\tfrac{59}{9}\\)", "\\(\\tfrac{19}{9}\\)", "\\(-\\tfrac{21}{9}\\)", "\\(-\\tfrac{59}{9}\\)"], "ans": "A", "skill": "Linear functions"}, {"src": "ID cfe67646 &middot; Algebra", "type": "mc", "stem": "The point \\((8,2)\\) in the xy-plane is a solution to which of the following systems of inequalities?", "fig": null, "rat": "Testing \\((8,2)\\): it has positive coordinates, so it satisfies \\(x>0\\) and \\(y>0\\). Only choice A requires exactly that.", "opts": ["\\(x>0\\) and \\(y>0\\)", "\\(x>0\\) and \\(y<0\\)", "\\(x<0\\) and \\(y>0\\)", "\\(x<0\\) and \\(y<0\\)"], "ans": "A", "skill": "Linear inequalities in one or two variables"}, {"src": "Official-style &middot; Advanced Math", "type": "spr", "stem": "What is the sum of the solutions to the equation \\((x-6)(x+2)=0\\)?", "fig": null, "rat": "Solutions are \\(x=6\\) and \\(x=-2\\); their sum is 4.", "accepted": [4], "skill": "Nonlinear equations in one variable and systems of equations in two variables"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "Which expression is equivalent to \\(x^{\\frac{6}{5}}\\), where \\(x>0\\)?", "fig": null, "rat": "A fractional exponent \\(\\tfrac{6}{5}\\) means the fifth root of the sixth power: \\(\\sqrt[5]{x^6}\\).", "opts": ["\\(\\sqrt[5]{x^6}\\)", "\\(\\sqrt[6]{x^5}\\)", "\\(\\sqrt{x^5}\\)", "\\(x\\sqrt[5]{x^6}\\)"], "ans": "A", "skill": "Equivalent expressions"}, {"src": "Official-style &middot; Advanced Math", "type": "spr", "stem": "The function \\(h\\) is defined by \\(h(x)=x^2+9\\). What is the value of \\(h(4)\\)?", "fig": null, "rat": "\\(h(4)=16+9=25\\).", "accepted": [25], "skill": "Nonlinear functions"}, {"src": "ID 45cfb9de &middot; Algebra", "type": "mc", "stem": "Adam’s school is a 20-minute walk or a 5-minute bus ride away from his house. The bus runs once every 30 minutes, and the number of minutes, \\(w\\), that Adam waits for the bus varies between 0 and 30. Which of the following inequalities gives the values of \\(w\\) for which it would be faster for Adam to walk to school?", "fig": null, "rat": "Walking takes 20 minutes; the bus takes \\(w+5\\) minutes. Walking is faster when \\(w+5>20\\).", "opts": ["\\(w+5<20\\)", "\\(w+20<5\\)", "\\(w+20>5\\)", "\\(w+5>20\\)"], "ans": "D", "skill": "Linear inequalities in one or two variables"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "The given equation \\(4x+5=165\\) describes the relationship for a purchase. What is the value of \\(x\\)?", "fig": null, "rat": "\\(4x=160\\), so \\(x=40\\).", "accepted": [40], "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "The function \\(f(x)=\\tfrac{1}{9}(x-7)^2+3\\) gives a metal ball’s height above the ground \\(f(x)\\), in inches, \\(x\\) seconds after it started moving on a track, where \\(0\\le x\\le 9\\). Which of the following is the best interpretation of the vertex of the graph of \\(y=f(x)\\) in the xy-plane?", "fig": null, "rat": "The vertex is \\((7,3)\\): at \\(x=7\\) seconds the height reaches its minimum of 3 inches. So: the ball’s minimum height was 3 inches, occurring 7 seconds after it started moving.", "opts": ["The metal ball’s minimum height was 3 inches above the ground.", "The metal ball’s minimum height was 7 inches above the ground.", "The metal ball’s height was 3 inches above the ground when it started moving.", "The metal ball’s height was 7 inches above the ground when it started moving."], "ans": "A", "skill": "Linear equations in two variables"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "The solution to the system \\(x+y=18\\) and \\(y=5x\\) is \\((x,y)\\). What is the value of \\(x\\)?", "fig": null, "rat": "Substitute \\(y=5x\\): \\(x+5x=18\\), so \\(6x=18\\) and \\(x=3\\).", "accepted": [3], "skill": "Systems of two linear equations in two variables"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "The revenue \\(R\\), in dollars, that a company receives from sales of a product is given by \\(R(x)=-x^2+70x\\), where \\(x\\) is the price in dollars of the product. What price \\(x\\) gives the maximum revenue?", "fig": null, "rat": "The parabola opens downward with roots at 0 and 70; the maximum is midway: \\(x=35\\).", "opts": ["25", "35", "45", "70"], "ans": "B", "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "What value of \\(x\\) satisfies \\(\\dfrac{x}{4}=9\\)?", "fig": null, "rat": "Multiply both sides by 4: \\(x=36\\).", "accepted": [36], "skill": "Linear equations in one variable"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "Which of the following expressions is equivalent to \\((x+2)(x^2+3x-4)\\)?", "fig": null, "rat": "Expand: \\(x^3+3x^2-4x+2x^2+6x-8=x^3+5x^2+2x-8\\).", "opts": ["\\(x^3+5x^2+2x-8\\)", "\\(x^3+3x^2-4x-8\\)", "\\(x^3+2x^2+3x-8\\)", "\\(x^3+5x^2-2x-8\\)"], "ans": "A", "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "In the xy-plane, the graph of \\(y=x^2-9\\) intersects the x-axis at the points \\((a,0)\\) and \\((b,0)\\), where \\(a\\) and \\(b\\) are distinct. What is the positive difference between \\(a\\) and \\(b\\)?", "fig": null, "rat": "Roots: \\(x=\\pm 3\\). Positive difference: \\(3-(-3)=6\\).", "opts": ["3", "6", "9", "18"], "ans": "B", "skill": "Nonlinear equations in one variable and systems of equations in two variables"}, {"src": "Official-style &middot; Algebra", "type": "mc", "stem": "Which of the following is the graph’s slope for the line \\(y=-4x+30\\)?", "fig": null, "rat": "The equation is in slope-intercept form; the slope is the coefficient of \\(x\\): \\(-4\\).", "opts": ["\\(-4\\)", "\\(-\\tfrac{1}{4}\\)", "\\(4\\)", "\\(30\\)"], "ans": "A", "skill": "Linear functions"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "The function \\(g\\) is defined by \\(g(x)=10x+8\\). What is the value of \\(g(x)\\) when \\(x=8\\)?", "fig": null, "rat": "\\(g(8)=10(8)+8=88\\).", "accepted": [88], "skill": "Linear functions"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "The population of a city is currently 80,000 and is increasing by 3% each year. Which function models the population \\(P(t)\\) of the city \\(t\\) years from now?", "fig": null, "rat": "Growth of 3% per year multiplies by \\(1.03\\) annually from 80,000: \\(P(t)=80{,}000(1.03)^t\\).", "opts": ["\\(P(t)=80{,}000(1.03)^t\\)", "\\(P(t)=80{,}000(0.03)^t\\)", "\\(P(t)=80{,}000(1.3)^t\\)", "\\(P(t)=80{,}000+1.03t\\)"], "ans": "A", "skill": "Nonlinear equations in one variable and systems of equations in two variables"}, {"src": "ID 4b642eef &middot; Advanced Math", "type": "spr", "stem": "The total distance \\(d\\), in meters, traveled by an object moving in a straight line can be modeled by a quadratic function that is defined in terms of \\(t\\), where \\(t\\) is the time in seconds. At a time of 10.0 seconds, the total distance traveled by the object is 50.0 meters, and at a time of 20.0 seconds, the total distance traveled by the object is 200.0 meters. If the object was at a distance of 0 meters when \\(t=0\\), then what is the total distance traveled, in meters, by the object after 30.0 seconds?", "fig": null, "rat": "Model \\(d=at^2+bt\\) (zero constant term since \\(d(0)=0\\)). From \\(d(10)=50\\): \\(100a+10b=50\\). From \\(d(20)=200\\): \\(400a+20b=200\\). Solving: \\(a=\\tfrac12,\\;b=0\\), so \\(d=\\tfrac12 t^2\\) and \\(d(30)=450\\).", "accepted": [450], "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Algebra", "type": "mc", "stem": "What is the solution \\((x,y)\\) to the given system of equations? \\(y=4x+1\\) and \\(4y=4x-4\\)", "fig": null, "rat": "Substitute \\(y=4x+1\\) into the second equation: \\(4(4x+1)=4x-4\\) gives \\(16x+4=4x-4\\), so \\(12x=-8\\) and \\(x=-\\tfrac{2}{3}\\)&hellip; With integer-friendly checking, solving exactly: \\(x=-\\tfrac{2}{3},\\;y=4(-\\tfrac{2}{3})+1=-\\tfrac{5}{3}\\).", "opts": ["\\(\\left(-\\tfrac{2}{3},-\\tfrac{5}{3}\\right)\\)", "\\((0,1)\\)", "\\(\\left(\\tfrac{2}{3},\\tfrac{5}{3}\\right)\\)", "\\((1,5)\\)"], "ans": "A", "skill": "Linear equations in two variables"}, {"src": "ID 7902bed0 &middot; Advanced Math", "type": "mc", "stem": "A machine launches a softball from ground level. The softball reaches a maximum height of 51.84 meters above the ground at 1.8 seconds and hits the ground at 3.6 seconds. Which equation represents the height above ground \\(h\\), in meters, of the softball \\(t\\) seconds after it is launched?", "fig": null, "rat": "Vertex form with vertex \\((1.8, 51.84)\\) and root \\(t=3.6\\): \\(h=a(t-1.8)^2+51.84\\) with \\(h(3.6)=0\\) gives \\(a(1.8)^2=-51.84\\), so \\(a=-16\\): \\(h=-16(t-1.8)^2+51.84\\).", "opts": ["\\(h=-16(t+1.8)^2+51.84\\)", "\\(h=16(t-1.8)^2+51.84\\)", "\\(h=-51.84(t-1.8)^2+16\\)", "\\(h=-16(t-1.8)^2+51.84\\)"], "ans": "D", "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Algebra", "type": "mc", "stem": "Which of the following ordered pairs \\((x,y)\\) satisfies the inequality \\(5x-3y<4\\)? I. \\((1,1)\\)&ensp;II. \\((2,5)\\)&ensp;III. \\((3,2)\\)", "fig": null, "rat": "Test each pair in \\(5x-3y<4\\): I gives \\(5-3=2<4\\) &#10003;; II gives \\(10-15=-5<4\\) &#10003;; III gives \\(15-6=9\\), not \\(<4\\). So I and II only.", "opts": ["I only", "II only", "I and II only", "I and III only"], "ans": "C", "skill": "Linear functions"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "For the function \\(q\\), the value of \\(q(x)\\) decreases by 45% for every increase in the value of \\(x\\) by 1. If \\(q(0)=14\\), which equation defines \\(q\\)?", "fig": null, "rat": "A 45% decay per unit means multiplying by \\(1-0.45=0.55\\) each step from an initial value of 14: \\(q(x)=14(0.55)^x\\).", "opts": ["\\(q(x)=14(0.55)^x\\)", "\\(q(x)=14(0.45)^x\\)", "\\(q(x)=0.55(14)^x\\)", "\\(q(x)=14(1.45)^x\\)"], "ans": "A", "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Algebra", "type": "mc", "stem": "The total cost \\(C\\), in dollars, to rent a kayak is given by \\(C=15h+12\\), where \\(h\\) is the number of hours the kayak is rented. Which of the following is the best interpretation of 12 in this context?", "fig": null, "rat": "When \\(h=0\\), \\(C=12\\): the 12 is the fixed cost, in dollars, to rent the kayak before any hourly charges.", "opts": ["The fixed cost, in dollars, of renting the kayak", "The cost, in dollars, for each hour the kayak is rented", "The total cost, in dollars, of renting the kayak for one hour", "The number of hours the kayak is rented"], "ans": "A", "skill": "Linear functions"}, {"src": "ID 002dba45 &middot; Algebra", "type": "spr", "stem": "Line \\(k\\) is defined by \\(y=-\\dfrac{17}{3}x+5\\). Line \\(j\\) is perpendicular to line \\(k\\) in the xy-plane. What is the slope of line \\(j\\)?", "fig": null, "rat": "Line \\(k\\) has slope \\(-\\tfrac{17}{3}\\). A perpendicular line has the negative reciprocal slope: \\(\\tfrac{3}{17}\\). (3/17, .1764, and .1765 are all accepted.)", "accepted": [0.17647058823529413, 0.1764, 0.1765], "skill": "Linear equations in two variables"}, {"src": "Official-style &middot; Algebra", "type": "mc", "stem": "A line in the xy-plane has a slope of \\(\\tfrac{1}{9}\\) and passes through the point \\((0,14)\\). Which equation represents this line?", "fig": null, "rat": "Slope-intercept form with \\(m=\\tfrac19\\) and \\(b=14\\): \\(y=\\tfrac{1}{9}x+14\\).", "opts": ["\\(y=-\\tfrac{1}{9}x-14\\)", "\\(y=-\\tfrac{1}{9}x+14\\)", "\\(y=\\tfrac{1}{9}x-14\\)", "\\(y=\\tfrac{1}{9}x+14\\)"], "ans": "D", "skill": "Linear equations in two variables"}, {"src": "Official-style &middot; Advanced Math", "type": "spr", "stem": "What is the minimum value of the function \\(f\\) defined by \\(f(x)=(x-2)^2-4\\)?", "fig": null, "rat": "Vertex form: the minimum value is the constant term at the vertex, \\(-4\\), occurring at \\(x=2\\).", "accepted": [-4], "skill": "Equivalent expressions"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "If \\(2x+3y=11\\) and \\(x=2\\), what is the value of \\(y\\)?", "fig": null, "rat": "Substitute \\(x=2\\): \\(4+3y=11\\), so \\(3y=7\\)&hellip; giving \\(y=\\tfrac{7}{3}\\).", "accepted": [2.333333], "skill": "Linear equations in one variable"}, {"src": "ID e53add44 &middot; Advanced Math", "type": "spr", "stem": "The function \\(f\\) is defined by \\(f(x)=\\dfrac{x+6}{2}\\). What is the value of \\(f(x)\\) when \\(x=4\\)?", "fig": null, "rat": "\\(f(4)=\\dfrac{4+6}{2}=5\\).", "accepted": [5], "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "If \\(6x=42\\) and \\(xc=42\\), what is the value of \\(c\\)?", "fig": null, "rat": "From \\(6x=42\\), \\(x=7\\). Then \\(7c=42\\), so \\(c=6\\).", "accepted": [6], "skill": "Linear equations in one variable"}, {"src": "Official-style &middot; Algebra", "type": "mc", "stem": "A number \\(x\\) is at most 2 less than 3 times the value of \\(y\\). If the value of \\(y\\) is 6, what is the greatest possible value of \\(x\\)?", "fig": null, "rat": "\\(x\\le 3y-2\\). With \\(y=6\\): \\(x\\le 16\\), so the greatest possible value is 16.", "opts": ["4", "8", "16", "20"], "ans": "C", "skill": "Systems of two linear equations in two variables"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "The function \\(f\\) is defined by \\(f(x)=(x+7)(x-4)\\). For what value of \\(x\\) does \\(f(x)\\) reach its minimum?", "fig": null, "rat": "The parabola’s minimum lies midway between the roots \\(-7\\) and \\(4\\): \\(x=\\dfrac{-7+4}{2}=-\\dfrac{3}{2}\\).", "opts": ["\\(-\\tfrac{3}{2}\\)", "\\(-3\\)", "\\(-\\tfrac{11}{2}\\)", "\\(\\tfrac{3}{2}\\)"], "ans": "A", "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Advanced Math", "type": "spr", "stem": "A quantity doubles every 8 hours. The quantity starts at 5 units. After 24 hours, how many units of the quantity are there?", "fig": null, "rat": "24 hours = three doubling periods: \\(5\\cdot 2^3=40\\).", "accepted": [40], "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "What is the y-intercept of the line \\(y=6x+7\\) in the xy-plane? Give the y-coordinate.", "fig": null, "rat": "At the y-intercept \\(x=0\\), so \\(y=7\\).", "accepted": [7], "skill": "Linear equations in two variables"}, {"src": "Official-style &middot; Algebra", "type": "spr", "stem": "What is the x-coordinate of the x-intercept of the line \\(3x+5y=30\\) in the xy-plane?", "fig": null, "rat": "Set \\(y=0\\): \\(3x=30\\), so \\(x=10\\).", "accepted": [10], "skill": "Linear equations in two variables"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "Which expression is equivalent to \\((3x^2+5x)-(2x^2-4x)\\)?", "fig": null, "rat": "Distribute the minus sign and combine like terms: \\(3x^2-2x^2+5x+4x=x^2+9x\\).", "opts": ["\\(x^2+9x\\)", "\\(x^2+x\\)", "\\(5x^2+9x\\)", "\\(x^2-9x\\)"], "ans": "A", "skill": "Linear functions"}, {"src": "Official-style &middot; Advanced Math", "type": "spr", "stem": "What is the positive solution to the equation \\(x^2=121\\)?", "fig": null, "rat": "Take square roots: \\(x=\\pm 11\\); the positive solution is 11.", "accepted": [11], "skill": "Nonlinear equations in one variable and systems of equations in two variables"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "Which expression is equivalent to \\((2x+3)(x-5)\\)?", "fig": null, "rat": "Expand: \\(2x^2-10x+3x-15=2x^2-7x-15\\).", "opts": ["\\(2x^2-7x-15\\)", "\\(2x^2+7x-15\\)", "\\(2x^2-2x-15\\)", "\\(2x^2-13x-15\\)"], "ans": "A", "skill": "Equivalent expressions"}, {"src": "Official-style &middot; Advanced Math", "type": "spr", "stem": "The function \\(f\\) is defined by \\(f(x)=2^x\\). What is the value of \\(f(5)\\)?", "fig": null, "rat": "\\(f(5)=2^5=32\\).", "accepted": [32], "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "Which expression is equivalent to \\(\\sqrt{49x^2}\\), where \\(x>0\\)?", "fig": null, "rat": "\\(\\sqrt{49x^2}=\\sqrt{49}\\cdot\\sqrt{x^2}=7x\\) for positive \\(x\\).", "opts": ["\\(7x\\)", "\\(7x^2\\)", "\\(49x\\)", "\\(24.5x\\)"], "ans": "A", "skill": "Equivalent expressions"}, {"src": "Official-style &middot; Advanced Math", "type": "spr", "stem": "What is the positive solution to the equation \\((x+3)^2=36\\)?", "fig": null, "rat": "\\(x+3=\\pm 6\\), so \\(x=3\\) or \\(x=-9\\); the positive solution is 3.", "accepted": [3], "skill": "Nonlinear equations in one variable and systems of equations in two variables"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "The system \\(y=x^2\\) and \\(y=3x\\) intersects at the origin and at one other point \\((x,y)\\) in the xy-plane. What is the value of \\(y\\) at that other point?", "fig": null, "rat": "\\(x^2=3x\\) gives \\(x(x-3)=0\\); the nonzero solution is \\(x=3\\), so \\(y=3(3)=9\\).", "opts": ["0", "3", "9", "27"], "ans": "C", "skill": "Nonlinear equations in one variable and systems of equations in two variables"}, {"src": "Official-style &middot; Advanced Math", "type": "spr", "stem": "The function \\(g\\) is defined by \\(g(x)=x^3\\). What is the value of \\(g(2)\\)?", "fig": null, "rat": "\\(g(2)=2^3=8\\).", "accepted": [8], "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "Which of the following is equivalent to \\(x^2+6x+5\\)?", "fig": null, "rat": "Find factors of 5 summing to 6: \\((x+1)(x+5)\\).", "opts": ["\\((x+1)(x+5)\\)", "\\((x-1)(x-5)\\)", "\\((x+2)(x+3)\\)", "\\((x+6)(x+5)\\)"], "ans": "A", "skill": "Equivalent expressions"}, {"src": "Official-style &middot; Advanced Math", "type": "spr", "stem": "The function \\(h\\) is defined by \\(h(x)=5(2)^x\\). What is the value of \\(h(3)\\)?", "fig": null, "rat": "\\(h(3)=5\\cdot 2^3=40\\).", "accepted": [40], "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "Which expression is equivalent to \\(3^4\\cdot 3^2\\)?", "fig": null, "rat": "Add exponents with a common base: \\(3^{4+2}=3^6\\).", "opts": ["\\(3^6\\)", "\\(3^8\\)", "\\(9^6\\)", "\\(9^8\\)"], "ans": "A", "skill": "Equivalent expressions"}, {"src": "Official-style &middot; Advanced Math", "type": "spr", "stem": "What is the sum of the solutions to the equation \\((x-9)(x+9)=0\\)?", "fig": null, "rat": "Solutions are \\(9\\) and \\(-9\\); their sum is 0.", "accepted": [0], "skill": "Nonlinear equations in one variable and systems of equations in two variables"}, {"src": "Official-style &middot; Advanced Math", "type": "mc", "stem": "The function \\(f\\) is defined by \\(f(x)=x^2-6x+8\\). Which of the following is an equivalent form of \\(f(x)\\) that displays the coordinates of the vertex of its graph as constants or coefficients?", "fig": null, "rat": "Complete the square: \\(x^2-6x+8=(x-3)^2-1\\), showing the vertex \\((3,-1)\\).", "opts": ["\\((x-3)^2-1\\)", "\\((x-3)^2+1\\)", "\\((x+3)^2-1\\)", "\\((x-4)(x-2)\\)"], "ans": "A", "skill": "Nonlinear functions"}, {"src": "Official-style &middot; Advanced Math", "type": "spr", "stem": "What is the sum of the solutions to the equation \\(|x-5|=3\\)?", "fig": null, "rat": "\\(x-5=\\pm 3\\) gives \\(x=8\\) or \\(x=2\\); the sum is 10.", "accepted": [10], "skill": "Nonlinear equations in one variable and systems of equations in two variables"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "spr", "stem": "A right rectangular prism has a length of 3 inches, a width of 6 inches, and a height of 7 inches. What is the volume, in cubic inches, of the prism?", "fig": null, "rat": "\\(V=3(6)(7)=126\\).", "accepted": [126], "skill": "Area and volume"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "mc", "stem": "A circle has a radius of 5 centimeters. What is the area, in square centimeters, of the circle?", "fig": null, "rat": "\\(A=\\pi r^2=25\\pi\\).", "opts": ["\\(5\\pi\\)", "\\(10\\pi\\)", "\\(25\\pi\\)", "\\(50\\pi\\)"], "ans": "C", "skill": "Circles"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "spr", "stem": "A cube has an edge length of 4 inches. What is the surface area, in square inches, of the cube?", "fig": null, "rat": "Six faces of area \\(4^2=16\\): \\(6(16)=96\\).", "accepted": [96], "skill": "Area and volume"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "mc", "stem": "A right triangle has legs with lengths of 6 centimeters and 8 centimeters. What is the length, in centimeters, of the hypotenuse?", "fig": null, "rat": "\\(\\sqrt{6^2+8^2}=\\sqrt{100}=10\\).", "opts": ["7", "10", "14", "48"], "ans": "B", "skill": "Right triangles and trigonometry"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "spr", "stem": "Two angles of a triangle measure \\(35^\\circ\\) and \\(45^\\circ\\). What is the measure, in degrees, of the third angle?", "fig": null, "rat": "Angles of a triangle sum to 180: \\(180-35-45=100\\).", "accepted": [100], "skill": "Lines, angles, and triangles"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "mc", "stem": "What is the circumference of a circle with a radius of 3 meters?", "fig": null, "rat": "\\(C=2\\pi r=6\\pi\\) meters.", "opts": ["\\(3\\pi\\)", "\\(6\\pi\\)", "\\(9\\pi\\)", "\\(12\\pi\\)"], "ans": "B", "skill": "Circles"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "spr", "stem": "Two angles are complementary. One angle measures \\(28^\\circ\\). What is the measure, in degrees, of the other angle?", "fig": null, "rat": "Complementary angles sum to 90: \\(90-28=62\\).", "accepted": [62], "skill": "Lines, angles, and triangles"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "mc", "stem": "In a right triangle, the measure of one acute angle is \\(20^\\circ\\). If \\(\\sin 20^\\circ = a\\), which of the following is equal to \\(a\\)?", "fig": null, "rat": "Cofunction identity: \\(\\sin\\theta=\\cos(90^\\circ-\\theta)\\), so \\(\\sin 20^\\circ=\\cos 70^\\circ\\).", "opts": ["\\(\\cos 70^\\circ\\)", "\\(\\cos 20^\\circ\\)", "\\(\\sin 70^\\circ\\)", "\\(\\tan 20^\\circ\\)"], "ans": "A", "skill": "Right triangles and trigonometry"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "spr", "stem": "A rectangle has a length of 12 centimeters and a width of 5 centimeters. What is the area, in square centimeters, of the rectangle?", "fig": null, "rat": "\\(A=12(5)=60\\).", "accepted": [60], "skill": "Area and volume"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "mc", "stem": "Triangle A is similar to triangle B, and each side of triangle B is 3 times as long as the corresponding side of triangle A. The area of triangle B is how many times the area of triangle A?", "fig": null, "rat": "Area scales with the square of the length ratio: \\(3^2=9\\).", "opts": ["3", "6", "9", "27"], "ans": "C", "skill": "Lines, angles, and triangles"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "spr", "stem": "In a right triangle, one of the acute angles measures \\(30^\\circ\\). What is the measure, in degrees, of the other acute angle?", "fig": null, "rat": "\\(180-90-30=60\\).", "accepted": [60], "skill": "Lines, angles, and triangles"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "mc", "stem": "What is the volume of a sphere with a radius of 3 inches?", "fig": null, "rat": "\\(V=\\tfrac{4}{3}\\pi r^3=\\tfrac{4}{3}\\pi(27)=36\\pi\\) cubic inches.", "opts": ["\\(12\\pi\\)", "\\(27\\pi\\)", "\\(36\\pi\\)", "\\(108\\pi\\)"], "ans": "C", "skill": "Area and volume"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "spr", "stem": "A square has a perimeter of 36 inches. What is the area, in square inches, of the square?", "fig": null, "rat": "Side \\(=36/4=9\\); area \\(=9^2=81\\).", "accepted": [81], "skill": "Area and volume"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "mc", "stem": "In a right triangle, the legs have lengths 5 and 12. What is the tangent of the angle opposite the leg of length 5?", "fig": null, "rat": "\\(\\tan=\\dfrac{\\text{opposite}}{\\text{adjacent}}=\\dfrac{5}{12}\\).", "opts": ["\\(\\tfrac{5}{12}\\)", "\\(\\tfrac{12}{5}\\)", "\\(\\tfrac{5}{13}\\)", "\\(\\tfrac{12}{13}\\)"], "ans": "A", "skill": "Right triangles and trigonometry"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "spr", "stem": "The hypotenuse of a right triangle has a length of 13 units, and one leg has a length of 5 units. What is the length, in units, of the other leg?", "fig": null, "rat": "\\(\\sqrt{13^2-5^2}=\\sqrt{144}=12\\).", "accepted": [12], "skill": "Right triangles and trigonometry"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "mc", "stem": "What is the volume of a right circular cone with a radius of 3 units and a height of 4 units?", "fig": null, "rat": "\\(V=\\tfrac{1}{3}\\pi r^2 h=\\tfrac{1}{3}\\pi(9)(4)=12\\pi\\).", "opts": ["\\(4\\pi\\)", "\\(12\\pi\\)", "\\(36\\pi\\)", "\\(48\\pi\\)"], "ans": "B", "skill": "Area and volume"}, {"src": "Official-style &middot; Geometry &amp; Trigonometry", "type": "spr", "stem": "An isosceles right triangle has legs of length 7 centimeters. What is the area, in square centimeters, of the triangle?", "fig": null, "rat": "\\(A=\\tfrac12(7)(7)=24.5\\).", "accepted": [24.5], "skill": "Area and volume"}, {"src": "Official-style &middot; Problem-Solving &amp; Data Analysis", "type": "spr", "stem": "What is the mean of the data set 12, 15, 18, 15?", "fig": null, "rat": "\\((12+15+18+15)/4=60/4=15\\).", "accepted": [15], "skill": "One-variable data: distributions and measures of center and spread"}, {"src": "Official-style &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A bag contains 3 red marbles and 7 blue marbles. If one marble is selected at random, what is the probability that it is red?", "fig": null, "rat": "\\(3/(3+7)=3/10=0.3\\).", "opts": ["0.3", "0.7", "0.43", "3"], "ans": "A", "skill": "Probability and conditional probability"}, {"src": "ID 3c8fdc40 &middot; Problem-Solving &amp; Data Analysis", "type": "spr", "stem": "A printer produces posters at a constant rate of 42 posters per minute. At what rate, in posters per <u>hour</u>, does the printer produce the posters?", "fig": null, "rat": "There are 60 minutes in an hour, so the rate is \\(42\\times 60=2{,}520\\) posters per hour.", "accepted": [2520], "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "Official-style &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "How many meters are equivalent to 5 kilometers? (1 kilometer = 1,000 meters)", "fig": null, "rat": "\\(5(1{,}000)=5{,}000\\) meters.", "opts": ["50", "500", "5,000", "50,000"], "ans": "C", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "Official-style &middot; Problem-Solving &amp; Data Analysis", "type": "spr", "stem": "What is the median of the data set 3, 7, 9, 11, 15?", "fig": null, "rat": "The middle value of the five ordered values is 9.", "accepted": [9], "skill": "One-variable data: distributions and measures of center and spread"}, {"src": "Official-style &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A class of 24 students has a ratio of boys to girls of 1 to 2. How many girls are in the class?", "fig": null, "rat": "Parts: \\(1+2=3\\); each part is \\(24/3=8\\); girls \\(=2(8)=16\\).", "opts": ["8", "12", "16", "18"], "ans": "C", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "Official-style &middot; Problem-Solving &amp; Data Analysis", "type": "spr", "stem": "How many quarts are equivalent to 2.5 gallons? (1 gallon = 4 quarts)", "fig": null, "rat": "\\(2.5(4)=10\\).", "accepted": [10], "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "Official-style &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "On a map, 1 inch represents 40 miles. What distance, in miles, is represented by 3.5 inches on the map?", "fig": null, "rat": "\\(3.5(40)=140\\) miles.", "opts": ["43.5", "80", "140", "160"], "ans": "C", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "Official-style &middot; Problem-Solving &amp; Data Analysis", "type": "spr", "stem": "What is the range of the data set 4, 9, 13, 20?", "fig": null, "rat": "Range = maximum &minus; minimum = \\(20-4=16\\).", "accepted": [16], "skill": "One-variable data: distributions and measures of center and spread"}, {"src": "Official-style &middot; Problem-Solving &amp; Data Analysis", "type": "mc", "stem": "A car travels 150 miles in 2.5 hours at a constant speed. What is the speed of the car in miles per hour?", "fig": null, "rat": "\\(150/2.5=60\\) mph.", "opts": ["50", "60", "75", "375"], "ans": "B", "skill": "Ratios, rates, proportional relationships, and units"}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "Use Desmos to solve the equation \\(3x+7=22\\). What is the value of \\(x\\)?", "fig": null, "rat": "Graph \\(y=3x+7\\) and \\(y=22\\); they intersect at \\((5,22)\\), so \\(x=5\\).<br><b>Desmos tip:</b> Type both sides as separate equations and click the intersection point.", "skill": "Desmos graphing techniques", "accepted": [5]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "Using a graph, find the x-intercept of the line \\(y=2x-10\\). What is the x-coordinate?", "fig": null, "rat": "The graph crosses the x-axis where \\(y=0\\): \\(2x-10=0\\) gives \\(x=5\\).<br><b>Desmos tip:</b> Click the gray x-intercept point Desmos highlights automatically.", "skill": "Desmos graphing techniques", "accepted": [5]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "Lines \\(y=2x+1\\) and \\(y=-x+7\\) intersect at point \\((x,y)\\). Use a graph to find \\(x\\).", "fig": null, "rat": "\\(2x+1=-x+7\\) gives \\(3x=6\\), \\(x=2\\).<br><b>Desmos tip:</b> Graph both lines and tap where they cross — Desmos labels the exact point.", "skill": "Desmos graphing techniques", "accepted": [2]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "For the same two lines, \\(y=2x+1\\) and \\(y=-x+7\\), what is the value of \\(y\\) at the intersection point?", "fig": null, "rat": "At \\(x=2\\): \\(y=2(2)+1=5\\).<br><b>Desmos tip:</b> Read the second coordinate of the intersection point.", "skill": "Desmos graphing techniques", "accepted": [5]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "mc", "stem": "The graph of \\(y=x^2-8x+3\\) has a vertex at \\((h,k)\\). Using a graph, what is the value of \\(h\\)?", "fig": null, "rat": "The vertex x-coordinate is \\(-b/2a=8/2=4\\).<br><b>Desmos tip:</b> Desmos marks the minimum point of a parabola — just click it.", "skill": "Desmos graphing techniques", "opts": ["3", "4", "8", "\\(-8\\)"], "ans": "B"}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "Using a graph of \\(y=x^2-8x+3\\), what is the minimum value of \\(y\\)?", "fig": null, "rat": "At \\(x=4\\): \\(y=16-32+3=-13\\).<br><b>Desmos tip:</b> The y-coordinate of the lowest marked point is the minimum value.", "skill": "Desmos graphing techniques", "accepted": [-13]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "Use a graph to find the positive solution of \\(x^2-5x-14=0\\).", "fig": null, "rat": "The graph of \\(y=x^2-5x-14\\) crosses the x-axis at \\(x=-2\\) and \\(x=7\\); the positive solution is 7.<br><b>Desmos tip:</b> Type the equation with =0 or graph y= the left side and click the x-intercepts.", "skill": "Desmos graphing techniques", "accepted": [7]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "How many x-intercepts does the graph of \\(y=x^2-4x+7\\) have?", "fig": null, "rat": "The parabola’s minimum is at \\(y=7-4=3>0\\), so the graph never touches the x-axis: 0 x-intercepts.<br><b>Desmos tip:</b> If the parabola floats above the axis, there are no real solutions — no algebra needed.", "skill": "Desmos graphing techniques", "accepted": [0]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "The graphs of \\(y=|x|-3\\) and \\(y=1\\) are drawn in the same plane. How many intersection points are there?", "fig": null, "rat": "\\(|x|-3=1\\) gives \\(|x|=4\\), so \\(x=\\pm4\\): 2 intersection points.<br><b>Desmos tip:</b> Absolute value graphs are V-shaped; a horizontal line above the vertex cuts it twice.", "skill": "Desmos graphing techniques", "accepted": [2]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "mc", "stem": "A table of values contains the points \\((1,5)\\), \\((2,8)\\), and \\((3,11)\\). Using Desmos regression \\(y_1\\sim mx_1+b\\), what is the value of \\(m\\)?", "fig": null, "rat": "The points are perfectly linear with slope \\((8-5)/(2-1)=3\\); the regression returns \\(m=3\\), \\(b=2\\).<br><b>Desmos tip:</b> Make a table, then type y₁~mx₁+b under it — Desmos fits the line instantly.", "skill": "Desmos graphing techniques", "opts": ["2", "3", "5", "8"], "ans": "B"}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "Use a graph to solve \\(2^x=32\\). What is the value of \\(x\\)?", "fig": null, "rat": "Graph \\(y=2^x\\) and \\(y=32\\): they meet at \\(x=5\\) since \\(2^5=32\\).<br><b>Desmos tip:</b> Intersections work for exponential equations too — no logarithms required.", "skill": "Desmos graphing techniques", "accepted": [5]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "Use a graph to solve the system \\(3x+2y=12\\) and \\(x-y=1\\). What is the value of \\(x\\)? (Enter as a fraction or decimal.)", "fig": null, "rat": "From \\(x-y=1\\), \\(y=x-1\\). Then \\(3x+2(x-1)=12\\) gives \\(5x=14\\), \\(x=2.8\\).<br><b>Desmos tip:</b> Type both equations exactly as written — Desmos graphs implicit lines like 3x+2y=12 directly.", "skill": "Desmos graphing techniques", "accepted": [2.8]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "For the same system, \\(3x+2y=12\\) and \\(x-y=1\\), what is the value of \\(y\\)? (Fraction or decimal.)", "fig": null, "rat": "\\(y=x-1=2.8-1=1.8\\).<br><b>Desmos tip:</b> Both coordinates appear when you click the intersection.", "skill": "Desmos graphing techniques", "accepted": [1.8]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "mc", "stem": "Which point satisfies both \\(y>2x-3\\) and \\(y<x+4\\)?", "fig": null, "rat": "Test \\((1,2)\\): \\(2>-1\\) ✓ and \\(2<5\\) ✓. The others fail one inequality.<br><b>Desmos tip:</b> Type both inequalities — the overlap region is shaded darkest; any point inside it works.", "skill": "Desmos graphing techniques", "opts": ["\\((1,2)\\)", "\\((4,9)\\)", "\\((0,-5)\\)", "\\((5,1)\\)"], "ans": "A"}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "The circle \\(x^2+y^2=25\\) and the line \\(y=x+1\\) intersect at two points. What is the x-coordinate of the intersection point with positive coordinates?", "fig": null, "rat": "Substituting: \\(x^2+(x+1)^2=25\\) gives \\(2x^2+2x-24=0\\), so \\(x=3\\) or \\(x=-4\\). The positive point is \\((3,4)\\).<br><b>Desmos tip:</b> Desmos graphs circles from their equation directly — click each intersection.", "skill": "Desmos graphing techniques", "accepted": [3]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "How many x-intercepts does the graph of \\(y=x^3-6x^2+11x-6\\) have?", "fig": null, "rat": "The cubic factors as \\((x-1)(x-2)(x-3)\\): 3 x-intercepts.<br><b>Desmos tip:</b> Zoom out; every gray point on the x-axis is a real root.", "skill": "Desmos graphing techniques", "accepted": [3]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "Using a graph, what is the maximum value of \\(y=-2(x-3)^2+11\\)?", "fig": null, "rat": "Vertex form: maximum \\(y=11\\) at \\(x=3\\).<br><b>Desmos tip:</b> For downward parabolas Desmos marks the top point — its y-value is the max.", "skill": "Desmos graphing techniques", "accepted": [11]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "Use a graph to solve \\(5(0.8)^x=2.048\\). What is the value of \\(x\\)?", "fig": null, "rat": "\\((0.8)^x=0.4096=(0.8)^4\\), so \\(x=4\\).<br><b>Desmos tip:</b> Exponential decay equations are one intersection click in Desmos.", "skill": "Desmos graphing techniques", "accepted": [4]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "mc", "stem": "A data set contains the points \\((1,2)\\), \\((2,4)\\), and \\((3,8)\\). Which type of model fits these points exactly?", "fig": null, "rat": "Each y-value doubles as x increases by 1 — exponential: \\(y=2^x\\).<br><b>Desmos tip:</b> Try y₁~a·b^x₁ regression; R²=1 confirms a perfect exponential fit.", "skill": "Desmos graphing techniques", "opts": ["Linear", "Quadratic", "Exponential", "Inverse"], "ans": "C"}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "What is the sum of the solutions of \\(|2x-6|=10\\)?", "fig": null, "rat": "\\(2x-6=\\pm10\\) gives \\(x=8\\) or \\(x=-2\\); the sum is 6.<br><b>Desmos tip:</b> Graph y=|2x−6| and y=10; add the x-coordinates of the two intersections.", "skill": "Desmos graphing techniques", "accepted": [6]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "The graphs of \\(y=x^2\\) and \\(y=2x+8\\) intersect at two points. What is the positive x-coordinate of intersection?", "fig": null, "rat": "\\(x^2-2x-8=0\\) factors to \\((x-4)(x+2)=0\\); the positive solution is 4.<br><b>Desmos tip:</b> Parabola-line intersections are exact points in Desmos — click to read them.", "skill": "Desmos graphing techniques", "accepted": [4]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "mc", "stem": "The equation \\((x-2)^2+(y+3)^2=16\\) is graphed. What is the radius of the circle?", "fig": null, "rat": "\\(r^2=16\\), so \\(r=4\\).<br><b>Desmos tip:</b> Graph it and use the axis grid — the circle spans 8 units across.", "skill": "Desmos graphing techniques", "opts": ["2", "4", "8", "16"], "ans": "B"}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "How many x-intercepts does the graph of \\(y=x^4-5x^2+4\\) have?", "fig": null, "rat": "Factor: \\((x^2-1)(x^2-4)\\) gives roots \\(\\pm1,\\pm2\\): 4 x-intercepts.<br><b>Desmos tip:</b> Quartics are hard by hand, instant by graph.", "skill": "Desmos graphing techniques", "accepted": [4]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "What is the greatest solution of \\(x^4-5x^2+4=0\\)?", "fig": null, "rat": "The roots are \\(\\pm1,\\pm2\\); the greatest is 2.<br><b>Desmos tip:</b> The right-most x-intercept is the greatest solution.", "skill": "Desmos graphing techniques", "accepted": [2]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "The graph of \\(y=(x-1)(x-5)\\) is symmetric about a vertical line \\(x=h\\). What is \\(h\\)?", "fig": null, "rat": "The axis of symmetry is midway between the roots: \\((1+5)/2=3\\).<br><b>Desmos tip:</b> The vertex x-coordinate IS the axis of symmetry.", "skill": "Desmos graphing techniques", "accepted": [3]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "What is the distance between the two x-intercepts of \\(y=x^2-2x-24\\)?", "fig": null, "rat": "Roots: \\((x-6)(x+4)=0\\) at \\(6\\) and \\(-4\\); the distance is 10.<br><b>Desmos tip:</b> Subtract the two x-intercept coordinates shown on the graph.", "skill": "Desmos graphing techniques", "accepted": [10]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "For what positive value of \\(b\\) does the graph of \\(y=x^2+bx+16\\) have exactly one x-intercept?", "fig": null, "rat": "One intercept means discriminant zero: \\(b^2-64=0\\), so \\(b=8\\).<br><b>Desmos tip:</b> Add a slider for b and drag until the parabola just touches the axis.", "skill": "Desmos graphing techniques", "accepted": [8]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "mc", "stem": "The graphs of \\(y=x^2-4\\) and \\(y=k\\) have NO intersection points for which values of \\(k\\)?", "fig": null, "rat": "The parabola’s minimum is \\(-4\\); a horizontal line below it never meets the graph: \\(k<-4\\).<br><b>Desmos tip:</b> Use a slider for k and watch when the intersections disappear.", "skill": "Desmos graphing techniques", "opts": ["\\(k<-4\\)", "\\(k>-4\\)", "\\(k<4\\)", "\\(k>4\\)"], "ans": "A"}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "The function \\(f(x)=(x+2)(x-6)\\) reaches its minimum at \\(x=h\\). Use a graph to find \\(h\\).", "fig": null, "rat": "Midpoint of the roots \\(-2\\) and \\(6\\): \\(h=2\\).<br><b>Desmos tip:</b> Click the vertex Desmos marks on the parabola.", "skill": "Desmos graphing techniques", "accepted": [2]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "What is the minimum value of \\(f(x)=(x+2)(x-6)\\)?", "fig": null, "rat": "\\(f(2)=(4)(-4)=-16\\).<br><b>Desmos tip:</b> The vertex y-coordinate is the minimum value.", "skill": "Desmos graphing techniques", "accepted": [-16]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "Use a graph to solve \\(3^x=\\sqrt{81}\\). What is the value of \\(x\\)?", "fig": null, "rat": "\\(\\sqrt{81}=9=3^2\\), so \\(x=2\\).<br><b>Desmos tip:</b> Type sqrt(81) directly — Desmos evaluates it on the graph.", "skill": "Desmos graphing techniques", "accepted": [2]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "A line passes through \\((2,5)\\) and \\((6,13)\\). Using a table and regression, what is the slope of the line?", "fig": null, "rat": "Slope \\(=(13-5)/(6-2)=2\\).<br><b>Desmos tip:</b> Two-point tables with y₁~mx₁+b give slope and intercept instantly.", "skill": "Desmos graphing techniques", "accepted": [2]}, {"src": "Desmos Training &middot; Eng. Ghoneem", "type": "spr", "stem": "For the same line through \\((2,5)\\) and \\((6,13)\\), what is the y-intercept?", "fig": null, "rat": "\\(y=2x+b\\) with \\((2,5)\\): \\(b=1\\).<br><b>Desmos tip:</b> Read b straight from the regression output.", "skill": "Desmos graphing techniques", "accepted": [1]}, {"src": "ID 2b1a27cd &middot; Advanced Math &middot; Hard", "skill": "Nonlinear functions", "type": "spr", "stem": "The quadratic function \\(g\\) models the depth, in meters, below the surface of the water of a seal \\(t\\) minutes after the seal entered the water during a dive. The function estimates that the seal reached its maximum depth of 302.4 meters 6 minutes after it entered the water and then reached the surface of the water 12 minutes after it entered the water. Based on the function, what was the estimated depth, to the nearest meter, of the seal 10 minutes after it entered the water?", "fig": null, "accepted": [168], "rat": "The dive is symmetric: depth 0 at \\(t=0\\) and \\(t=12\\), with the vertex (maximum depth 302.4) at \\(t=6\\). So \\(g(t)=302.4\\left(1-\\left(\\tfrac{t-6}{6}\\right)^{2}\\right)\\). At \\(t=10\\): \\(302.4\\left(1-\\tfrac{16}{36}\\right)=302.4\\cdot\\tfrac{20}{36}=168\\) meters."}, {"src": "ID bc638f2d &middot; Algebra &middot; Easy", "skill": "Linear functions", "type": "mc", "stem": "The function \\(f\\) defined by \\(f(t)=14t+9\\) gives the estimated length, in inches, of a vine plant \\(t\\) months after Tavon purchased it. Which of the following is the best interpretation of 9 in this context?", "fig": null, "opts": ["Tavon will keep the vine plant for 9 months.", "The vine plant is expected to grow 9 inches each month.", "The vine plant is expected to grow to a maximum length of 9 inches.", "The estimated length of the vine plant was 9 inches when Tavon purchased it."], "ans": "D", "rat": "At \\(t=0\\), the moment of purchase, \\(f(0)=9\\): the 9 is the starting length in inches. The 14 is the monthly growth rate."}, {"src": "ID 708590d7 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "One-variable data: distributions and measures of center and spread", "type": "mc", "stem": "Data set A: 1, 2, 3, 4, 5, 6, 7<br>Data set B: 1, 1, 2, 2, 3, 3, 4<br>Which of the following statements correctly compares the means of data set A and data set B?", "fig": null, "opts": ["The mean of each data set is 2.", "The mean of each data set is 4.", "The mean of data set A is less than the mean of data set B.", "The mean of data set A is greater than the mean of data set B."], "ans": "D", "rat": "Mean of A: \\(28/7=4\\). Mean of B: \\(16/7\\approx2.3\\). The mean of A is greater."}, {"src": "ID 98958ae8 &middot; Problem-Solving &amp; Data Analysis &middot; Hard", "skill": "One-variable data: distributions and measures of center and spread", "type": "spr", "stem": "Data set A consists of the heights of 75 objects and has a mean of 25 meters. Data set B consists of the heights of 50 objects and has a mean of 65 meters. Data set C consists of the heights of the 125 objects from data sets A and B. What is the mean, in meters, of data set C?", "fig": null, "accepted": [41], "rat": "Total of all heights: \\(75(25)+50(65)=1{,}875+3{,}250=5{,}125\\). Mean of the combined 125 objects: \\(5{,}125/125=41\\)."}, {"src": "ID 4b7bb316 &middot; Geometry &amp; Trigonometry &middot; Medium", "skill": "Area and volume", "type": "spr", "stem": "The length of each edge of a box is 29 inches. Each side of the box is in the shape of a square. The box does not have a lid. What is the exterior surface area, in square inches, of this box without a lid?", "fig": null, "accepted": [4205], "rat": "A lidless cube has 5 square faces: \\(5(29^{2})=5(841)=4{,}205\\) square inches."}, {"src": "ID ba8ca563 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Area and volume", "type": "spr", "stem": "A cube has a volume of 474,552 cubic units. What is the surface area, in square units, of the cube?", "fig": null, "accepted": [36504], "rat": "Edge length: \\(\\sqrt[3]{474{,}552}=78\\). Surface area: \\(6(78^{2})=6(6{,}084)=36{,}504\\)."}, {"src": "ID 38517165 &middot; Geometry &amp; Trigonometry &middot; Medium", "skill": "Area and volume", "type": "spr", "stem": "A circle has a circumference of \\(31\\pi\\) centimeters. What is the diameter, in centimeters, of the circle?", "fig": null, "accepted": [31], "rat": "Since \\(C=\\pi d\\), the diameter is \\(\\dfrac{31\\pi}{\\pi}=31\\) centimeters."}, {"src": "ID 74d8b897 &middot; Geometry &amp; Trigonometry &middot; Medium", "skill": "Circles", "type": "spr", "stem": "An angle has a measure of \\(\\dfrac{9\\pi}{20}\\) radians. What is the measure of the angle in degrees?", "fig": null, "accepted": [81], "rat": "Multiply by \\(\\tfrac{180}{\\pi}\\): \\(\\dfrac{9\\pi}{20}\\cdot\\dfrac{180}{\\pi}=\\dfrac{9(180)}{20}=81\\) degrees."}, {"src": "ID a0cacec1 &middot; Geometry &amp; Trigonometry &middot; Medium", "skill": "Circles", "type": "spr", "stem": "An angle has a measure of \\(\\dfrac{16\\pi}{15}\\) radians. What is the measure of the angle, in degrees?", "fig": null, "accepted": [192], "rat": "\\(\\dfrac{16\\pi}{15}\\cdot\\dfrac{180}{\\pi}=\\dfrac{16(180)}{15}=192\\) degrees."}, {"src": "ID 186fdbca &middot; Geometry &amp; Trigonometry &middot; Easy", "skill": "Circles", "type": "spr", "stem": "A circle has a diameter of 12.6 centimeters. What is the radius of the circle, in centimeters?", "fig": null, "accepted": [6.3], "rat": "The radius is half the diameter: \\(12.6/2=6.3\\) centimeters."}, {"src": "ID 4757123b &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Area and volume", "type": "spr", "stem": "Trapezoid A and trapezoid B are similar. The length of each side of trapezoid A is 41 times the length of the corresponding side of trapezoid B. The area of trapezoid A is how many times as large as the area of trapezoid B?", "fig": null, "accepted": [1681], "rat": "Area scales with the square of the length ratio: \\(41^{2}=1{,}681\\) times as large."}, {"src": "ID 43744269 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Two-variable data: models and scatterplots", "type": "mc", "stem": "An airplane descends from an altitude of 34,000 feet to 26,000 feet at a constant rate of 800 feet per minute. What type of function best models the relationship between the descending airplane’s altitude and time?", "fig": null, "opts": ["Decreasing exponential", "Decreasing linear", "Increasing exponential", "Increasing linear"], "ans": "B", "rat": "A constant rate of change means a linear model, and a descent means altitude decreases: decreasing linear."}, {"src": "ID 58171b5e &middot; Problem-Solving &amp; Data Analysis &middot; Medium", "skill": "Two-variable data: models and scatterplots", "type": "mc", "stem": "Each year, the value of an investment increases by 5% of its value the previous year. Which of the following functions best models how the value of the investment changes over time?", "fig": null, "opts": ["Decreasing exponential", "Decreasing linear", "Increasing exponential", "Increasing linear"], "ans": "C", "rat": "Increasing by a fixed percent of the previous value multiplies by 1.05 each year, which is exponential growth: increasing exponential."}, {"src": "ID eccbf957 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Probability and conditional probability", "type": "mc", "stem": "Each face of a fair 14-sided die is labeled with a number from 1 through 14, with a different number appearing on each face. If the die is rolled one time, what is the probability of rolling a 2?", "fig": null, "rat": "There are 14 equally likely outcomes and exactly one shows a 2, so the probability is \\(\\tfrac{1}{14}\\).", "opts": ["\\(\\tfrac{1}{14}\\)", "\\(\\tfrac{2}{14}\\)", "\\(\\tfrac{12}{14}\\)", "\\(\\tfrac{13}{14}\\)"], "ans": "A"}, {"src": "ID 1353b86e &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Probability and conditional probability", "type": "mc", "stem": "The table shows the number of different colors of marbles in a bag. If a marble is chosen at random from the bag, what is the probability that the marble will be blue?", "fig": null, "rat": "There are 10 blue marbles out of 40 total, so the probability is \\(\\tfrac{10}{40}\\).", "opts": ["\\(\\tfrac{30}{40}\\)", "\\(\\tfrac{22}{40}\\)", "\\(\\tfrac{18}{40}\\)", "\\(\\tfrac{10}{40}\\)"], "ans": "D", "figHTML": "<table class=\"data-table\"><caption>Colors of Marbles in a Bag</caption><tr><th>Color</th><th>Number</th></tr><tr><th>Red</th><td>8</td></tr><tr><th>Blue</th><td>10</td></tr><tr><th>Green</th><td>22</td></tr><tr><th>Total</th><td>40</td></tr></table>"}, {"src": "ID 46545dd6 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Probability and conditional probability", "type": "mc", "stem": "The table shows the number of students from two different high schools who completed summer internships in each of five years. No student attended both schools. Of the students who completed a summer internship in 2010, which of the following represents the fraction of students who were from Valley High School?", "fig": null, "rat": "In 2010 there were 140 interns in total and 65 of them were from Valley, so the fraction is \\(\\tfrac{65}{140}\\).", "opts": ["\\(\\tfrac{10}{140}\\)", "\\(\\tfrac{65}{140}\\)", "\\(\\tfrac{75}{140}\\)", "\\(\\tfrac{65}{75}\\)"], "ans": "B", "figHTML": "<table class=\"data-table\"><caption>Number of High School Students Who Completed Summer Internships</caption><tr><th>High school</th><th>2008</th><th>2009</th><th>2010</th><th>2011</th><th>2012</th></tr><tr><th>Foothill</th><td>87</td><td>80</td><td>75</td><td>76</td><td>70</td></tr><tr><th>Valley</th><td>44</td><td>54</td><td>65</td><td>76</td><td>82</td></tr><tr><th>Total</th><td>131</td><td>134</td><td>140</td><td>152</td><td>152</td></tr></table>"}, {"src": "ID 0301c5dc &middot; Problem-Solving &amp; Data Analysis &middot; Medium", "skill": "Probability and conditional probability", "type": "mc", "stem": "The table shows the number of state parks in a certain state that contain camping facilities and bicycle paths. If one of these state parks is selected at random, what is the probability that it has camping facilities but does not have bicycle paths?", "fig": null, "rat": "The total number of parks is \\(20+5+8+4=37\\). Of these, 5 have camping facilities but no bicycle paths, so the probability is \\(\\tfrac{5}{37}\\).", "opts": ["\\(\\tfrac{5}{37}\\)", "\\(\\tfrac{5}{25}\\)", "\\(\\tfrac{8}{28}\\)", "\\(\\tfrac{5}{9}\\)"], "ans": "A", "figHTML": "<table class=\"data-table\"><tr><th></th><th>Has bicycle paths</th><th>Does not have bicycle paths</th></tr><tr><th>Has camping facilities</th><td>20</td><td>5</td></tr><tr><th>Does not have camping facilities</th><td>8</td><td>4</td></tr></table>"}, {"src": "ID 47624288 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Probability and conditional probability", "type": "mc", "stem": "The table gives the distribution of votes for a new school mascot and grade level for 80 students. If one of these students is selected at random, what is the probability of selecting a student whose vote for new mascot was for a lion?", "fig": null, "rat": "Of the 80 votes, 20 were for a lion, so the probability is \\(\\tfrac{20}{80}=\\tfrac{1}{4}\\).", "opts": ["\\(\\tfrac{1}{9}\\)", "\\(\\tfrac{1}{5}\\)", "\\(\\tfrac{1}{4}\\)", "\\(\\tfrac{2}{3}\\)"], "ans": "C", "figHTML": "<table class=\"data-table\"><caption>Grade level</caption><tr><th>Mascot</th><th>Sixth</th><th>Seventh</th><th>Eighth</th><th>Total</th></tr><tr><th>Badger</th><td>4</td><td>9</td><td>9</td><td>22</td></tr><tr><th>Lion</th><td>9</td><td>2</td><td>9</td><td>20</td></tr><tr><th>Longhorn</th><td>4</td><td>6</td><td>4</td><td>14</td></tr><tr><th>Tiger</th><td>6</td><td>9</td><td>9</td><td>24</td></tr><tr><th>Total</th><td>23</td><td>26</td><td>31</td><td>80</td></tr></table>"}, {"src": "ID 2905ded0 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Probability and conditional probability", "type": "mc", "stem": "The table summarizes members of a local organization by age and whether they live east or west of the river. If a member of the organization is selected at random, what is the probability that the selected member is at least 40 years old?", "fig": null, "rat": "Of the 135 members, 107 are at least 40 years old, so the probability is \\(\\tfrac{107}{135}\\).", "opts": ["\\(\\tfrac{28}{135}\\)", "\\(\\tfrac{35}{135}\\)", "\\(\\tfrac{100}{135}\\)", "\\(\\tfrac{107}{135}\\)"], "ans": "D", "figHTML": "<table class=\"data-table\"><tr><th></th><th>Live east of the river</th><th>Live west of the river</th><th>Total</th></tr><tr><th>Less than 40 years old</th><td>17</td><td>11</td><td>28</td></tr><tr><th>At least 40 years old</th><td>18</td><td>89</td><td>107</td></tr><tr><th>Total</th><td>35</td><td>100</td><td>135</td></tr></table>"}, {"src": "ID ec7b0eb8 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Probability and conditional probability", "type": "mc", "stem": "In a study of cell phone use, 799 randomly selected US teens were asked how often they talked on a cell phone and about their texting behavior. The data are summarized in the table. If one of the 799 teens surveyed is selected at random, what is the probability that the teen talks on a cell phone daily?", "fig": null, "rat": "Of the 799 teens, 415 talk on a cell phone daily, so the probability is \\(\\tfrac{415}{799}\\).", "opts": ["\\(\\tfrac{1}{799}\\)", "\\(\\tfrac{415}{799}\\)", "\\(\\tfrac{384}{415}\\)", "\\(\\tfrac{384}{799}\\)"], "ans": "B", "figHTML": "<table class=\"data-table\"><tr><th>Texting behavior</th><th>Talks on cell phone daily</th><th>Does not talk on cell phone daily</th><th>Total</th></tr><tr><th>Light</th><td>110</td><td>146</td><td>256</td></tr><tr><th>Medium</th><td>139</td><td>164</td><td>303</td></tr><tr><th>Heavy</th><td>166</td><td>74</td><td>240</td></tr><tr><th>Total</th><td>415</td><td>384</td><td>799</td></tr></table>"}, {"src": "ID 2a08d878 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Probability and conditional probability", "type": "mc", "stem": "There are \\(n\\) nonfiction books and 12 fiction books on a bookshelf. If one of these books is selected at random, what is the probability of selecting a nonfiction book, in terms of \\(n\\)?", "fig": null, "rat": "The shelf holds \\(n+12\\) books in total and \\(n\\) of them are nonfiction, so the probability is \\(\\dfrac{n}{n+12}\\).", "opts": ["\\(\\dfrac{n}{12}\\)", "\\(\\dfrac{n}{n+12}\\)", "\\(\\dfrac{12}{n}\\)", "\\(\\dfrac{12}{n+12}\\)"], "ans": "B"}, {"src": "ID a478f9f5 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Probability and conditional probability", "type": "mc", "stem": "Each of 157 gemstones can be classified as one of three classifications, as shown in the frequency table. If one of the gemstones is selected at random, what is the probability of selecting a gemstone of color Y?", "fig": null, "rat": "There are 3 gemstones of color Y out of 157 total, so the probability is \\(\\tfrac{3}{157}\\).", "opts": ["\\(\\tfrac{3}{157}\\)", "\\(\\tfrac{35}{157}\\)", "\\(\\tfrac{119}{157}\\)", "\\(\\tfrac{154}{157}\\)"], "ans": "A", "figHTML": "<table class=\"data-table\"><tr><th>Classification</th><th>Frequency</th></tr><tr><th>color X</th><td>119</td></tr><tr><th>color Y</th><td>3</td></tr><tr><th>color Z</th><td>35</td></tr></table>"}, {"src": "ID 5dc386fb &middot; Problem-Solving &amp; Data Analysis &middot; Hard", "skill": "Probability and conditional probability", "type": "mc", "stem": "The table shows the distribution of US states according to whether they have a state-level sales tax and a state-level income tax. To the nearest tenth of a percent, what percent of states with a state-level sales tax do not have a state-level income tax?", "fig": null, "rat": "States with a sales tax: \\(39+6=45\\). Of those, 6 have no income tax: \\(\\tfrac{6}{45}=0.1333\\), or about 13.3%.", "opts": ["6.0%", "12.0%", "13.3%", "14.0%"], "ans": "C", "figHTML": "<table class=\"data-table\"><caption>2013 State-Level Taxes</caption><tr><th></th><th>State sales tax</th><th>No state sales tax</th></tr><tr><th>State income tax</th><td>39</td><td>4</td></tr><tr><th>No state income tax</th><td>6</td><td>1</td></tr></table>"}, {"src": "ID b8150b17 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Probability and conditional probability", "type": "mc", "stem": "For a particular machine that produces beads, 29 out of every 100 beads it produces have a defect. A bead produced by the machine will be selected at random. What is the probability of selecting a bead that has a defect?", "fig": null, "rat": "A rate of 29 defective per 100 produced gives a probability of \\(\\tfrac{29}{100}\\).", "opts": ["\\(\\tfrac{1}{2{,}900}\\)", "\\(\\tfrac{1}{29}\\)", "\\(\\tfrac{29}{100}\\)", "\\(\\tfrac{29}{10}\\)"], "ans": "C"}, {"src": "ID 0a99e5bb &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Probability and conditional probability", "type": "mc", "stem": "The data set \\(-13,\\;4,\\;23\\) is shown. If a number from this data set is selected at random, what is the probability of selecting a negative number?", "fig": null, "rat": "Only \\(-13\\) is negative, out of 3 numbers, so the probability is \\(\\tfrac{1}{3}\\).", "opts": ["0", "\\(\\tfrac{1}{3}\\)", "\\(\\tfrac{2}{3}\\)", "1"], "ans": "B"}, {"src": "ID ecf8d15f &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Probability and conditional probability", "type": "mc", "stem": "A total of 50 children attended a summer camp and were offered 4 types of sandwiches. The table shows the number of children who chose each type of sandwich. If one of these children is selected at random, what is the probability of selecting a child who chose a vegetarian sandwich?", "fig": null, "rat": "Of the 50 children, 9 chose a vegetarian sandwich, so the probability is \\(\\tfrac{9}{50}\\).", "opts": ["\\(\\tfrac{9}{100}\\)", "\\(\\tfrac{9}{50}\\)", "\\(\\tfrac{1}{4}\\)", "\\(\\tfrac{9}{10}\\)"], "ans": "B", "figHTML": "<table class=\"data-table\"><tr><th>Type of sandwich</th><th>Number of children</th></tr><tr><th>Turkey</th><td>15</td></tr><tr><th>Chicken</th><td>23</td></tr><tr><th>Ham</th><td>3</td></tr><tr><th>Vegetarian</th><td>9</td></tr><tr><th>Total</th><td>50</td></tr></table>"}, {"src": "ID 6a715bed &middot; Problem-Solving &amp; Data Analysis &middot; Hard", "skill": "Probability and conditional probability", "type": "spr", "stem": "The table summarizes the distribution of age and assigned group for 90 participants in a study. One of these participants will be selected at random. What is the probability of selecting a participant from group A, given that the participant is at least 10 years of age? (Express your answer as a decimal or fraction, not as a percent.)", "fig": null, "rat": "Participants at least 10 years old: the \\(10\\text{--}19\\) and \\(20+\\) columns total \\(30+30=60\\). Of those, group A has \\(14+9=23\\). So the conditional probability is \\(\\tfrac{23}{60}\\approx.3833\\).", "accepted": [0.38333333333333336, 0.3833, 0.383], "figHTML": "<table class=\"data-table\"><tr><th></th><th>0&ndash;9 years</th><th>10&ndash;19 years</th><th>20+ years</th><th>Total</th></tr><tr><th>Group A</th><td>7</td><td>14</td><td>9</td><td>30</td></tr><tr><th>Group B</th><td>6</td><td>4</td><td>20</td><td>30</td></tr><tr><th>Group C</th><td>17</td><td>12</td><td>1</td><td>30</td></tr><tr><th>Total</th><td>30</td><td>30</td><td>30</td><td>90</td></tr></table>"}, {"src": "ID 89ff6a0a &middot; Problem-Solving &amp; Data Analysis &middot; Hard", "skill": "Probability and conditional probability", "type": "spr", "stem": "For 100 buttons, the table summarizes the distribution by group and diameter. One of these buttons will be selected at random. What is the probability of selecting a button with a diameter that is less than or equal to 30 millimeters, given that it is <b>not</b> in group 2? (Express your answer as a decimal or fraction, not as a percent.)", "fig": null, "rat": "Buttons not in group 2: group 1 has \\(12+8+3=23\\) and group 3 has \\(10+32+0=42\\), for 65 buttons. Of those, with diameter at most 30: group 1 gives \\(12+8=20\\) and group 3 gives \\(10+32=42\\), for 62. So the probability is \\(\\tfrac{62}{65}\\approx.9538\\).", "accepted": [0.9538461538461539, 0.9538], "figHTML": "<table class=\"data-table\"><caption>Diameter (millimeters)</caption><tr><th>Group</th><th>Less than 20</th><th>20 to 30</th><th>Greater than 30</th></tr><tr><th>Group 1</th><td>12</td><td>8</td><td>3</td></tr><tr><th>Group 2</th><td>0</td><td>17</td><td>18</td></tr><tr><th>Group 3</th><td>10</td><td>32</td><td>0</td></tr></table>"}, {"src": "ID f496d2c0 &middot; Problem-Solving &amp; Data Analysis &middot; Hard", "skill": "Probability and conditional probability", "type": "mc", "stem": "The table shows the distribution of rooms in a certain facility by seating capacity. If a room in this facility is selected at random, which of the following is closest to the probability of selecting a room that has a seating capacity greater than 65 seats, given that the room has a seating capacity of at least 18 seats?", "fig": null, "rat": "Rooms with at least 18 seats make up \\(21\\%+29\\%+24\\%=74\\%\\). Of the whole facility, 24% have more than 65 seats. The conditional probability is \\(\\tfrac{0.24}{0.74}\\approx0.32\\).", "opts": ["0.24", "0.32", "0.50", "0.92"], "ans": "B", "figHTML": "<table class=\"data-table\"><tr><th>Seating capacity</th><th>Proportion</th></tr><tr><th>Less than 18 seats</th><td>26%</td></tr><tr><th>18&ndash;40 seats</th><td>21%</td></tr><tr><th>41&ndash;65 seats</th><td>29%</td></tr><tr><th>Greater than 65 seats</th><td>24%</td></tr></table>"}, {"src": "ID a4c0547f &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Right triangles and trigonometry", "type": "mc", "stem": "In triangle \\(XYZ\\), angle \\(Z\\) is a right angle and the length of \\(\\overline{YZ}\\) is 24 units. If \\(\\tan X=\\tfrac{12}{35}\\), what is the perimeter, in units, of triangle \\(XYZ\\)?", "fig": null, "rat": "\\(\\tan X=\\dfrac{YZ}{XZ}=\\dfrac{24}{XZ}=\\dfrac{12}{35}\\), so \\(XZ=70\\). Then \\(XY=\\sqrt{70^2+24^2}=\\sqrt{5{,}476}=74\\). Perimeter: \\(24+70+74=168\\).", "opts": ["188", "168", "84", "71"], "ans": "B"}, {"src": "ID b0c5ece5 &middot; Geometry &amp; Trigonometry &middot; Easy", "skill": "Right triangles and trigonometry", "type": "mc", "stem": "A right triangle has a hypotenuse of length 19 and legs of length 4 and \\(b\\). Which equation shows the relationship between the side lengths of the given triangle?", "fig": null, "rat": "By the Pythagorean theorem the squares of the legs sum to the square of the hypotenuse: \\(4^2+b^2=19^2\\).", "opts": ["\\(4b=19\\)", "\\(4+b=19\\)", "\\(4^2+b^2=19^2\\)", "\\(4^2-b^2=19^2\\)"], "ans": "C"}, {"src": "ID 5a7e3b46 &middot; Geometry &amp; Trigonometry &middot; Medium", "skill": "Right triangles and trigonometry", "type": "mc", "stem": "In \\(\\triangle ABC\\), \\(\\angle B\\) is a right angle and the length of \\(\\overline{BC}\\) is 136 millimeters. If \\(\\cos A=\\tfrac{3}{5}\\), what is the length, in millimeters, of \\(\\overline{AB}\\)?", "fig": null, "rat": "\\(\\cos A=\\dfrac{AB}{AC}=\\dfrac{3}{5}\\), so \\(AB=3a\\) and \\(AC=5a\\). Then \\(BC^2=(5a)^2-(3a)^2=16a^2\\), so \\(BC=4a\\). From \\(4a=136\\), \\(a=34\\), giving \\(AB=3(34)=102\\).", "opts": ["34", "102", "136", "170"], "ans": "B"}, {"src": "ID 498d6795 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Right triangles and trigonometry", "type": "mc", "stem": "In triangle \\(ABC\\), angle \\(B\\) is a right angle. The length of side \\(AB\\) is \\(10\\sqrt{37}\\) and the length of side \\(BC\\) is \\(24\\sqrt{37}\\). What is the length of side \\(AC\\)?", "fig": null, "rat": "\\(AC^2=(10\\sqrt{37})^2+(24\\sqrt{37})^2=100(37)+576(37)=676(37)\\). So \\(AC=\\sqrt{676}\\sqrt{37}=26\\sqrt{37}\\).", "opts": ["\\(14\\sqrt{37}\\)", "\\(26\\sqrt{37}\\)", "\\(34\\sqrt{37}\\)", "\\(\\sqrt{34\\cdot37}\\)"], "ans": "B"}, {"src": "ID a6097ec2 &middot; Geometry &amp; Trigonometry &middot; Easy", "skill": "Right triangles and trigonometry", "type": "mc", "stem": "A right triangle has a hypotenuse of length 73 and legs of length 63 and 10, where the angle measuring \\(x^\\circ\\) is opposite the leg of length 63. What is the value of \\(\\sin x^\\circ\\)?", "fig": null, "rat": "The sine of an acute angle is the opposite leg over the hypotenuse: \\(\\sin x^\\circ=\\tfrac{63}{73}\\).", "opts": ["\\(\\tfrac{1}{73}\\)", "\\(\\tfrac{10}{73}\\)", "\\(\\tfrac{63}{73}\\)", "\\(\\tfrac{136}{73}\\)"], "ans": "C"}, {"src": "ID 6ab30ce3 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Right triangles and trigonometry", "type": "mc", "stem": "Triangle \\(ABC\\) is similar to triangle \\(DEF\\), where \\(A\\) corresponds to \\(D\\) and \\(C\\) corresponds to \\(F\\). Angles \\(C\\) and \\(F\\) are right angles. If \\(\\tan A=\\sqrt{3}\\) and \\(DF=125\\), what is the length of \\(\\overline{DE}\\)?", "fig": null, "rat": "Similar triangles give \\(\\tan D=\\tan A=\\sqrt3\\), so \\(D=60^\\circ\\) and \\(DEF\\) is a 30-60-90 triangle with the right angle at \\(F\\). Then \\(\\overline{DE}\\) is the hypotenuse and \\(DF\\) the short leg, so \\(DE=2(125)=250\\).", "opts": ["\\(125\\tfrac{\\sqrt3}{3}\\)", "\\(125\\tfrac{\\sqrt3}{2}\\)", "\\(125\\sqrt3\\)", "250"], "ans": "D"}, {"src": "ID 16d66178 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Right triangles and trigonometry", "type": "mc", "stem": "Which of the following expressions is equivalent to \\((\\sin 24^\\circ)(\\cos 66^\\circ)+(\\cos 24^\\circ)(\\sin 66^\\circ)\\)?", "fig": null, "rat": "Angles 24&deg; and 66&deg; are complementary, so \\(\\sin 24^\\circ=\\cos 66^\\circ\\) and \\(\\sin 66^\\circ=\\cos 24^\\circ\\). Substituting gives \\((\\cos 66^\\circ)^2+(\\cos 24^\\circ)^2\\).", "opts": ["\\(2(\\cos 66^\\circ)(\\sin 24^\\circ)\\)", "\\(2(\\cos 66^\\circ)+2(\\sin 24^\\circ)\\)", "\\((\\cos 66^\\circ)^2+(\\cos 24^\\circ)^2\\)", "\\((\\cos 66^\\circ)^2+(\\sin 24^\\circ)^2\\)"], "ans": "C"}, {"src": "ID ae041e52 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Right triangles and trigonometry", "type": "mc", "stem": "A square is inscribed in a circle. The radius of the circle is \\(\\dfrac{20\\sqrt2}{2}\\) inches. What is the side length, in inches, of the square?", "fig": null, "rat": "The diameter is \\(2\\cdot\\dfrac{20\\sqrt2}{2}=20\\sqrt2\\), which is the square’s diagonal. For a square, diagonal \\(=s\\sqrt2\\), so \\(s\\sqrt2=20\\sqrt2\\) and \\(s=20\\).", "opts": ["20", "\\(\\tfrac{20\\sqrt2}{2}\\)", "\\(20\\sqrt2\\)", "40"], "ans": "A"}, {"src": "ID 7c25b0dc &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Right triangles and trigonometry", "type": "spr", "stem": "The length of a rectangle’s diagonal is \\(3\\sqrt{17}\\), and the length of the rectangle’s shorter side is 3. What is the length of the rectangle’s longer side?", "fig": null, "rat": "The sides and diagonal form a right triangle: \\(a^2+3^2=(3\\sqrt{17})^2=153\\), so \\(a^2=144\\) and \\(a=12\\).", "accepted": [12]}, {"src": "ID a67b9f88 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Right triangles and trigonometry", "type": "spr", "stem": "In right triangle \\(RST\\), the right angle is at \\(S\\), the hypotenuse \\(\\overline{RT}\\) has length 53, and \\(RS=\\sqrt{105}\\). What is the value of \\(\\sin R\\)?", "fig": null, "rat": "The other leg: \\(TS=\\sqrt{53^2-105}=\\sqrt{2{,}809-105}=\\sqrt{2{,}704}=52\\). The side opposite \\(R\\) is \\(TS\\), so \\(\\sin R=\\tfrac{52}{53}\\approx.9811\\).", "accepted": [0.9811320754716981, 0.9811]}, {"src": "ID 1bf809b5 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Right triangles and trigonometry", "type": "spr", "stem": "In a right triangle, the leg adjacent to the angle measuring \\(x^\\circ\\) has length 11 and the hypotenuse has length 28. What is the value of \\(\\cos x^\\circ\\)?", "fig": null, "rat": "Cosine is the adjacent leg over the hypotenuse: \\(\\cos x^\\circ=\\tfrac{11}{28}\\approx.3928\\).", "accepted": [0.39285714285714285, 0.3928, 0.3929, 0.393]}, {"src": "ID 54df8076 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Right triangles and trigonometry", "type": "spr", "stem": "The perimeter of an equilateral triangle is 852 centimeters. The three vertices of the triangle lie on a circle. The radius of the circle is \\(w\\sqrt3\\) centimeters. What is the value of \\(w\\)?", "fig": null, "rat": "Each side is \\(852/3=284\\) cm. For an equilateral triangle the circumradius is \\(\\dfrac{s}{\\sqrt3}=\\dfrac{284}{\\sqrt3}=\\dfrac{284\\sqrt3}{3}\\). Setting \\(w\\sqrt3=\\dfrac{284\\sqrt3}{3}\\) gives \\(w=\\tfrac{284}{3}\\approx94.67\\).", "accepted": [94.66666666666667, 94.66, 94.67]}, {"src": "ID ebbf23ae &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Circles", "type": "spr", "stem": "A circle in the xy-plane has a diameter with endpoints \\((2,4)\\) and \\((2,14)\\). An equation of this circle is \\((x-2)^2+(y-9)^2=r^2\\), where \\(r\\) is a positive constant. What is the value of \\(r\\)?", "fig": null, "rat": "The center \\((2,9)\\) is the midpoint of the diameter. The radius is the distance to an endpoint: \\(\\sqrt{(2-2)^2+(9-4)^2}=5\\).", "accepted": [5]}, {"src": "ID 267f82b5 &middot; Geometry &amp; Trigonometry &middot; Medium", "skill": "Circles", "type": "mc", "stem": "A circle in the xy-plane has the equation \\((x-19)^2+(y-17)^2=64k^2\\), where \\(k\\) is a positive constant. Which of the following gives the center of the circle and its radius?", "fig": null, "rat": "Comparing with \\((x-h)^2+(y-p)^2=r^2\\): the center is \\((19,17)\\) and \\(r^2=64k^2\\), so \\(r=8k\\).", "opts": ["The center is at \\((19,17)\\), and the radius is 8.", "The center is at \\((19,17)\\), and the radius is \\(8k\\).", "The center is at \\((19,17)\\), and the radius is 64.", "The center is at \\((19,17)\\), and the radius is \\(64k\\)."], "ans": "B"}, {"src": "ID 800e71b8 &middot; Geometry &amp; Trigonometry &middot; Medium", "skill": "Circles", "type": "mc", "stem": "Points \\(M\\), \\(N\\), and \\(P\\) lie on a circle. On this circle, minor arc \\(MN\\) has a length of 39 centimeters and major arc \\(MPN\\) has a length of 195 centimeters. What is the circumference, in centimeters, of the circle?", "fig": null, "rat": "The two arcs share endpoints and together form the whole circle, so the circumference is \\(39+195=234\\) centimeters.", "opts": ["39", "156", "195", "234"], "ans": "D"}, {"src": "ID c8345903 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Circles", "type": "mc", "stem": "A circle has center \\(O\\). The length of arc \\(ADC\\) is \\(5\\pi\\), and the central angle for arc \\(ADC\\) measures \\(100^\\circ\\). What is the length of arc \\(ABC\\)?", "fig": null, "rat": "Arc \\(ABC\\) is subtended by the rest of the circle: \\(360-100=260^\\circ\\). Arc lengths are proportional to central angles: \\(\\dfrac{s}{5\\pi}=\\dfrac{260}{100}=\\dfrac{13}{5}\\), so \\(s=13\\pi\\).", "opts": ["\\(9\\pi\\)", "\\(13\\pi\\)", "\\(18\\pi\\)", "\\(\\tfrac{13}{2}\\pi\\)"], "ans": "B"}, {"src": "ID 149021da &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Circles", "type": "spr", "stem": "A circle has center \\(P\\), and points \\(A\\) and \\(B\\) lie on the circle. The measure of arc \\(AB\\) is \\(45^\\circ\\) and the length of arc \\(AB\\) is \\(4\\pi\\) units. What is the length, in units, of the radius of the circle?", "fig": null, "rat": "Arc length is the same fraction of the circumference as the arc measure is of 360&deg;: \\(\\dfrac{45}{360}=\\dfrac{4\\pi}{2\\pi r}\\), so \\(\\tfrac18=\\tfrac{2}{r}\\) and \\(r=16\\).", "accepted": [16]}, {"src": "ID a5ff1a96 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Circles", "type": "mc", "stem": "In the xy-plane, circle \\(M\\) is the graph of the equation \\((x-4)^2+(y-5)^2=9\\). Circle \\(P\\) has the same center as circle \\(M\\) but has a radius that is twice the radius of circle \\(M\\). Which equation represents circle \\(P\\)?", "fig": null, "rat": "Circle \\(M\\) has center \\((4,5)\\) and radius 3. Doubling gives radius 6, so \\((x-4)^2+(y-5)^2=6^2=36\\).", "opts": ["\\((x-4)^2+(y-5)^2=18\\)", "\\((x-4)^2+(y-5)^2=36\\)", "\\((x-8)^2+(y-10)^2=9\\)", "\\((x-8)^2+(y-10)^2=18\\)"], "ans": "B"}, {"src": "ID 89661424 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Circles", "type": "spr", "stem": "A circle in the xy-plane has its center at \\((-5,2)\\) and has a radius of 9. An equation of this circle is \\(x^2+y^2+ax+by+c=0\\), where \\(a\\), \\(b\\), and \\(c\\) are constants. What is the value of \\(c\\)?", "fig": null, "rat": "Standard form: \\((x+5)^2+(y-2)^2=81\\). Expanding: \\(x^2+10x+25+y^2-4y+4=81\\), so \\(x^2+y^2+10x-4y-52=0\\). Thus \\(c=-52\\).", "accepted": [-52]}, {"src": "ID 27f1db42 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Circles", "type": "spr", "stem": "In the xy-plane, circle \\(F\\) is defined by the equation \\((x+8)^2+(y+8)^2=25\\). Circle \\(G\\) has the same center as circle \\(F\\), and the radius of circle \\(G\\) is 2 units greater than the radius of circle \\(F\\). Circle \\(G\\) is defined by the equation \\((x+8)^2+(y+8)^2=p\\), where \\(p\\) is a constant. What is the value of \\(p\\)?", "fig": null, "rat": "Circle \\(F\\) has radius \\(\\sqrt{25}=5\\), so circle \\(G\\) has radius 7 and \\(p=7^2=49\\).", "accepted": [49]}, {"src": "ID 1b2b20b9 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Circles", "type": "spr", "stem": "Circle A is defined by the equation \\(x^2+(y-6)^2=7\\). Circle B has the same radius as circle A but is translated 96 units to the right. If the equation of circle B is \\((x-h)^2+(y-k)^2=a\\), where \\(h\\), \\(k\\), and \\(a\\) are constants, what is the value of \\(4a\\)?", "fig": null, "rat": "A translation does not change the radius, so \\(a=r^2=7\\). Therefore \\(4a=28\\).", "accepted": [28]}, {"src": "ID 44b2b894 &middot; Geometry &amp; Trigonometry &middot; Hard", "skill": "Right triangles and trigonometry", "type": "spr", "stem": "A rectangle is inscribed in a circle, such that each vertex of the rectangle lies on the circumference of the circle. The diagonal of the rectangle is twice the length of the shortest side of the rectangle. The area of the rectangle is \\(1{,}089\\sqrt3\\) square units. What is the length, in units, of the diameter of the circle?", "fig": null, "rat": "Let the short side be \\(s\\); the diagonal is \\(2s\\), so the long side is \\(\\sqrt{(2s)^2-s^2}=s\\sqrt3\\). Area: \\(s\\cdot s\\sqrt3=s^2\\sqrt3=1{,}089\\sqrt3\\), so \\(s^2=1{,}089\\) and \\(s=33\\). The diameter equals the diagonal: \\(2(33)=66\\).", "accepted": [66]}, {"src": "ID 9b5b23fc &middot; Problem-Solving &amp; Data Analysis &middot; Hard", "skill": "Two-variable data: models and scatterplots", "type": "mc", "stem": "For \\(x>0\\), the function \\(f\\) is defined as follows: \\(f(x)\\) equals 201% of \\(x\\). Which of the following could describe this function?", "fig": null, "rat": "201% of \\(x\\) is \\(f(x)=2.01x\\) — a constant rate of change, and increasing. So it is an increasing linear function.", "opts": ["Decreasing exponential", "Decreasing linear", "Increasing exponential", "Increasing linear"], "ans": "D"}, {"src": "ID ab7740a8 &middot; Problem-Solving &amp; Data Analysis &middot; Medium", "skill": "Two-variable data: models and scatterplots", "type": "mc", "stem": "In which of the following tables is the relationship between the values of \\(x\\) and their corresponding \\(y\\)-values nonlinear?", "fig": null, "rat": "A relationship is nonlinear when the rate of change is not constant. For choice D, the successive rates are \\(\\tfrac{12-6}{1}=6\\), \\(\\tfrac{24-12}{1}=12\\), and \\(\\tfrac{48-24}{1}=24\\) — not constant, so it is nonlinear. Choices A, B, and C have constant rates of 3, 4, and 5.", "opts": ["\\(x\\): 1, 2, 3, 4 &nbsp;/&nbsp; \\(y\\): 8, 11, 14, 17", "\\(x\\): 1, 2, 3, 4 &nbsp;/&nbsp; \\(y\\): 4, 8, 12, 16", "\\(x\\): 1, 2, 3, 4 &nbsp;/&nbsp; \\(y\\): 8, 13, 18, 23", "\\(x\\): 1, 2, 3, 4 &nbsp;/&nbsp; \\(y\\): 6, 12, 24, 48"], "ans": "D"}, {"src": "ID 842cec4d &middot; Algebra &middot; Easy", "skill": "Linear inequalities in one or two variables", "type": "mc", "stem": "During a portion of a flight, a small airplane’s cruising speed varied between 150 miles per hour and 170 miles per hour. Which inequality best represents this situation, where \\(s\\) is the cruising speed, in miles per hour, during this portion of the flight?", "fig": null, "rat": "The speed was at least 150 and at most 170, so \\(150\\le s\\le 170\\).", "opts": ["\\(s\\le 20\\)", "\\(s\\le 150\\)", "\\(s\\le 170\\)", "\\(150\\le s\\le 170\\)"], "ans": "D"}, {"src": "ID 64c85440 &middot; Algebra &middot; Medium", "skill": "Linear inequalities in one or two variables", "type": "mc", "stem": "In North America, the standard width of a parking space is at least 7.5 feet and no more than 9.0 feet. A restaurant owner recently resurfaced the restaurant’s parking lot and wants to determine the number of parking spaces, \\(n\\), in the parking lot that could be placed perpendicular to a curb that is 135 feet long, based on the standard width of a parking space. Which of the following describes all the possible values of \\(n\\)?", "fig": null, "rat": "Narrowest spaces give the most spots: \\(135/7.5=18\\). Widest spaces give the fewest: \\(135/9=15\\). So \\(15\\le n\\le 18\\).", "opts": ["\\(18\\le n\\le 135\\)", "\\(7.5\\le n\\le 9\\)", "\\(15\\le n\\le 135\\)", "\\(15\\le n\\le 18\\)"], "ans": "D"}, {"src": "ID 541bef2f &middot; Algebra &middot; Hard", "skill": "Linear inequalities in one or two variables", "type": "mc", "stem": "Which point \\((x,y)\\) is a solution to the given system of inequalities in the xy-plane?<br>\\(y\\le x+7\\)<br>\\(y\\ge -2x-1\\)", "fig": null, "rat": "Test \\((14,0)\\): first, \\(0\\le 14+7=21\\) ✓; second, \\(0\\ge -2(14)-1=-29\\) ✓. Both hold, so it is a solution.", "opts": ["\\((-14,0)\\)", "\\((0,-14)\\)", "\\((0,14)\\)", "\\((14,0)\\)"], "ans": "D"}, {"src": "ID d914abec &middot; Algebra &middot; Medium", "skill": "Linear inequalities in one or two variables", "type": "mc", "stem": "To complete a landscaping project, Adam charges a fee of $20.00 for his equipment and $9.50 per hour spent working on the project. To complete this same landscaping project, Caroline charges a fee of $17.00 for her equipment and $10.00 per hour spent working on the project. If \\(x\\) represents the number of hours spent working on the landscaping project, what are all the values of \\(x\\) for which Caroline’s total charge is greater than Adam’s total charge?", "fig": null, "rat": "Caroline charges more when \\(17+10x>20+9.5x\\). Subtracting \\(9.5x\\) gives \\(17+0.5x>20\\); subtracting 17 gives \\(0.5x>3\\), so \\(x>6\\).", "opts": ["\\(5\\le x\\le 6\\)", "\\(6\\le x\\le 7\\)", "\\(x<5\\)", "\\(x>6\\)"], "ans": "D"}, {"src": "ID df32b09c &middot; Algebra &middot; Easy", "skill": "Linear inequalities in one or two variables", "type": "mc", "stem": "Tom scored 85, 78, and 98 on his first three exams in history class. Solving which inequality gives the score, \\(G\\), on Tom’s fourth exam that will result in a mean score on all four exams of at least 90?", "fig": null, "rat": "The mean of the four scores is \\(\\dfrac{G+85+78+98}{4}\\), and \"at least 90\" means it is \\(\\ge 90\\).", "opts": ["\\(90-(85+78+98)\\le 4G\\)", "\\(4G+85+78+98\\ge 360\\)", "\\(\\dfrac{G+85+78+98}{4}\\ge 90\\)", "\\(\\dfrac{85+78+98}{4}\\ge 90-4G\\)"], "ans": "C"}, {"src": "ID b78cd5df &middot; Algebra &middot; Medium", "skill": "Linear inequalities in one or two variables", "type": "spr", "stem": "An event planner is planning a party. It costs the event planner a onetime fee of $35 to rent the venue and $10.25 per attendee. The event planner has a budget of $300. What is the greatest number of attendees possible without exceeding the budget?", "fig": null, "rat": "With \\(x\\) attendees: \\(35+10.25x\\le 300\\), so \\(10.25x\\le 265\\) and \\(x\\le 25.85\\). Attendees must be whole, so the greatest number is 25.", "accepted": [25]}, {"src": "ID 89541f9b &middot; Algebra &middot; Easy", "skill": "Linear inequalities in one or two variables", "type": "mc", "stem": "Which of the following ordered pairs \\((x,y)\\) satisfies the inequality \\(5x-3y<4\\)?<br>I. \\((1,1)\\)&ensp;II. \\((2,5)\\)&ensp;III. \\((3,2)\\)", "fig": null, "rat": "I: \\(5-3=2<4\\) ✓. II: \\(10-15=-5<4\\) ✓. III: \\(15-6=9\\), which is not less than 4. So I and II only.", "opts": ["I only", "II only", "I and II only", "I and III only"], "ans": "C"}, {"src": "ID 34aca984 &middot; Algebra &middot; Medium", "skill": "Linear inequalities in one or two variables", "type": "mc", "stem": "The length of a rectangle is 50 inches and the width is \\(x\\) inches. The perimeter is at most 210 inches. Which inequality represents this situation?", "fig": null, "rat": "The perimeter is \\(2(50)+2x=100+2x\\), and \"at most 210\" gives \\(2x+100\\le 210\\).", "opts": ["\\(2x+100\\le 210\\)", "\\(2x+100\\ge 210\\)", "\\(2x+50\\le 210\\)", "\\(2x+50\\ge 210\\)"], "ans": "A"}, {"src": "ID 03503d49 &middot; Algebra &middot; Hard", "skill": "Linear inequalities in one or two variables", "type": "mc", "stem": "A business owner plans to purchase the same model of chair for each of the 81 employees. The total budget to spend on these chairs is $14,000, which includes a 7% sales tax. Which of the following is closest to the maximum possible price per chair, before sales tax, the business owner could pay based on this budget?", "fig": null, "rat": "With price \\(p\\) per chair before tax, the total with tax is \\(81(1.07)p\\le 14{,}000\\), so \\(p\\le \\dfrac{14{,}000}{86.67}\\approx161.53\\).", "opts": ["$148.15", "$161.53", "$172.84", "$184.94"], "ans": "B"}, {"src": "ID 2869fe95 &middot; Algebra &middot; Easy", "skill": "Linear inequalities in one or two variables", "type": "mc", "stem": "For a 3-week period in a town in Illinois, the lowest recorded temperature was 31 degrees Fahrenheit (&deg;F) and the highest recorded temperature was 67&deg;F. Which inequality is true for any recorded temperature \\(t\\), in &deg;F, in this town for this 3-week period?", "fig": null, "rat": "Every recorded temperature is between the lowest and highest values inclusive: \\(31\\le t\\le 67\\).", "opts": ["\\(t\\ge 98\\)", "\\(t\\ge 67\\)", "\\(31\\le t\\le 67\\)", "\\(t\\le 31\\)"], "ans": "C"}, {"src": "ID e9ef0e6b &middot; Algebra &middot; Medium", "skill": "Linear inequalities in one or two variables", "type": "mc", "stem": "A model estimates that whales from the genus <i>Eschrichtius</i> travel 72 to 77 miles in the ocean each day during their migration. Based on this model, which inequality represents the estimated total number of miles, \\(x\\), a whale from the genus <i>Eschrichtius</i> could travel in 16 days of its migration?", "fig": null, "rat": "Over 16 days the total is between \\(72(16)\\) and \\(77(16)\\) miles: \\((72)(16)\\le x\\le(77)(16)\\).", "opts": ["\\(72+16\\le x\\le 77+16\\)", "\\((72)(16)\\le x\\le (77)(16)\\)", "\\(72\\le 16+x\\le 77\\)", "\\(72\\le 16x\\le 77\\)"], "ans": "B"}, {"src": "ID 208626df &middot; Algebra &middot; Easy", "skill": "Linear inequalities in one or two variables", "type": "mc", "stem": "A rectangle has length \\(\\ell\\) and width \\(w\\). The inequality \\(2\\ell+2w\\le 27\\) gives the possible values of \\(\\ell\\) and \\(w\\) for which the perimeter of this rectangle is less than or equal to 27. Which statement is the best interpretation of \\((\\ell,w)=(8,3)\\) in this context?", "fig": null, "rat": "The pair gives length 8 and width 3. Checking: \\(2(8)+2(3)=22\\le 27\\), so a rectangle with length 8 and width 3 has perimeter at most 27.", "opts": ["If the rectangle has length 3 and width 8, its perimeter is less than or equal to 27.", "If the rectangle has length 8 and width 3, its perimeter is less than or equal to 27.", "If the rectangle has length 3 and width 8, its perimeter is greater than or equal to 27.", "If the rectangle has length 8 and width 3, its perimeter is greater than or equal to 27."], "ans": "B"}, {"src": "ID 075b29b0 &middot; Advanced Math &middot; Easy", "skill": "Equivalent expressions", "type": "mc", "stem": "Which expression is equivalent to \\((9x^3+5x+7)+(6x^3+5x^2-5)\\)?", "fig": null, "rat": "Combine like terms: \\(9x^3+6x^3=15x^3\\), the \\(5x^2\\) stands alone, \\(5x\\) stands alone, and \\(7-5=2\\). Result: \\(15x^3+5x^2+5x+2\\).", "opts": ["\\(15x^6+5x^2-5x-35\\)", "\\(15x^3+10x^2+2\\)", "\\(15x^6+5x^2+5x+2\\)", "\\(15x^3+5x^2+5x+2\\)"], "ans": "D"}, {"src": "ID 38c90632 &middot; Advanced Math &middot; Hard", "skill": "Equivalent expressions", "type": "spr", "stem": "The expression \\(\\dfrac{29x+102}{x(x+51)}\\) is equivalent to \\(\\dfrac{p}{x}+\\dfrac{w}{x+51}\\), where \\(p\\) and \\(w\\) are constants. What is the value of \\(w\\)?", "fig": null, "rat": "Combining the right side over \\(x(x+51)\\) gives \\(\\dfrac{p(x+51)+wx}{x(x+51)}=\\dfrac{(p+w)x+51p}{x(x+51)}\\). Matching numerators: \\(51p=102\\) so \\(p=2\\), and \\(p+w=29\\) so \\(w=27\\).", "accepted": [27]}, {"src": "ID 70482e20 &middot; Advanced Math &middot; Easy", "skill": "Equivalent expressions", "type": "mc", "stem": "Which expression is equivalent to \\(11x^3-5x^3\\)?", "fig": null, "rat": "Both terms are multiples of \\(x^3\\), so they combine: \\(11x^3-5x^3=6x^3\\).", "opts": ["\\(16x^3\\)", "\\(6x^3\\)", "\\(6x^6\\)", "\\(16x^6\\)"], "ans": "B"}, {"src": "ID 772de699 &middot; Advanced Math &middot; Easy", "skill": "Equivalent expressions", "type": "mc", "stem": "Which expression is equivalent to \\(23x^3+2x^2+9x\\)?", "fig": null, "rat": "Each term has a factor of \\(x\\), so factoring it out gives \\(x(23x^2+2x+9)\\).", "opts": ["\\(23x(x^2+2x+9)\\)", "\\(9x(23x^3+2x^2+1)\\)", "\\(x(23x^2+2x+9)\\)", "\\(34(x^3+x^2+x)\\)"], "ans": "C"}, {"src": "ID a0b4103e &middot; Advanced Math &middot; Hard", "skill": "Equivalent expressions", "type": "mc", "stem": "The expression \\(\\tfrac13x^2-2\\) can be rewritten as \\(\\tfrac13(x-k)(x+k)\\), where \\(k\\) is a positive constant. What is the value of \\(k\\)?", "fig": null, "rat": "Factoring out \\(\\tfrac13\\) gives \\(\\tfrac13(x^2-6)\\). As a difference of squares, \\(x^2-6=(x-\\sqrt6)(x+\\sqrt6)\\), so \\(k=\\sqrt6\\).", "opts": ["2", "6", "\\(\\sqrt2\\)", "\\(\\sqrt6\\)"], "ans": "D"}, {"src": "ID 26eb61c1 &middot; Advanced Math &middot; Medium", "skill": "Equivalent expressions", "type": "mc", "stem": "Which expression is equivalent to \\(6x^8y^2+12x^2y^2\\)?", "fig": null, "rat": "The greatest common factor is \\(6x^2y^2\\): \\(6x^8y^2+12x^2y^2=6x^2y^2(x^6+2)\\).", "opts": ["\\(6x^2y^2(2x^6)\\)", "\\(6x^2y^2(x^4)\\)", "\\(6x^2y^2(x^6+2)\\)", "\\(6x^2y^2(x^4+2)\\)"], "ans": "C"}, {"src": "ID beb86a0c &middot; Advanced Math &middot; Easy", "skill": "Equivalent expressions", "type": "mc", "stem": "Which expression is equivalent to \\(9x^2+5x\\)?", "fig": null, "rat": "Both terms share a factor of \\(x\\): \\(9x^2+5x=x(9x+5)\\).", "opts": ["\\(x(9x+5)\\)", "\\(5x(9x+1)\\)", "\\(9x(x+5)\\)", "\\(x^2(9x+5)\\)"], "ans": "A"}, {"src": "ID 12e7faf8 &middot; Advanced Math &middot; Hard", "skill": "Equivalent expressions", "type": "mc", "stem": "The equation \\(\\dfrac{x^2+6x-7}{x+7}=ax+d\\) is true for all \\(x\\ne -7\\), where \\(a\\) and \\(d\\) are integers. What is the value of \\(a+d\\)?", "fig": null, "rat": "Factor the numerator: \\(x^2+6x-7=(x+7)(x-1)\\). Dividing by \\(x+7\\) leaves \\(x-1\\), so \\(a=1\\) and \\(d=-1\\), giving \\(a+d=0\\).", "opts": ["\\(-6\\)", "\\(-1\\)", "0", "1"], "ans": "C"}, {"src": "ID df0ef054 &middot; Advanced Math &middot; Easy", "skill": "Equivalent expressions", "type": "mc", "stem": "Which of the following is equivalent to the expression \\((2x^3+3x)(x^3-2x)\\)?", "fig": null, "rat": "Distribute: \\(2x^3\\cdot x^3=2x^6\\), \\(2x^3(-2x)=-4x^4\\), \\(3x\\cdot x^3=3x^4\\), \\(3x(-2x)=-6x^2\\). Combining \\(-4x^4+3x^4=-x^4\\) gives \\(2x^6-x^4-6x^2\\).", "opts": ["\\(x^3+5x\\)", "\\(3x^3+x\\)", "\\(2x^6-x^4-6x^2\\)", "\\(3x^6-x^4-6x^2\\)"], "ans": "C"}, {"src": "ID e117d3b8 &middot; Advanced Math &middot; Hard", "skill": "Equivalent expressions", "type": "mc", "stem": "If \\(a\\) and \\(c\\) are positive numbers, which of the following is equivalent to \\(\\sqrt{(a+c)^3}\\cdot\\sqrt{a+c}\\)?", "fig": null, "rat": "Multiplying the radicals: \\(\\sqrt{(a+c)^3(a+c)}=\\sqrt{(a+c)^4}=(a+c)^2=a^2+2ac+c^2\\).", "opts": ["\\(a+c\\)", "\\(a^2+c^2\\)", "\\(a^2+2ac+c^2\\)", "\\(a^2c^2\\)"], "ans": "C"}, {"src": "ID df747160 &middot; Advanced Math &middot; Easy", "skill": "Equivalent expressions", "type": "mc", "stem": "Which expression is equivalent to \\(17(x^2-100y^2)\\)?", "fig": null, "rat": "\\(x^2-100y^2\\) is a difference of squares: \\((x-10y)(x+10y)\\). So the expression is \\(17(x-10y)(x+10y)\\).", "opts": ["\\(17(x-2y)(x-50y)\\)", "\\(17(x-2y)(x+50y)\\)", "\\(17(x-10y)(x-10y)\\)", "\\(17(x-10y)(x+10y)\\)"], "ans": "D"}, {"src": "ID 4eaf0a3a &middot; Advanced Math &middot; Medium", "skill": "Equivalent expressions", "type": "mc", "stem": "Which expression is equivalent to \\(\\sqrt[3]{x^9y^9}\\), where \\(x\\) and \\(y\\) are positive?", "fig": null, "rat": "\\(x^9y^9=(xy)^9\\), and the cube root gives \\(\\left((xy)^9\\right)^{1/3}=(xy)^3\\).", "opts": ["\\((xy)^{\\frac{9}{2}}\\)", "\\((xy)^3\\)", "\\((xy)^{16}\\)", "\\((xy)^{63}\\)"], "ans": "B"}, {"src": "ID 4e18fc5d &middot; Advanced Math &middot; Medium", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "type": "mc", "stem": "The equation \\(v=-\\dfrac{w}{150x}\\) relates the distinct positive numbers \\(v\\), \\(w\\), and \\(x\\). Which equation correctly expresses \\(w\\) in terms of \\(v\\) and \\(x\\)?", "fig": null, "rat": "Multiply both sides by \\(-150x\\): \\(-150xv=w\\), so \\(w=-150vx\\).", "opts": ["\\(w=-150vx\\)", "\\(w=-\\dfrac{150v}{x}\\)", "\\(w=-\\dfrac{x}{150v}\\)", "\\(w=v+150x\\)"], "ans": "A"}, {"src": "ID 4661e2a9 &middot; Advanced Math &middot; Hard", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "type": "mc", "stem": "Which ordered pair is a solution to the system of equations \\(x-y=1\\) and \\(x+y=x^2-3\\)?", "fig": null, "rat": "From the first equation \\(x=y+1\\). Substituting: \\((y+1)+y=(y+1)^2-3\\) gives \\(2y+1=y^2+2y-2\\), so \\(y^2=3\\) and \\(y=\\pm\\sqrt3\\). With \\(y=\\sqrt3\\), \\(x=1+\\sqrt3\\), giving \\((1+\\sqrt3,\\sqrt3)\\).", "opts": ["\\((1+\\sqrt3,\\sqrt3)\\)", "\\((\\sqrt3,-\\sqrt3)\\)", "\\((1+\\sqrt5,\\sqrt5)\\)", "\\((\\sqrt5,-1+\\sqrt5)\\)"], "ans": "A"}, {"src": "ID ff2c1431 &middot; Advanced Math &middot; Medium", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "type": "mc", "stem": "The equation \\(7m=5(n+p)\\) relates the positive numbers \\(m\\), \\(n\\), and \\(p\\). Which equation correctly gives \\(n\\) in terms of \\(m\\) and \\(p\\)?", "fig": null, "rat": "Divide both sides by 5: \\(\\tfrac{7m}{5}=n+p\\). Subtracting \\(p\\) gives \\(n=\\tfrac{7m}{5}-p\\).", "opts": ["\\(n=\\dfrac{5p}{7m}\\)", "\\(n=\\dfrac{7m}{5}-p\\)", "\\(n=5(7m)+p\\)", "\\(n=7m-5-p\\)"], "ans": "B"}, {"src": "ID b80d10d7 &middot; Advanced Math &middot; Medium", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "type": "mc", "stem": "What is the solution to the equation \\(\\dfrac{2(x+1)}{x+5}=1-\\dfrac{1}{x+5}\\)?", "fig": null, "rat": "Write the right side over \\(x+5\\): \\(\\dfrac{(x+5)-1}{x+5}=\\dfrac{x+4}{x+5}\\). Equal denominators give \\(2(x+1)=x+4\\), so \\(2x+2=x+4\\) and \\(x=2\\).", "opts": ["0", "2", "3", "5"], "ans": "B"}, {"src": "ID 95ed0b69 &middot; Advanced Math &middot; Medium", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "type": "mc", "stem": "The equation \\(p=\\dfrac{k}{4j+9}\\) relates the distinct positive numbers \\(p\\), \\(k\\), and \\(j\\). Which equation correctly expresses \\(4j+9\\) in terms of \\(p\\) and \\(k\\)?", "fig": null, "rat": "Multiply both sides by \\(4j+9\\): \\(p(4j+9)=k\\). Dividing by \\(p\\) gives \\(4j+9=\\dfrac{k}{p}\\).", "opts": ["\\(4j+9=\\dfrac{k}{p}\\)", "\\(4j+9=kp\\)", "\\(4j+9=k-p\\)", "\\(4j+9=\\dfrac{p}{k}\\)"], "ans": "A"}, {"src": "ID 03ff48d2 &middot; Advanced Math &middot; Hard", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "type": "spr", "stem": "In the equation \\(x(kx-56)=-16\\), \\(k\\) is an integer constant. If the equation has no real solution, what is the least possible value of \\(k\\)?", "fig": null, "rat": "Expanding gives \\(kx^2-56x+16=0\\). No real solution means a negative discriminant: \\((-56)^2-4(k)(16)<0\\), so \\(3{,}136<64k\\) and \\(k>49\\). The least integer is 50.", "accepted": [50]}, {"src": "ID ebb717ab &middot; Advanced Math &middot; Hard", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "type": "spr", "stem": "In the equation \\(x^2-34x+c=0\\), \\(c\\) is a constant. The equation has no real solutions if \\(c>n\\). What is the least possible value of \\(n\\)?", "fig": null, "rat": "No real solutions means \\((-34)^2-4c<0\\), so \\(1{,}156<4c\\) and \\(c>289\\). Therefore the least possible value of \\(n\\) is 289.", "accepted": [289]}, {"src": "ID 717a1964 &middot; Advanced Math &middot; Medium", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "type": "spr", "stem": "What is one of the solutions to the equation \\(z^2+10z-24=0\\)?", "fig": null, "rat": "Factor: two numbers multiplying to \\(-24\\) and adding to 10 are 12 and \\(-2\\), so \\((z+12)(z-2)=0\\) and \\(z=-12\\) or \\(z=2\\).", "accepted": [2, -12]}, {"src": "ID 895628b5 &middot; Advanced Math &middot; Medium", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "type": "mc", "stem": "Which ordered pair \\((x,y)\\) is the solution to the system of equations \\(y=(x-2)(x+4)\\) and \\(y=6x-12\\)?", "fig": null, "rat": "Setting them equal: \\((x-2)(x+4)=6(x-2)\\). Since \\(x=2\\) makes both sides zero, \\(x=2\\) works, giving \\(y=6(2)-12=0\\). So the solution is \\((2,0)\\).", "opts": ["\\((0,2)\\)", "\\((-4,2)\\)", "\\((2,0)\\)", "\\((2,-4)\\)"], "ans": "C"}, {"src": "ID a1262cdb &middot; Advanced Math &middot; Medium", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "type": "mc", "stem": "The equation \\(12t+b=c\\) relates the variables \\(t\\), \\(b\\), and \\(c\\). Which of the following correctly expresses the value of \\(c-b\\) in terms of \\(t\\)?", "fig": null, "rat": "Subtracting \\(b\\) from both sides gives \\(12t=c-b\\).", "opts": ["\\(\\dfrac{t}{12}\\)", "\\(t\\)", "\\(t+\\dfrac{1}{12}\\)", "\\(12t\\)"], "ans": "D"}, {"src": "ID 2f958af9 &middot; Advanced Math &middot; Medium", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "type": "mc", "stem": "The formula \\(v^2=\\dfrac{LT}{m}\\) expresses the square of the speed \\(v\\) of a wave moving along a string in terms of tension \\(T\\), mass \\(m\\), and length \\(L\\) of the string. What is \\(T\\) in terms of \\(m\\), \\(v\\), and \\(L\\)?", "fig": null, "rat": "Multiply both sides by \\(m\\): \\(mv^2=LT\\). Dividing by \\(L\\) gives \\(T=\\dfrac{mv^2}{L}\\).", "opts": ["\\(T=\\dfrac{mv^2}{L}\\)", "\\(T=\\dfrac{m}{v^2L}\\)", "\\(T=\\dfrac{mL}{v^2}\\)", "\\(T=\\dfrac{L}{mv^2}\\)"], "ans": "A"}, {"src": "ID 09e5e4d3 &middot; Advanced Math &middot; Medium", "skill": "Nonlinear equations in one variable and systems of equations in two variables", "type": "mc", "stem": "If \\(\\dfrac{42}{x}=7x\\), what is the value of \\(7x^2\\)?", "fig": null, "rat": "Multiplying both sides by \\(x\\) gives \\(42=7x^2\\). So \\(7x^2=42\\).", "opts": ["6", "7", "42", "294"], "ans": "C"}, {"src": "ID 797a81fb &middot; Algebra &middot; Hard", "skill": "Systems of two linear equations in two variables", "type": "mc", "stem": "How many solutions does the system \\(-12x+14y=36\\) and \\(-6x+7y=-18\\) have?", "fig": null, "rat": "Dividing the first equation by 2 gives \\(-6x+7y=18\\), which contradicts \\(-6x+7y=-18\\). The lines are parallel and distinct, so there are zero solutions.", "opts": ["Exactly one", "Exactly two", "Infinitely many", "Zero"], "ans": "D"}, {"src": "ID f75bd744 &middot; Algebra &middot; Hard", "skill": "Systems of two linear equations in two variables", "type": "spr", "stem": "In the system of equations \\(4x-6y=10y+2\\) and \\(ty=\\tfrac12+2x\\), \\(t\\) is a constant. If the system has no solution, what is the value of \\(t\\)?", "fig": null, "rat": "Rewrite the first as \\(4x-16y=2\\), or \\(2x-8y=1\\). Rewrite the second as \\(2x-ty=-\\tfrac12\\). For no solution the coefficients must be proportional while the constants are not, which requires \\(t=8\\).", "accepted": [8]}, {"src": "ID 1362ccde &middot; Algebra &middot; Hard", "skill": "Systems of two linear equations in two variables", "type": "spr", "stem": "The solution to the system \\(y=4x+1\\) and \\(4y=15x-8\\) is \\((x,y)\\). What is the value of \\(x-y\\)?", "fig": null, "rat": "Substituting: \\(4(4x+1)=15x-8\\) gives \\(16x+4=15x-8\\), so \\(x=-12\\). Then \\(y=4(-12)+1=-47\\), and \\(x-y=-12-(-47)=35\\).", "accepted": [35]}, {"src": "ID f88970cc &middot; Algebra &middot; Easy", "skill": "Systems of two linear equations in two variables", "type": "mc", "stem": "Which of the following points \\((x,y)\\) is the solution to the system \\(x=5\\) and \\(y=x-8\\) in the xy-plane?", "fig": null, "rat": "Substituting \\(x=5\\) into the second equation gives \\(y=5-8=-3\\), so the solution is \\((5,-3)\\).", "opts": ["\\((0,0)\\)", "\\((5,-3)\\)", "\\((5,-8)\\)", "\\((5,8)\\)"], "ans": "B"}, {"src": "ID e470e19d &middot; Algebra &middot; Medium", "skill": "Linear functions", "type": "mc", "stem": "The function \\(f\\) is defined by \\(f(x)=7x-84\\). What is the x-intercept of the graph of \\(y=f(x)\\) in the xy-plane?", "fig": null, "rat": "Set \\(f(x)=0\\): \\(7x-84=0\\) gives \\(x=12\\), so the x-intercept is \\((12,0)\\).", "opts": ["\\((-12,0)\\)", "\\((-7,0)\\)", "\\((7,0)\\)", "\\((12,0)\\)"], "ans": "D"}, {"src": "ID d1f50dbe &middot; Algebra &middot; Hard", "skill": "Linear functions", "type": "mc", "stem": "One gallon of stain will cover 170 square feet of a surface. A yard has a total fence area of \\(w\\) square feet. Which equation represents the total amount of stain \\(S\\), in gallons, needed to stain the fence in this yard twice?", "fig": null, "rat": "Staining twice covers \\(2w\\) square feet, and each gallon covers 170: \\(S=\\dfrac{2w}{170}=\\dfrac{w}{85}\\).", "opts": ["\\(S=\\dfrac{w}{170}\\)", "\\(S=170w\\)", "\\(S=340w\\)", "\\(S=\\dfrac{w}{85}\\)"], "ans": "D"}, {"src": "ID 2e379126 &middot; Algebra &middot; Easy", "skill": "Linear functions", "type": "mc", "stem": "The function \\(g\\) is defined by \\(g(x)=4x-6\\). What is the value of \\(g(-7)\\)?", "fig": null, "rat": "\\(g(-7)=4(-7)-6=-28-6=-34\\).", "opts": ["\\(-34\\)", "\\(-22\\)", "\\(-\\tfrac{13}{4}\\)", "\\(-\\tfrac{1}{4}\\)"], "ans": "A"}, {"src": "ID c4d49134 &middot; Algebra &middot; Easy", "skill": "Linear functions", "type": "mc", "stem": "The equation \\(s=40+3t\\) gives the speed \\(s\\), in miles per hour, of a certain car \\(t\\) seconds after it began to accelerate. What is the speed, in miles per hour, of the car 5 seconds after it began to accelerate?", "fig": null, "rat": "Substituting \\(t=5\\): \\(s=40+3(5)=55\\) miles per hour.", "opts": ["40", "43", "45", "55"], "ans": "D"}, {"src": "ID 3d1070c9 &middot; Algebra &middot; Easy", "skill": "Linear functions", "type": "mc", "stem": "The function \\(f\\) is defined by \\(f(x)=25x+30\\). What is the value of \\(f(x)\\) when \\(x=2\\)?", "fig": null, "rat": "\\(f(2)=25(2)+30=50+30=80\\).", "opts": ["50", "57", "80", "110"], "ans": "C"}, {"src": "ID af142f8d &middot; Problem-Solving &amp; Data Analysis &middot; Hard", "skill": "Two-variable data: models and scatterplots", "type": "mc", "stem": "Two investments were made as shown in the table. The interest in Account A is compounded once per year. Which of the following is true about the investments?", "fig": null, "rat": "Account A earns \\(500(0.06)=\\$30\\) in the first year, already more than Account B’s flat \\$25. Because A compounds, its yearly earnings only grow from there, so A always earns more per year than B.", "figHTML": "<table class=\"data-table\"><tr><th></th><th>Amount invested</th><th>Balance increase</th></tr><tr><th>Account A</th><td>$500</td><td>6% annual interest</td></tr><tr><th>Account B</th><td>$1,000</td><td>$25 per year</td></tr></table>", "opts": ["Account A always earns more money per year than Account B.", "Account A always earns less money per year than Account B.", "Account A earns more money per year than Account B at first but eventually earns less money per year.", "Account A earns less money per year than Account B at first but eventually earns more money per year."], "ans": "A"}, {"src": "ID 9a144a01 &middot; Problem-Solving &amp; Data Analysis &middot; Medium", "skill": "Two-variable data: models and scatterplots", "type": "mc", "stem": "Which of the following is true about the values of \\(2^x\\) and \\(2x+2\\) for \\(x>0\\)?", "fig": null, "rat": "At \\(x=0\\): \\(1<2\\), so \\(2^x\\) is smaller. They are equal at \\(x=3\\): \\(2^3=8=2(3)+2\\). Beyond that the exponential grows faster, so for \\(x>3\\), \\(2^x>2x+2\\). Hence there is a constant \\(c\\) (namely 3) where the comparison flips.", "opts": ["For all \\(x>0\\), it is true that \\(2^x<2x+2\\).", "For all \\(x>0\\), it is true that \\(2^x>2x+2\\).", "There is a constant \\(c\\) such that if \\(0<x<c\\), then \\(2^x<2x+2\\), but if \\(x>c\\), then \\(2^x>2x+2\\).", "There is a constant \\(c\\) such that if \\(0<x<c\\), then \\(2^x>2x+2\\), but if \\(x>c\\), then \\(2^x<2x+2\\)."], "ans": "C"}, {"src": "ID a03b7e02 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Two-variable data: models and scatterplots", "type": "mc", "stem": "The table shows selected values from function \\(f\\). Which of the following is the best description of function \\(f\\)?", "fig": null, "rat": "As \\(x\\) increases by 1, \\(f(x)\\) increases by exactly 1 each time — a constant rate of change, so \\(f\\) is an increasing linear function.", "figHTML": "<table class=\"data-table\"><tr><th>\\(x\\)</th><th>\\(f(x)\\)</th></tr><tr><th>−1</th><td>16</td></tr><tr><th>0</th><td>17</td></tr><tr><th>1</th><td>18</td></tr><tr><th>2</th><td>19</td></tr></table>", "opts": ["Decreasing linear", "Increasing linear", "Decreasing exponential", "Increasing exponential"], "ans": "B"}, {"src": "ID 6fca0144 &middot; Problem-Solving &amp; Data Analysis &middot; Hard", "skill": "Evaluating statistical claims: observational studies and experiments", "type": "mc", "stem": "For a baobab tree habitat in South Africa, a scientist randomly selected 50 baobab trees that were 17 years old and randomly assigned them to two groups. Each group was subjected to a different watering pattern for 2 consecutive years to observe whether the watering pattern affects the trees’ growth rate. Based on the design of the study, what is the largest group to which these results can be applied?", "fig": null, "rat": "Results generalize to the population the random sample was drawn from: the 17-year-old baobab trees in this particular habitat.", "opts": ["All the 50 baobab trees that were selected in this habitat", "All the baobab trees that were 19 years old in this habitat", "All the baobab trees that were 17 years old in South Africa", "All the baobab trees that were 17 years old in this habitat"], "ans": "D"}, {"src": "ID 82dfb646 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Evaluating statistical claims: observational studies and experiments", "type": "mc", "stem": "A market researcher selected 200 people at random from a group of people who indicated that they liked a certain book. The 200 people were shown a movie based on the book and then asked whether they liked or disliked the movie. Of those surveyed, 95% said they disliked the movie. Which of the following inferences can appropriately be drawn from this survey result?", "fig": null, "rat": "The sample came only from people who liked the book, so conclusions extend only to that group: most people who like this book will dislike the movie.", "opts": ["At least 95% of people who go see movies will dislike this movie.", "At least 95% of people who read books will dislike this movie.", "Most people who dislike this book will like this movie.", "Most people who like this book will dislike this movie."], "ans": "D"}, {"src": "ID 7d68096f &middot; Problem-Solving &amp; Data Analysis &middot; Hard", "skill": "Evaluating statistical claims: observational studies and experiments", "type": "mc", "stem": "A trivia tournament organizer wanted to study the relationship between the number of points a team scores in a trivia round and the number of hours a team practices each week. For the study, the organizer selected 55 teams at random from all trivia teams in a certain tournament. The table displays the information for the 40 teams in the sample that practiced for at least 3 hours per week. Which of the following is the largest population to which the results of the study can be generalized?", "fig": null, "rat": "The random selection was made from all trivia teams in the tournament, so that is the largest population the results generalize to.", "figHTML": "<table class=\"data-table\"><caption>Number of points per round</caption><tr><th>Hours practiced</th><th>6 to 13 points</th><th>14 or more points</th><th>Total</th></tr><tr><th>3 to 5 hours</th><td>6</td><td>4</td><td>10</td></tr><tr><th>More than 5 hours</th><td>4</td><td>26</td><td>30</td></tr><tr><th>Total</th><td>10</td><td>30</td><td>40</td></tr></table>", "opts": ["All trivia teams in the tournament that scored 14 or more points in the round", "The 55 trivia teams in the sample", "The 40 trivia teams in the sample that practiced for at least 3 hours per week", "All trivia teams in the tournament"], "ans": "D"}, {"src": "ID fc46af57 &middot; Problem-Solving &amp; Data Analysis &middot; Medium", "skill": "Inference from sample statistics and margin of error", "type": "mc", "stem": "A bag containing 10,000 beads of assorted colors is purchased from a craft store. To estimate the percent of red beads in the bag, a sample of beads is selected at random. The percent of red beads in the bag was estimated to be 15%, with an associated margin of error of 2%. If \\(r\\) is the actual number of red beads in the bag, which of the following is most plausible?", "fig": null, "rat": "The estimate is \\(10{,}000(0.15)=1{,}500\\) beads, and the margin of error is \\(10{,}000(0.02)=200\\) beads. So plausible values run from \\(1{,}300\\) to \\(1{,}700\\).", "opts": ["\\(r>1{,}700\\)", "\\(1{,}300<r<1{,}700\\)", "\\(200<r<1{,}500\\)", "\\(r<1{,}300\\)"], "ans": "B"}, {"src": "ID da978ee6 &middot; Problem-Solving &amp; Data Analysis &middot; Hard", "skill": "Inference from sample statistics and margin of error", "type": "mc", "stem": "A researcher surveyed a random sample of 1,020 people from a certain city to estimate the percentage of people who support a recently announced proposal. From the survey, the researcher estimated that 86% of people from the city support this proposal, with an associated margin of error of 2.13%. The researcher repeated the survey with a random sample of people from the city that was double the original sample size. Assuming the margins of error were calculated in the same way, which of the following is true about the margin of error associated with the estimate from the larger sample?", "fig": null, "rat": "A larger sample size generally produces a smaller margin of error, so the new margin of error is less than 2.13%.", "opts": ["The margin of error is between 2.13% and 3.13%.", "The margin of error is between 4.13% and 5.13%.", "The margin of error is greater than 5.13%.", "The margin of error is less than 2.13%."], "ans": "D"}, {"src": "ID 97631565 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Inference from sample statistics and margin of error", "type": "mc", "stem": "Scott selected 20 employees at random from all 400 employees at a company. He found that 16 of the employees in this sample are enrolled in exactly three professional development courses this year. Based on Scott’s findings, which of the following is the best estimate of the number of employees at the company who are enrolled in exactly three professional development courses this year?", "fig": null, "rat": "The sample proportion is \\(\\tfrac{16}{20}=0.80\\). Applying it to all 400 employees: \\(0.80(400)=320\\).", "opts": ["4", "320", "380", "384"], "ans": "B"}, {"src": "ID f04d40b2 &middot; Problem-Solving &amp; Data Analysis &middot; Medium", "skill": "Inference from sample statistics and margin of error", "type": "mc", "stem": "From a population of 50,000 people, 1,000 were chosen at random and surveyed about a proposed piece of legislation. Based on the survey, it is estimated that 35% of people in the population support the legislation, with an associated margin of error of 3%. Based on these results, which of the following is a plausible value for the total number of people in the population who support the proposed legislation?", "fig": null, "rat": "Plausible percentages run from 32% to 38%, giving \\(50{,}000(0.32)=16{,}000\\) to \\(50{,}000(0.38)=19{,}000\\). Of the choices, only 16,750 lies in that interval.", "opts": ["350", "650", "16,750", "31,750"], "ans": "C"}, {"src": "ID 308084c5 &middot; Problem-Solving &amp; Data Analysis &middot; Hard", "skill": "Inference from sample statistics and margin of error", "type": "mc", "stem": "The results of two random samples of votes for a proposition are shown in the table. The samples were selected from the same population, and the margins of error were calculated using the same method. Which of the following is the most appropriate reason that the margin of error for sample A is greater than the margin of error for sample B?", "fig": null, "rat": "Sample size is what drives the margin of error here: a smaller sample generally gives a larger margin of error, so sample A having a smaller sample size explains it.", "figHTML": "<table class=\"data-table\"><tr><th>Sample</th><th>Percent in favor</th><th>Margin of error</th></tr><tr><th>A</th><td>52%</td><td>4.2%</td></tr><tr><th>B</th><td>48%</td><td>1.6%</td></tr></table>", "opts": ["Sample A had a smaller number of votes that could not be recorded.", "Sample A had a higher percent of favorable responses.", "Sample A had a larger sample size.", "Sample A had a smaller sample size."], "ans": "D"}, {"src": "ID 2c76bcce &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Inference from sample statistics and margin of error", "type": "mc", "stem": "A company designs and makes handbags. To estimate the mean weight of the handbags made by the company on a particular day, a sample of the handbags made by the company on that day was selected at random. Based on the sample, it is estimated that the mean weight of all handbags made by the company on that day is 27.8 ounces (oz), with an associated margin of error of 0.02 oz. Based on this estimate and associated margin of error, which of the following is the most plausible conclusion?", "fig": null, "rat": "The interval is \\(27.8\\pm0.02\\), so the plausible conclusion concerns the <i>mean</i> weight: it is between 27.78 oz and 27.82 oz.", "opts": ["The mean weight of all handbags made by the company on that day is between 27.78 oz and 27.82 oz.", "The actual weights of all handbags made by the company on that day are between 27.78 oz and 27.82 oz.", "The actual weights of all handbags from the sample are between 27.78 oz and 27.82 oz.", "The mean weight of all handbags made by the company on that day is 27.8 oz."], "ans": "A"}, {"src": "ID 9bedc4a0 &middot; Problem-Solving &amp; Data Analysis &middot; Medium", "skill": "Inference from sample statistics and margin of error", "type": "mc", "stem": "A company that produces socks wants to estimate the percent of the socks produced in a typical week that are defective. A random sample of 310 socks produced in a certain week were inspected. Based on the sample, it is estimated that 12% of all socks produced by the company in this week are defective, with an associated margin of error of 3.62%. Based on the estimate and associated margin of error, which of the following is the most appropriate conclusion about all socks produced by the company during this week?", "fig": null, "rat": "The plausible interval is \\(12\\%\\pm3.62\\%\\), that is, from 8.38% to 15.62%.", "opts": ["3.62% of the socks are defective.", "It is plausible that between 8.38% and 15.62% of the socks are defective.", "12% of the socks are defective.", "It is plausible that more than 15.62% of the socks are defective."], "ans": "B"}, {"src": "ID 916ffe9b &middot; Problem-Solving &amp; Data Analysis &middot; Hard", "skill": "Inference from sample statistics and margin of error", "type": "mc", "stem": "The table shows the results of a poll. A total of 803 voters selected at random were asked which candidate they would vote for in the upcoming election. According to the poll, if 6,424 people vote in the election, by how many votes would Angel Cruz be expected to win?", "fig": null, "rat": "The poll proportion for Cruz is \\(\\tfrac{483}{803}\\). Expected votes: \\(6{,}424\\left(\\tfrac{483}{803}\\right)=3{,}864\\), leaving \\(6{,}424-3{,}864=2{,}560\\) for the other candidate. The margin is \\(3{,}864-2{,}560=1{,}304\\).", "figHTML": "<table class=\"data-table\"><caption>Poll Results</caption><tr><th></th><th></th></tr><tr><th>Angel Cruz</th><td>483</td></tr><tr><th>Terry Smith</th><td>320</td></tr></table>", "opts": ["163", "1,304", "3,864", "5,621"], "ans": "B"}, {"src": "ID 8173f32b &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Inference from sample statistics and margin of error", "type": "mc", "stem": "An analyst collected data on the price of a carton of grape tomatoes at 30 locations selected at random in Utah. The mean price of a carton of grape tomatoes in Utah was estimated to be $4.23, with an associated margin of error of $0.08. Which of the following is a plausible statement about the mean price of a carton of grape tomatoes for all locations that sell this product in Utah?", "fig": null, "rat": "The plausible interval is \\(4.23\\pm0.08\\): between $4.15 and $4.31.", "opts": ["It is between $4.15 and $4.31.", "It is either less than $4.15 or greater than $4.31.", "It is less than $4.15.", "It is greater than $4.31."], "ans": "A"}, {"src": "ID 2bab1399 &middot; Problem-Solving &amp; Data Analysis &middot; Medium", "skill": "Inference from sample statistics and margin of error", "type": "mc", "stem": "A researcher is designing a study to investigate the average number of hours participants in a training course spend on a particular activity per day. The researcher will report an estimated average number of hours participants in the training course spend on this activity per day with an associated margin of error. The researcher is considering using a random sample of either 115 or 230 participants from the training course. Which of the following would be the most likely effect of using the larger random sample compared to the smaller random sample?", "fig": null, "rat": "Larger samples generally produce smaller margins of error, so the reported margin of error would be lower.", "opts": ["The reported margin of error would be lower.", "The reported margin of error would be higher.", "The reported average number of hours would be lower.", "The reported average number of hours would be higher."], "ans": "A"}, {"src": "ID affb2315 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "Inference from sample statistics and margin of error", "type": "mc", "stem": "There are 55 students in Spanish club. A sample of the Spanish club students was selected at random and asked whether they intend to enroll in a new study program. Of those surveyed, 20% responded that they intend to enroll in the study program. Based on this survey, which of the following is the best estimate of the total number of Spanish club students who intend to enroll in the study program?", "fig": null, "rat": "Applying the sample proportion to the whole club: \\(55(0.20)=11\\) students.", "opts": ["11", "20", "44", "55"], "ans": "A"}, {"src": "ID b82a943c &middot; Algebra &middot; Easy", "skill": "Linear equations in one variable", "type": "mc", "stem": "If \\(7x=28\\), what is the value of \\(8x\\)?", "fig": null, "rat": "Dividing gives \\(x=4\\), so \\(8x=8(4)=32\\).", "opts": ["21", "32", "168", "224"], "ans": "B"}, {"src": "ID 76f29fa5 &middot; Algebra &middot; Medium", "skill": "Linear equations in one variable", "type": "mc", "stem": "The cost to rent a commercial fishing boat from a certain company is $950 for the first 2 hours and an additional $50 per hour for each hour after the first 2 hours. If the total cost to rent the commercial fishing boat from the company for \\(t\\) hours, where \\(t>2\\), is $1,100, which equation represents this situation?", "fig": null, "rat": "The extra hours beyond the first two number \\(t-2\\), each costing $50, added to the base $950: \\(950+50(t-2)=1{,}100\\).", "opts": ["\\(950(t-2)+50t=1{,}100\\)", "\\(950(2t)+50t=1{,}100\\)", "\\(950+50(t-2)=1{,}100\\)", "\\(950+50(2t)=1{,}100\\)"], "ans": "C"}, {"src": "ID 8339793c &middot; Algebra &middot; Easy", "skill": "Linear equations in one variable", "type": "spr", "stem": "Nasir bought 9 storage bins that were each the same price. He used a coupon for $63 off the entire purchase. The cost for the entire purchase after using the coupon was $27. What was the original price, in dollars, for 1 storage bin?", "fig": null, "rat": "Before the coupon the purchase cost \\(27+63=\\$90\\). Divided among 9 bins: \\(90/9=\\$10\\) each.", "accepted": [10]}, {"src": "ID 0cb57740 &middot; Algebra &middot; Hard", "skill": "Linear equations in one variable", "type": "mc", "stem": "Each side of a 30-sided polygon has one of three lengths. The number of sides with length 8 centimeters (cm) is 5 times the number of sides \\(n\\) with length 3 cm. There are 6 sides with length 4 cm. Which equation must be true for the value of \\(n\\)?", "fig": null, "rat": "The three counts are \\(n\\) (3 cm), \\(5n\\) (8 cm), and 6 (4 cm), and they total 30 sides: \\(n+6+5n=30\\), which simplifies to \\(6n+6=30\\).", "opts": ["\\(5n+6=30\\)", "\\(6n+6=30\\)", "\\(8n+3n+4n=30\\)", "\\(8(5n)+3n+4(6)=30\\)"], "ans": "B"}, {"src": "ID 79cf8505 &middot; Algebra &middot; Medium", "skill": "Linear equations in one variable", "type": "spr", "stem": "A line segment that has a length of 115 centimeters (cm) is divided into three parts. One part is 47 cm long. The other two parts have lengths that are equal to each other. What is the length, in cm, of one of the other two parts of equal length?", "fig": null, "rat": "With each equal part \\(x\\): \\(47+2x=115\\), so \\(2x=68\\) and \\(x=34\\) cm.", "accepted": [34]}, {"src": "ID 771bd0ca &middot; Algebra &middot; Hard", "skill": "Linear equations in one variable", "type": "spr", "stem": "What value of \\(t\\) is the solution to the equation \\(5(t+3)-7(t+3)=38\\)?", "fig": null, "rat": "Combining like terms gives \\(-2(t+3)=38\\), so \\(t+3=-19\\) and \\(t=-22\\).", "accepted": [-22]}, {"src": "ID eac739b2 &middot; Algebra &middot; Easy", "skill": "Linear equations in one variable", "type": "mc", "stem": "If \\(4x+2=12\\), what is the value of \\(16x+8\\)?", "fig": null, "rat": "Multiplying both sides by 4 gives \\(16x+8=4(12)=48\\).", "opts": ["40", "48", "56", "60"], "ans": "B"}, {"src": "ID 153ee763 &middot; Algebra &middot; Hard", "skill": "Linear equations in one variable", "type": "mc", "stem": "In the equation \\(-3x+21px=84\\), \\(p\\) is a constant. The equation has no solution. What is the value of \\(p\\)?", "fig": null, "rat": "Factoring the left side gives \\(x(-3+21p)=84\\). This has no solution exactly when the coefficient is zero: \\(-3+21p=0\\), so \\(p=\\tfrac{1}{7}\\).", "opts": ["0", "\\(\\tfrac{1}{7}\\)", "\\(\\tfrac{4}{3}\\)", "4"], "ans": "B"}, {"src": "ID feb78194 &middot; Algebra &middot; Medium", "skill": "Linear equations in one variable", "type": "spr", "stem": "A museum rents tablets to visitors. The museum earns revenue of $14 for each tablet rented for the day. On Wednesday, the museum earned $406 in profit from renting tablets after paying daily expenses of $112. How many tablets did the museum rent on Wednesday? (profit = total revenue &minus; total expenses)", "fig": null, "rat": "With \\(x\\) tablets: \\(14x-112=406\\), so \\(14x=518\\) and \\(x=37\\) tablets.", "accepted": [37]}, {"src": "ID fa7a0164 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "One-variable data: distributions and measures of center and spread", "type": "mc", "stem": "The table shows the high and low temperatures in Houston, Texas, during a five-day period. What was the mean low temperature, in degrees Fahrenheit, during the five-day period?", "fig": null, "rat": "Sum of the low temperatures: \\(49+37+41+54+63=244\\). Mean: \\(244/5=48.8\\).", "figHTML": "<table class=\"data-table\"><caption>Temperatures in Houston, Texas (degrees Fahrenheit)</caption><tr><th></th><th>Monday</th><th>Tuesday</th><th>Wednesday</th><th>Thursday</th><th>Friday</th></tr><tr><th>High temperature</th><td>73</td><td>56</td><td>62</td><td>73</td><td>81</td></tr><tr><th>Low temperature</th><td>49</td><td>37</td><td>41</td><td>54</td><td>63</td></tr></table>", "opts": ["48.8", "49", "59", "59.1"], "ans": "A"}, {"src": "ID d73a67d7 &middot; Problem-Solving &amp; Data Analysis &middot; Medium", "skill": "One-variable data: distributions and measures of center and spread", "type": "mc", "stem": "Which of the following lists represents a data set with the smallest standard deviation?", "fig": null, "rat": "Standard deviation measures spread about the mean. In choice D, 53, 54, 54, 54, 55, every value differs from the mean of 54 by at most 1, the tightest clustering of the four choices.", "opts": ["51, 52, 54, 56, 57", "52, 52, 54, 56, 56", "52, 53, 54, 55, 56", "53, 54, 54, 54, 55"], "ans": "D"}, {"src": "ID 560fab82 &middot; Problem-Solving &amp; Data Analysis &middot; Medium", "skill": "One-variable data: distributions and measures of center and spread", "type": "spr", "stem": "The table shows the frequency of values in a data set. What is the minimum value of the data set?", "fig": null, "rat": "The minimum is the least value that actually occurs. The listed values are 19, 21, 23, and 25, and 19 occurs 7 times, so the minimum is 19.", "figHTML": "<table class=\"data-table\"><tr><th>Value</th><th>Frequency</th></tr><tr><th>19</th><td>7</td></tr><tr><th>21</th><td>1</td></tr><tr><th>23</th><td>7</td></tr><tr><th>25</th><td>4</td></tr></table>", "accepted": [19]}, {"src": "ID 7760c516 &middot; Problem-Solving &amp; Data Analysis &middot; Easy", "skill": "One-variable data: distributions and measures of center and spread", "type": "spr", "stem": "Each value in the data set shown represents the height, in centimeters, of a plant: 6, 10, 13, 2, 15, 22, 10, 4, 4, 4. What is the mean height, in centimeters, of these plants?", "fig": null, "rat": "The sum is \\(6+10+13+2+15+22+10+4+4+4=90\\), and there are 10 plants, so the mean is \\(90/10=9\\).", "accepted": [9]}, {"src": "ID 1142af44 &middot; Problem-Solving &amp; Data Analysis &middot; Hard", "skill": "One-variable data: distributions and measures of center and spread", "type": "mc", "stem": "The frequency distribution shown summarizes a set of data, where \\(a\\) is a positive integer. How much greater is the mean of the set of data than the median?", "fig": null, "rat": "The frequencies are symmetric about the middle value 3: values 1 and 5 both occur \\(a\\) times, and 2 and 4 both occur \\(2a\\) times. A symmetric distribution has equal mean and median, so the difference is 0.", "figHTML": "<table class=\"data-table\"><tr><th>Value</th><th>Frequency</th></tr><tr><th>1</th><td>\\(a\\)</td></tr><tr><th>2</th><td>\\(2a\\)</td></tr><tr><th>3</th><td>\\(3a\\)</td></tr><tr><th>4</th><td>\\(2a\\)</td></tr><tr><th>5</th><td>\\(a\\)</td></tr></table>", "opts": ["0", "1", "2", "3"], "ans": "A"}, {"src": "ID 52a8ef85 &middot; Algebra &middot; Easy", "skill": "Linear equations in two variables", "type": "mc", "stem": "The equation \\(40x+20y=160\\) represents the number of sweaters, \\(x\\), and number of shirts, \\(y\\), that Yesenia purchased for $160. If Yesenia purchased 2 sweaters, how many shirts did she purchase?", "fig": null, "rat": "Substituting \\(x=2\\): \\(80+20y=160\\), so \\(20y=80\\) and \\(y=4\\) shirts.", "opts": ["3", "4", "8", "40"], "ans": "B"}, {"src": "ID 98d3393a &middot; Algebra &middot; Hard", "skill": "Linear equations in two variables", "type": "mc", "stem": "Line \\(\\ell\\) in the xy-plane is perpendicular to the line with equation \\(x=2\\). What is the slope of line \\(\\ell\\)?", "fig": null, "rat": "The line \\(x=2\\) is vertical, so any line perpendicular to it is horizontal, and horizontal lines have slope 0.", "opts": ["0", "\\(-\\tfrac{1}{2}\\)", "\\(-2\\)", "The slope of line \\(\\ell\\) is undefined."], "ans": "A"}, {"src": "ID 0d1b1e35 &middot; Algebra &middot; Medium", "skill": "Linear equations in two variables", "type": "mc", "stem": "A batch of banana milkshakes consists of 4 cups of ice cream and 2 bananas and has 1,114 milligrams (mg) of calcium. There is 276 mg of calcium in 1 cup of the ice cream used to make this batch of milkshakes. How much calcium, in mg, is in 1 banana?", "fig": null, "rat": "The ice cream contributes \\(4(276)=1{,}104\\) mg. The two bananas supply \\(1{,}114-1{,}104=10\\) mg, so one banana has \\(10/2=5\\) mg.", "opts": ["5", "10", "419", "1,104"], "ans": "A"}, {"src": "ID 9aaf7786 &middot; Algebra &middot; Hard", "skill": "Linear equations in two variables", "type": "spr", "stem": "In the xy-plane, line \\(p\\) has a slope of \\(-\\tfrac{5}{3}\\) and an x-intercept of \\((-6,0)\\). What is the y-coordinate of the y-intercept of line \\(p\\)?", "fig": null, "rat": "Using \\(y=mx+b\\) with the point \\((-6,0)\\): \\(0=-\\tfrac53(-6)+b=10+b\\), so \\(b=-10\\).", "accepted": [-10]}, {"src": "ID ca452900 &middot; Algebra &middot; Medium", "skill": "Linear equations in two variables", "type": "spr", "stem": "What is the slope of the graph of \\(y=\\tfrac{5x}{13}-23\\) in the xy-plane?", "fig": null, "rat": "Written as \\(y=\\left(\\tfrac{5}{13}\\right)x-23\\), the slope is the coefficient of \\(x\\): \\(\\tfrac{5}{13}\\approx.3846\\).", "accepted": [0.38461538461538464, 0.3846, 0.385]}], "LESSON_DEFS": [{"id": "lesson-lin1", "title": "Linear Equations (One Variable)", "sub": "Solving, no-solution conditions &amp; real-world linear setups", "ids": [38, 70, 71, 89, 103, 121, 136, 138, 333, 334, 335, 336, 337, 338, 339, 340, 341, 33, 50, 55, 76, 85], "n": 22, "min": 35, "time": 2100}, {"id": "lesson-lin2", "title": "Linear Equations (Two Variables) &amp; Slope", "sub": "Slopes, intercepts, perpendicular lines &amp; two-variable models", "ids": [40, 87, 107, 118, 128, 133, 134, 142, 143, 347, 348, 349, 350, 351, 46, 48, 61, 105, 111, 124, 125, 130], "n": 22, "min": 35, "time": 2100}, {"id": "lesson-lin-fn", "title": "Linear Functions &amp; Models", "sub": "Function evaluation, intercepts &amp; rate interpretation", "ids": [132, 144, 219, 311, 312, 313, 314, 315, 30, 36, 37, 60, 63, 101, 104, 106, 119, 139, 307, 308, 309, 310], "n": 22, "min": 35, "time": 2100}, {"id": "lesson-sys", "title": "Systems of Linear Equations", 